// Passagens citadas nos fatos: texto integral e leitura ao lado.
// Texto biblico: traducao de Joao Ferreira de Almeida (dominio publico), obtida via bible-api.com.
// Fontes nao biblicas: trechos em traducao livre, assinalados como tal.
window.JC = window.JC || {};

window.JC.passagens = {
  "Mt 2": {
    titulo: "Mateus 2",
    tipo: "biblia",
    versos: [{c:2,v:1,t:"Tendo, pois, nascido Jesus em Belém da Judéia, no tempo do rei Herodes, eis que vieram do oriente a Jerusalém uns magos que perguntavam:"},{c:2,v:2,t:"Onde está aquele que é nascido rei dos judeus? pois do oriente vimos a sua estrela e viemos adorá-lo."},{c:2,v:3,t:"O rei Herodes, ouvindo isso, perturbou-se, e com ele toda a Jerusalém;"},{c:2,v:4,t:"e, reunindo todos os principais sacerdotes e os escribas do povo, perguntava-lhes onde havia de nascer o Cristo."},{c:2,v:5,t:"Responderam-lhe eles: Em Belém da Judéia; pois assim está escrito pelo profeta:"},{c:2,v:6,t:"E tu, Belém, terra de Judá, de modo nenhum és a menor entre as principais cidades de Judá; porque de ti sairá o Guia que há de apascentar o meu povo de Israel."},{c:2,v:7,t:"Então Herodes chamou secretamente os magos, e deles inquiriu com precisão acerca do tempo em que a estrela aparecera;"},{c:2,v:8,t:"e enviando-os a Belém, disse-lhes: Ide, e perguntai diligentemente pelo menino; e, quando o achardes, participai-mo, para que também eu vá e o adore."},{c:2,v:9,t:"Tendo eles, pois, ouvido o rei, partiram; e eis que a estrela que tinham visto quando no oriente ia adiante deles, até que, chegando, se deteve sobre o lugar onde estava o menino."},{c:2,v:10,t:"Ao verem eles a estrela, regozijaram-se com grande alegria."},{c:2,v:11,t:"E entrando na casa, viram o menino com Maria sua mãe e, prostrando-se, o adoraram; e abrindo os seus tesouros, ofertaram-lhe dádivas: ouro incenso e mirra."},{c:2,v:12,t:"Ora, sendo por divina revelação avisados em sonhos para não voltarem a Herodes, regressaram à sua terra por outro caminho."},{c:2,v:13,t:"E, havendo eles se retirado, eis que um anjo do Senhor apareceu a José em sonho, dizendo: Levanta-te, toma o menino e sua mãe, foge para o Egito, e ali fica até que eu te fale; porque Herodes há de procurar o menino para o matar."},{c:2,v:14,t:"Levantou-se, pois, tomou de noite o menino e sua mãe, e partiu para o Egito."},{c:2,v:15,t:"e lá ficou até a morte de Herodes, para que se cumprisse o que fora dito da parte do Senhor pelo profeta: Do Egito chamei o meu Filho."},{c:2,v:16,t:"Então Herodes, vendo que fora iludido pelos magos, irou-se grandemente e mandou matar todos os meninos de dois anos para baixo que havia em Belém, e em todos os seus arredores, segundo o tempo que com precisão inquirira dos magos."},{c:2,v:17,t:"Cumpriu-se então o que fora dito pelo profeta Jeremias:"},{c:2,v:18,t:"Em Ramá se ouviu uma voz, lamentação e grande pranto: Raquel chorando os seus filhos, e não querendo ser consolada, porque eles já não existem."},{c:2,v:19,t:"Mas tendo morrido Herodes, eis que um anjo do Senhor apareceu em sonho a José no Egito,"},{c:2,v:20,t:"dizendo: Levanta-te, toma o menino e sua mãe e vai para a terra de Israel; porque já morreram os que procuravam a morte do menino."},{c:2,v:21,t:"Então ele se levantou, tomou o menino e sua mãe e foi para a terra de Israel."},{c:2,v:22,t:"Ouvindo, porém, que Arquelau reinava na Judéia em lugar de seu pai Herodes, temeu ir para lá; mas avisado em sonho por divina revelação, retirou-se para as regiões da Galiléia,"},{c:2,v:23,t:"e foi habitar numa cidade chamada Nazaré; para que se cumprisse o que fora dito pelos profetas: Ele será chamado nazareno."}],
    comentario: "O capítulo inteiro da infância segundo Mateus: magos, fuga para o Egito, matança dos inocentes e instalação em Nazaré. Cada episódio é fechado por uma citação do Antigo Testamento — a estrutura mostra que o evangelista está lendo a vida de Jesus com a gramática do Êxodo, em que um rei mata crianças e o escolhido escapa."
  },
  "Jo 2,20": {
    titulo: "João 2,20",
    tipo: "biblia",
    versos: [{c:2,v:20,t:"Disseram, pois, os judeus: Em quarenta e seis anos foi edificado este santuário, e tu o levantarás em três dias?"}],
    comentario: "A frase dos interlocutores — quarenta e seis anos de obra no Templo — é a âncora cronológica mais usada dos Evangelhos: contada a partir do início da reforma herodiana (c. 19 a.C.), leva ao ano 28 d.C. Note que eles entendem literalmente o que João explica como referência ao corpo de Jesus."
  },
  "Lc 2,1-2": {
    titulo: "Lucas 2,1-2",
    tipo: "biblia",
    versos: [{c:2,v:1,t:"Naqueles dias saiu um decreto da parte de César Augusto, para que todo o mundo fosse recenseado."},{c:2,v:2,t:"Este primeiro recenseamento foi feito quando Quirínio era governador da Síria."}],
    comentario: "Dois versículos que criaram séculos de debate. Lucas liga o nascimento ao recenseamento de Quirino, documentado em 6 d.C., mas Mateus o situa sob Herodes, morto em 4 a.C. As saídas propostas (um censo anterior, um mandato anterior de Quirino, outra tradução do versículo 2) não convencem a maioria dos historiadores."
  },
  "Lc 3,1": {
    titulo: "Lucas 3,1",
    tipo: "biblia",
    versos: [{c:3,v:1,t:"No décimo quinto ano do reinado de Tibério César, sendo Pôncio Pilatos governador da Judéia, Herodes tetrarca da Galiléia, seu irmão Filipe tetrarca da região da Ituréia e de Traconites, e Lisânias tetrarca de Abilene,"}],
    comentario: "A única sincronia explícita entre a narrativa cristã e a cronologia romana: décimo quinto ano de Tibério, Pilatos na Judeia, Antipas na Galileia, Anás e Caifás no sumo sacerdócio. Dependendo do calendário adotado para contar o reinado, aponta para 27–29 d.C. — base para datar o ministério e, por consequência, a crucificação."
  },
  "Mt 26,57": {
    titulo: "Mateus 26,57",
    tipo: "biblia",
    versos: [{c:26,v:57,t:"Aqueles que prenderam a Jesus levaram-no à presença do sumo sacerdote Caifás, onde os escribas e os anciãos estavam reunidos."}],
    comentario: "Jesus é levado a Caifás, onde escribas e anciãos estavam reunidos. Mateus chama a reunião de sessão do Sinédrio; o procedimento noturno, na véspera de festa e sem intervalo entre sentença e execução, viola regras que a Mishná fixaria depois — daí a leitura de que houve uma audiência informal de notáveis, não um julgamento formal."
  },
  "Jo 11,49-50": {
    titulo: "João 11,49-50",
    tipo: "biblia",
    versos: [{c:11,v:49,t:"Um deles, porém, chamado Caifás, que era sumo sacerdote naquele ano, disse-lhes: Vós nada sabeis,"},{c:11,v:50,t:"nem considerais que vos convém que morra um só homem pelo povo, e que não pereça a nação toda."}],
    comentario: "A frase de Caifás — convém que um homem morra pelo povo — é apresentada por João como profecia involuntária. Historicamente, descreve com precisão o cálculo de quem administrava Jerusalém sob ocupação romana durante a Páscoa: evitar tumulto a qualquer custo."
  },
  "Lc 1,26-38": {
    titulo: "Lucas 1,26-38",
    tipo: "biblia",
    versos: [{c:1,v:26,t:"Ora, no sexto mês, foi o anjo Gabriel enviado por Deus a uma cidade da Galiléia, chamada Nazaré,"},{c:1,v:27,t:"a uma virgem desposada com um varão cujo nome era José, da casa de Davi; e o nome da virgem era Maria."},{c:1,v:28,t:"E, entrando o anjo onde ela estava disse: Salve, agraciada; o Senhor é contigo."},{c:1,v:29,t:"Ela, porém, ao ouvir estas palavras, turbou-se muito e pôs-se a pensar que saudação seria essa."},{c:1,v:30,t:"Disse-lhe então o anjo: Não temas, Maria; pois achaste graça diante de Deus."},{c:1,v:31,t:"Eis que conceberás e darás à luz um filho, ao qual porás o nome de Jesus."},{c:1,v:32,t:"Este será grande e será chamado filho do Altíssimo; o Senhor Deus lhe dará o trono de Davi seu pai;"},{c:1,v:33,t:"e reinará eternamente sobre a casa de Jacó, e o seu reino não terá fim."},{c:1,v:34,t:"Então Maria perguntou ao anjo: Como se fará isso, uma vez que não conheço varão?"},{c:1,v:35,t:"Respondeu-lhe o anjo: Virá sobre ti o Espírito Santo, e o poder do Altíssimo te cobrirá com a sua sombra; por isso o que há de nascer será chamado santo, Filho de Deus."},{c:1,v:36,t:"Eis que também Isabel, tua parenta concebeu um filho em sua velhice; e é este o sexto mês para aquela que era chamada estéril;"},{c:1,v:37,t:"porque para Deus nada será impossível."},{c:1,v:38,t:"Disse então Maria. Eis aqui a serva do Senhor; cumpra-se em mim segundo a tua palavra. E o anjo ausentou-se dela."}],
    comentario: "A Anunciação. O verbo da saudação é de alegria festiva, não cumprimento comum; a resposta de Maria é uma objeção prática, e a explicação do anjo evita biologia e recorre à imagem da nuvem que cobria a tenda do encontro no Êxodo. É deste texto, e não do Natal, que vem a festa de 25 de março."
  },
  "Mt 1,18-25": {
    titulo: "Mateus 1,18-25",
    tipo: "biblia",
    versos: [{c:1,v:18,t:"Ora, o nascimento de Jesus Cristo foi assim: Estando Maria, sua mãe, desposada com José, antes de se ajuntarem, ela se achou ter concebido do Espírito Santo."},{c:1,v:19,t:"E como José, seu esposo, era justo, e não a queria infamar, intentou deixá-la secretamente."},{c:1,v:20,t:"E, projetando ele isso, eis que em sonho lhe apareceu um anjo do Senhor, dizendo: José, filho de Davi, não temas receber a Maria, tua mulher, pois o que nela se gerou é do Espírito Santo;"},{c:1,v:21,t:"ela dará à luz um filho, a quem chamarás JESUS; porque ele salvará o seu povo dos seus pecados."},{c:1,v:22,t:"Ora, tudo isso aconteceu para que se cumprisse o que fora dito da parte do Senhor pelo profeta:"},{c:1,v:23,t:"Eis que a virgem conceberá e dará à luz um filho, o qual será chamado EMANUEL, que traduzido é: Deus conosco."},{c:1,v:24,t:"E José, tendo despertado do sono, fez como o anjo do Senhor lhe ordenara, e recebeu sua mulher;"},{c:1,v:25,t:"e não a conheceu enquanto ela não deu à luz um filho; e pôs-lhe o nome de JESUS."}],
    comentario: "A mesma notícia do ponto de vista de José, e o problema aqui é jurídico: o que fazer com uma noiva grávida. Ao assumir a criança e dar-lhe o nome, ele a insere legalmente na linhagem de Davi. A citação de Isaías 7,14 usa a tradução grega parthenos (virgem) para o hebraico almah (jovem) — o centro da divergência judaico-cristã."
  },
  "Lc 1,39-56": {
    titulo: "Lucas 1,39-56",
    tipo: "biblia",
    versos: [{c:1,v:39,t:"Naqueles dias levantou-se Maria, foi apressadamente à região montanhosa, a uma cidade de Judá,"},{c:1,v:40,t:"entrou em casa de Zacarias e saudou a Isabel."},{c:1,v:41,t:"Ao ouvir Isabel a saudação de Maria, saltou a criancinha no seu ventre, e Isabel ficou cheia do Espírito Santo,"},{c:1,v:42,t:"e exclamou em alta voz: Bendita és tu entre as mulheres, e bendito é o fruto do teu ventre!"},{c:1,v:43,t:"E donde me provém isto, que venha visitar-me a mãe do meu Senhor?"},{c:1,v:44,t:"Pois logo que me soou aos ouvidos a voz da tua saudação, a criancinha saltou de alegria dentro de mim."},{c:1,v:45,t:"Bem-aventurada aquela que creu que se hão de cumprir as coisas que da parte do Senhor lhe foram ditas."},{c:1,v:46,t:"Disse então Maria: A minha alma engrandece ao Senhor,"},{c:1,v:47,t:"e o meu espírito exulta em Deus meu Salvador;"},{c:1,v:48,t:"porque atentou na condição humilde de sua serva. Desde agora, pois, todas as gerações me chamarão bem-aventurada,"},{c:1,v:49,t:"porque o Poderoso me fez grandes coisas; e santo é o seu nome."},{c:1,v:50,t:"E a sua misericórdia vai de geração em geração sobre os que o temem."},{c:1,v:51,t:"Com o seu braço manifestou poder; dissipou os que eram soberbos nos pensamentos de seus corações;"},{c:1,v:52,t:"depôs dos tronos os poderosos, e elevou os humildes."},{c:1,v:53,t:"Aos famintos encheu de bens, e vazios despediu os ricos."},{c:1,v:54,t:"Auxiliou a Isabel, seu servo, lembrando-se de misericórdia"},{c:1,v:55,t:"(como falou a nossos pais) para com Abraão e a sua descendência para sempre."},{c:1,v:56,t:"E Maria ficou com ela cerca de três meses; e depois voltou para sua casa."}],
    comentario: "A Visitação e o Magnificat. O cântico é um mosaico de citações do Antigo Testamento, muito próximo do cântico de Ana em 1Samuel 2, e seus verbos estão no passado, como se a inversão social já tivesse acontecido. Rezado diariamente nas Vésperas, foi proibido em público por regimes autoritários no século XX."
  },
  "Lc 1,57-80": {
    titulo: "Lucas 1,57-80",
    tipo: "biblia",
    versos: [{c:1,v:57,t:"Ora, completou-se para Isabel o tempo de dar à luz, e teve um filho."},{c:1,v:58,t:"Ouviram seus vizinhos e parentes que o Senhor lhe multiplicara a sua misericórdia, e se alegravam com ela."},{c:1,v:59,t:"Sucedeu, pois, no oitavo dia, que vieram circuncidar o menino; e queriam dar-lhe o nome de seu pai, Zacarias."},{c:1,v:60,t:"Respondeu, porém, sua mãe: De modo nenhum, mas será chamado João."},{c:1,v:61,t:"Ao que lhe disseram: Ninguém há na tua parentela que se chame por este nome."},{c:1,v:62,t:"E perguntaram por acenos ao pai como queria que se chamasse."},{c:1,v:63,t:"E pedindo ele uma tabuinha, escreveu: Seu nome é João. E todos se admiraram."},{c:1,v:64,t:"Imediatamente a boca se lhe abriu, e a língua se lhe soltou; louvando a Deus."},{c:1,v:65,t:"Então veio temor sobre todos os seus vizinhos; e em toda a região montanhosa da Judéia foram divulgadas todas estas coisas."},{c:1,v:66,t:"E todos os que delas souberam as guardavam no coração, dizendo: Que virá a ser, então, este menino? Pois a mão do Senhor estava com ele."},{c:1,v:67,t:"Zacarias, seu pai, ficou cheio do Espírito Santo e profetizou, dizendo:"},{c:1,v:68,t:"Bendito, seja o Senhor Deus de Israel, porque visitou e remiu o seu povo,"},{c:1,v:69,t:"e para nós fez surgir uma salvação poderosa na casa de Davi, seu servo;"},{c:1,v:70,t:"assim como desde os tempos antigos tem anunciado pela boca dos seus santos profetas;"},{c:1,v:71,t:"para nos livrar dos nossos inimigos e da mão de todos os que nos odeiam;"},{c:1,v:72,t:"para usar de misericórdia com nossos pais, e lembrar-se do seu santo pacto"},{c:1,v:73,t:"e do juramento que fez a Abrão, nosso pai,"},{c:1,v:74,t:"de conceder-nos que, libertados da mão de nossos inimigos, o servíssemos sem temor,"},{c:1,v:75,t:"em santidade e justiça perante ele, todos os dias da nossa vida."},{c:1,v:76,t:"E tu, menino, serás chamado profeta do Altíssimo, porque irás ante a face do Senhor, a preparar os seus caminhos;"},{c:1,v:77,t:"para dar ao seu povo conhecimento da salvação, na remissão dos seus pecados,"},{c:1,v:78,t:"graças à entrenhável misericórdia do nosso Deus, pela qual nos há de visitar a aurora lá do alto,"},{c:1,v:79,t:"para alumiar aos que jazem nas trevas e na sombra da morte, a fim de dirigir os nossos pés no caminho da paz."},{c:1,v:80,t:"Ora, o menino crescia, e se robustecia em espírito; e habitava nos desertos até o dia da sua manifestação a Israel."}],
    comentario: "O nascimento de João e o Benedictus de Zacarias, que amarra a história ao arco de Israel: aliança, juramento aos pais, libertação. O fecho — o menino vivia nos desertos — alimenta a hipótese, plausível e indemonstrável, de contato com a comunidade essênia de Qumran."
  },
  "Lc 2,1-20": {
    titulo: "Lucas 2,1-20",
    tipo: "biblia",
    versos: [{c:2,v:1,t:"Naqueles dias saiu um decreto da parte de César Augusto, para que todo o mundo fosse recenseado."},{c:2,v:2,t:"Este primeiro recenseamento foi feito quando Quirínio era governador da Síria."},{c:2,v:3,t:"E todos iam alistar-se, cada um à sua própria cidade."},{c:2,v:4,t:"Subiu também José, da Galiléia, da cidade de Nazaré, à cidade de Davi, chamada Belém, porque era da casa e família de Davi,"},{c:2,v:5,t:"a fim de alistar-se com Maria, sua esposa, que estava grávida."},{c:2,v:6,t:"Enquanto estavam ali, chegou o tempo em que ela havia de dar à luz,"},{c:2,v:7,t:"e teve a seu filho primogênito; envolveu-o em faixas e o deitou em uma manjedoura, porque não havia lugar para eles na estalagem."},{c:2,v:8,t:"Ora, havia naquela mesma região pastores que estavam no campo, e guardavam durante as vigílias da noite o seu rebanho."},{c:2,v:9,t:"E um anjo do Senhor apareceu-lhes, e a glória do Senhor os cercou de resplendor; pelo que se encheram de grande temor."},{c:2,v:10,t:"O anjo, porém, lhes disse: Não temais, porquanto vos trago novas de grande alegria que o será para todo o povo:"},{c:2,v:11,t:"É que vos nasceu hoje, na cidade de Davi, o Salvador, que é Cristo, o Senhor."},{c:2,v:12,t:"E isto vos será por sinal: Achareis um menino envolto em faixas, e deitado em uma manjedoura."},{c:2,v:13,t:"Então, de repente, apareceu junto ao anjo grande multidão da milícia celestial, louvando a Deus e dizendo:"},{c:2,v:14,t:"Glória a Deus nas maiores alturas, e paz na terra entre os homens de boa vontade."},{c:2,v:15,t:"E logo que os anjos se retiraram deles para o céu, diziam os pastores uns aos outros: Vamos já até Belém, e vejamos isso que aconteceu e que o Senhor nos deu a conhecer."},{c:2,v:16,t:"Foram, pois, a toda a pressa, e acharam Maria e José, e o menino deitado na manjedoura;"},{c:2,v:17,t:"e, vendo-o, divulgaram a palavra que acerca do menino lhes fora dita;"},{c:2,v:18,t:"e todos os que a ouviram se admiravam do que os pastores lhes diziam."},{c:2,v:19,t:"Maria, porém, guardava todas estas coisas, meditando-as em seu coração."},{c:2,v:20,t:"E voltaram os pastores, glorificando e louvando a Deus por tudo o que tinham ouvido e visto, como lhes fora dito."}],
    comentario: "O relato do nascimento em Lucas: censo, viagem, manjedoura, pastores e anjos. A palavra traduzida por estalagem (kataluma) é a mesma que Lucas usa depois para a sala da Última Ceia; nada no texto fala em estábulo, gruta, boi ou burro — tudo isso vem de tradições posteriores."
  },
  "Mt 1,18–2,12": {
    titulo: "Mateus 1,18–2,12",
    tipo: "biblia",
    versos: [{c:1,v:18,t:"Ora, o nascimento de Jesus Cristo foi assim: Estando Maria, sua mãe, desposada com José, antes de se ajuntarem, ela se achou ter concebido do Espírito Santo."},{c:1,v:19,t:"E como José, seu esposo, era justo, e não a queria infamar, intentou deixá-la secretamente."},{c:1,v:20,t:"E, projetando ele isso, eis que em sonho lhe apareceu um anjo do Senhor, dizendo: José, filho de Davi, não temas receber a Maria, tua mulher, pois o que nela se gerou é do Espírito Santo;"},{c:1,v:21,t:"ela dará à luz um filho, a quem chamarás JESUS; porque ele salvará o seu povo dos seus pecados."},{c:1,v:22,t:"Ora, tudo isso aconteceu para que se cumprisse o que fora dito da parte do Senhor pelo profeta:"},{c:1,v:23,t:"Eis que a virgem conceberá e dará à luz um filho, o qual será chamado EMANUEL, que traduzido é: Deus conosco."},{c:1,v:24,t:"E José, tendo despertado do sono, fez como o anjo do Senhor lhe ordenara, e recebeu sua mulher;"},{c:1,v:25,t:"e não a conheceu enquanto ela não deu à luz um filho; e pôs-lhe o nome de JESUS."},{c:2,v:1,t:"Tendo, pois, nascido Jesus em Belém da Judéia, no tempo do rei Herodes, eis que vieram do oriente a Jerusalém uns magos que perguntavam:"},{c:2,v:2,t:"Onde está aquele que é nascido rei dos judeus? pois do oriente vimos a sua estrela e viemos adorá-lo."},{c:2,v:3,t:"O rei Herodes, ouvindo isso, perturbou-se, e com ele toda a Jerusalém;"},{c:2,v:4,t:"e, reunindo todos os principais sacerdotes e os escribas do povo, perguntava-lhes onde havia de nascer o Cristo."},{c:2,v:5,t:"Responderam-lhe eles: Em Belém da Judéia; pois assim está escrito pelo profeta:"},{c:2,v:6,t:"E tu, Belém, terra de Judá, de modo nenhum és a menor entre as principais cidades de Judá; porque de ti sairá o Guia que há de apascentar o meu povo de Israel."},{c:2,v:7,t:"Então Herodes chamou secretamente os magos, e deles inquiriu com precisão acerca do tempo em que a estrela aparecera;"},{c:2,v:8,t:"e enviando-os a Belém, disse-lhes: Ide, e perguntai diligentemente pelo menino; e, quando o achardes, participai-mo, para que também eu vá e o adore."},{c:2,v:9,t:"Tendo eles, pois, ouvido o rei, partiram; e eis que a estrela que tinham visto quando no oriente ia adiante deles, até que, chegando, se deteve sobre o lugar onde estava o menino."},{c:2,v:10,t:"Ao verem eles a estrela, regozijaram-se com grande alegria."},{c:2,v:11,t:"E entrando na casa, viram o menino com Maria sua mãe e, prostrando-se, o adoraram; e abrindo os seus tesouros, ofertaram-lhe dádivas: ouro incenso e mirra."},{c:2,v:12,t:"Ora, sendo por divina revelação avisados em sonhos para não voltarem a Herodes, regressaram à sua terra por outro caminho."}],
    comentario: "A sequência de Mateus, do anúncio a José à visita dos magos. Repare que não há viagem: a família parece já morar em Belém, e a casa é mencionada explicitamente. É uma das divergências claras em relação a Lucas, para quem a família é de Nazaré e vai a Belém por causa do censo."
  },
  "Lc 2,8-20": {
    titulo: "Lucas 2,8-20",
    tipo: "biblia",
    versos: [{c:2,v:8,t:"Ora, havia naquela mesma região pastores que estavam no campo, e guardavam durante as vigílias da noite o seu rebanho."},{c:2,v:9,t:"E um anjo do Senhor apareceu-lhes, e a glória do Senhor os cercou de resplendor; pelo que se encheram de grande temor."},{c:2,v:10,t:"O anjo, porém, lhes disse: Não temais, porquanto vos trago novas de grande alegria que o será para todo o povo:"},{c:2,v:11,t:"É que vos nasceu hoje, na cidade de Davi, o Salvador, que é Cristo, o Senhor."},{c:2,v:12,t:"E isto vos será por sinal: Achareis um menino envolto em faixas, e deitado em uma manjedoura."},{c:2,v:13,t:"Então, de repente, apareceu junto ao anjo grande multidão da milícia celestial, louvando a Deus e dizendo:"},{c:2,v:14,t:"Glória a Deus nas maiores alturas, e paz na terra entre os homens de boa vontade."},{c:2,v:15,t:"E logo que os anjos se retiraram deles para o céu, diziam os pastores uns aos outros: Vamos já até Belém, e vejamos isso que aconteceu e que o Senhor nos deu a conhecer."},{c:2,v:16,t:"Foram, pois, a toda a pressa, e acharam Maria e José, e o menino deitado na manjedoura;"},{c:2,v:17,t:"e, vendo-o, divulgaram a palavra que acerca do menino lhes fora dita;"},{c:2,v:18,t:"e todos os que a ouviram se admiravam do que os pastores lhes diziam."},{c:2,v:19,t:"Maria, porém, guardava todas estas coisas, meditando-as em seu coração."},{c:2,v:20,t:"E voltaram os pastores, glorificando e louvando a Deus por tudo o que tinham ouvido e visto, como lhes fora dito."}],
    comentario: "O anúncio aos pastores. A linguagem — Salvador, Senhor, boas novas, paz — era vocabulário de propaganda imperial, aplicado aqui a um recém-nascido deitado numa manjedoura. A escolha dos destinatários é o argumento: trabalhadores itinerantes cujo testemunho tinha pouco valor legal."
  },
  "Lc 2,22-38": {
    titulo: "Lucas 2,22-38",
    tipo: "biblia",
    versos: [{c:2,v:22,t:"Terminados os dias da purificação, segundo a lei de Moisés, levaram-no a Jerusalém, para apresentá-lo ao Senhor"},{c:2,v:23,t:"(conforme está escrito na lei do Senhor: Todo primogênito será consagrado ao Senhor),"},{c:2,v:24,t:"e para oferecerem um sacrifício segundo o disposto na lei do Senhor: um par de rolas, ou dois pombinhos."},{c:2,v:25,t:"Ora, havia em Jerusalém um homem cujo nome era Simeão; e este homem, justo e temente a Deus, esperava a consolação de Israel; e o Espírito Santo estava sobre ele."},{c:2,v:26,t:"E lhe fora revelado pelo Espírito Santo que ele não morreria antes de ver o Cristo do Senhor."},{c:2,v:27,t:"Assim pelo Espírito foi ao templo; e quando os pais trouxeram o menino Jesus, para fazerem por ele segundo o costume da lei,"},{c:2,v:28,t:"Simeão o tomou em seus braços, e louvou a Deus, e disse:"},{c:2,v:29,t:"Agora, Senhor, despedes em paz o teu servo, segundo a tua palavra;"},{c:2,v:30,t:"pois os meus olhos já viram a tua salvação,"},{c:2,v:31,t:"a qual tu preparaste ante a face de todos os povos;"},{c:2,v:32,t:"luz para revelação aos gentios, e para glória do teu povo Israel."},{c:2,v:33,t:"Enquanto isso, seu pai e sua mãe se admiravam das coisas que deles se diziam."},{c:2,v:34,t:"E Simeão os abençoou, e disse a Maria, mãe do menino: Eis que este é posto para queda e para levantamento de muitos em Israel, e para ser alvo de contradição,"},{c:2,v:35,t:"sim, e uma espada traspassará a tua própria alma, para que se manifestem os pensamentos de muitos corações."},{c:2,v:36,t:"Havia também uma profetisa, Ana, filha de Fanuel, da tribo de Aser. Era já avançada em idade, tendo vivido com o marido sete anos desde a sua virgindade;"},{c:2,v:37,t:"e era viúva, de quase oitenta e quatro anos. Não se afastava do templo, servindo a Deus noite e dia em jejuns e orações."},{c:2,v:38,t:"Chegando ela na mesma hora, deu graças a Deus, e falou a respeito do menino a todos os que esperavam a redenção de Jerusalém."}],
    comentario: "A apresentação no Templo, com o cântico de Simeão e o testemunho da profetisa Ana. A oferta de duas aves é a alternativa prevista para quem não podia pagar um cordeiro — indício social preservado no texto. A profecia da espada que atravessará a alma da mãe fundou a devoção às Dores de Maria."
  },
  "Lv 12,8": {
    titulo: "Levítico 12,8",
    tipo: "biblia",
    versos: [{c:12,v:8,t:"Mas, se as suas posses não bastarem para um cordeiro, então tomará duas rolas, ou dois pombinhos: um para o holocausto e outro para a oferta pelo pecado; assim o sacerdote fará expiação por ela, e ela será limpa."}],
    comentario: "A prescrição levítica citada por Lucas: quem não puder oferecer um cordeiro, oferece duas rolas ou dois pombinhos. Serve como nota de rodapé econômica ao relato da apresentação — a família de Jesus se enquadra na cláusula dos pobres."
  },
  "Mt 2,1-12": {
    titulo: "Mateus 2,1-12",
    tipo: "biblia",
    versos: [{c:2,v:1,t:"Tendo, pois, nascido Jesus em Belém da Judéia, no tempo do rei Herodes, eis que vieram do oriente a Jerusalém uns magos que perguntavam:"},{c:2,v:2,t:"Onde está aquele que é nascido rei dos judeus? pois do oriente vimos a sua estrela e viemos adorá-lo."},{c:2,v:3,t:"O rei Herodes, ouvindo isso, perturbou-se, e com ele toda a Jerusalém;"},{c:2,v:4,t:"e, reunindo todos os principais sacerdotes e os escribas do povo, perguntava-lhes onde havia de nascer o Cristo."},{c:2,v:5,t:"Responderam-lhe eles: Em Belém da Judéia; pois assim está escrito pelo profeta:"},{c:2,v:6,t:"E tu, Belém, terra de Judá, de modo nenhum és a menor entre as principais cidades de Judá; porque de ti sairá o Guia que há de apascentar o meu povo de Israel."},{c:2,v:7,t:"Então Herodes chamou secretamente os magos, e deles inquiriu com precisão acerca do tempo em que a estrela aparecera;"},{c:2,v:8,t:"e enviando-os a Belém, disse-lhes: Ide, e perguntai diligentemente pelo menino; e, quando o achardes, participai-mo, para que também eu vá e o adore."},{c:2,v:9,t:"Tendo eles, pois, ouvido o rei, partiram; e eis que a estrela que tinham visto quando no oriente ia adiante deles, até que, chegando, se deteve sobre o lugar onde estava o menino."},{c:2,v:10,t:"Ao verem eles a estrela, regozijaram-se com grande alegria."},{c:2,v:11,t:"E entrando na casa, viram o menino com Maria sua mãe e, prostrando-se, o adoraram; e abrindo os seus tesouros, ofertaram-lhe dádivas: ouro incenso e mirra."},{c:2,v:12,t:"Ora, sendo por divina revelação avisados em sonhos para não voltarem a Herodes, regressaram à sua terra por outro caminho."}],
    comentario: "Os magos. O texto não diz quantos eram, não os chama de reis e não lhes dá nomes: tudo isso é tradição posterior. O astro que se move, para e paira sobre uma casa comporta-se como sinal narrativo, não como corpo celeste — o que não impediu séculos de hipóteses astronômicas."
  },
  "Mt 2,13-23": {
    titulo: "Mateus 2,13-23",
    tipo: "biblia",
    versos: [{c:2,v:13,t:"E, havendo eles se retirado, eis que um anjo do Senhor apareceu a José em sonho, dizendo: Levanta-te, toma o menino e sua mãe, foge para o Egito, e ali fica até que eu te fale; porque Herodes há de procurar o menino para o matar."},{c:2,v:14,t:"Levantou-se, pois, tomou de noite o menino e sua mãe, e partiu para o Egito."},{c:2,v:15,t:"e lá ficou até a morte de Herodes, para que se cumprisse o que fora dito da parte do Senhor pelo profeta: Do Egito chamei o meu Filho."},{c:2,v:16,t:"Então Herodes, vendo que fora iludido pelos magos, irou-se grandemente e mandou matar todos os meninos de dois anos para baixo que havia em Belém, e em todos os seus arredores, segundo o tempo que com precisão inquirira dos magos."},{c:2,v:17,t:"Cumpriu-se então o que fora dito pelo profeta Jeremias:"},{c:2,v:18,t:"Em Ramá se ouviu uma voz, lamentação e grande pranto: Raquel chorando os seus filhos, e não querendo ser consolada, porque eles já não existem."},{c:2,v:19,t:"Mas tendo morrido Herodes, eis que um anjo do Senhor apareceu em sonho a José no Egito,"},{c:2,v:20,t:"dizendo: Levanta-te, toma o menino e sua mãe e vai para a terra de Israel; porque já morreram os que procuravam a morte do menino."},{c:2,v:21,t:"Então ele se levantou, tomou o menino e sua mãe e foi para a terra de Israel."},{c:2,v:22,t:"Ouvindo, porém, que Arquelau reinava na Judéia em lugar de seu pai Herodes, temeu ir para lá; mas avisado em sonho por divina revelação, retirou-se para as regiões da Galiléia,"},{c:2,v:23,t:"e foi habitar numa cidade chamada Nazaré; para que se cumprisse o que fora dito pelos profetas: Ele será chamado nazareno."}],
    comentario: "Fuga para o Egito, retorno e instalação em Nazaré, com três citações proféticas encadeadas. A menção a Arquelau explica por que a família evita a Judeia — dado político preciso, já que ele foi deposto por Roma em 6 d.C. A última citação, sobre o nazareno, não corresponde a nenhum texto conhecido do Antigo Testamento."
  },
  "Mt 2,16-18": {
    titulo: "Mateus 2,16-18",
    tipo: "biblia",
    versos: [{c:2,v:16,t:"Então Herodes, vendo que fora iludido pelos magos, irou-se grandemente e mandou matar todos os meninos de dois anos para baixo que havia em Belém, e em todos os seus arredores, segundo o tempo que com precisão inquirira dos magos."},{c:2,v:17,t:"Cumpriu-se então o que fora dito pelo profeta Jeremias:"},{c:2,v:18,t:"Em Ramá se ouviu uma voz, lamentação e grande pranto: Raquel chorando os seus filhos, e não querendo ser consolada, porque eles já não existem."}],
    comentario: "A matança dos inocentes, ausente de qualquer fonte externa, inclusive de Josefo. Belém era um vilarejo, o que reduziria a cifra a poucas crianças, e o episódio é coerente com o retrato documentado de Herodes — mas está construído sobre o molde do faraó de Êxodo 1."
  },
  "Jr 31,15": {
    titulo: "Jeremias 31,15",
    tipo: "biblia",
    versos: [{c:31,v:15,t:"Assim diz o Senhor: Ouviu-se um clamor em Ramá, lamentação e choro amargo. Raquel chora a seus filhos, e não se deixa consolar a respeito deles, porque já não existem."}],
    comentario: "Raquel chorando os filhos, citada por Mateus. No original, o oráculo fala do exílio das tribos do norte e termina em consolo e retorno; Mateus recorta o verso do lamento. É um bom exemplo de como o Novo Testamento usa o Antigo: por associação temática, não por previsão literal."
  },
  "Mc 6,3": {
    titulo: "Marcos 6,3",
    tipo: "biblia",
    versos: [{c:6,v:3,t:"Não é este o carpinteiro, filho de Maria, irmão de Tiago, de José, de Judas e de Simão? e não estão aqui entre nós suas irmãs? E escandalizavam-se dele."}],
    comentario: "Os vizinhos listam o ofício e a parentela de Jesus: carpinteiro (tekton, artesão de madeira e pedra), filho de Maria, irmão de Tiago, José, Judas e Simão, com irmãs na aldeia. Chamar alguém de filho da mãe, e não do pai, era incomum. Este é o texto no centro da divergência sobre os irmãos de Jesus."
  },
  "Lc 2,51-52": {
    titulo: "Lucas 2,51-52",
    tipo: "biblia",
    versos: [{c:2,v:51,t:"Então, descendo com eles, foi para Nazaré, e era-lhes sujeito. E sua mãe guardava todas estas coisas em seu coração."},{c:2,v:52,t:"E crescia Jesus em sabedoria, em estatura e em graça diante de Deus e dos homens."}],
    comentario: "O fecho da infância: obediência aos pais e crescimento em sabedoria, estatura e graça. A frase alimentou séculos de discussão teológica — em que sentido alguém tido como divino aprende? — e é a única janela para os quase trinta anos que os Evangelhos deixam em branco."
  },
  "Lc 2,41-52": {
    titulo: "Lucas 2,41-52",
    tipo: "biblia",
    versos: [{c:2,v:41,t:"Ora, seus pais iam todos os anos a Jerusalém, à festa da páscoa."},{c:2,v:42,t:"Quando Jesus completou doze anos, subiram eles segundo o costume da festa;"},{c:2,v:43,t:"e, terminados aqueles dias, ao regressarem, ficou o menino Jesus em Jerusalém sem o saberem seus pais;"},{c:2,v:44,t:"julgando, porém, que estivesse entre os companheiros de viagem, andaram caminho de um dia, e o procuravam entre os parentes e conhecidos;"},{c:2,v:45,t:"e não o achando, voltaram a Jerusalém em busca dele."},{c:2,v:46,t:"E aconteceu que, passados três dias, o acharam no templo, sentado no meio dos doutores, ouvindo-os, e interrogando-os."},{c:2,v:47,t:"E todos os que o ouviam se admiravam da sua inteligência e das suas respostas."},{c:2,v:48,t:"Quando o viram, ficaram maravilhados, e disse-lhe sua mãe: Filho, por que procedeste assim para conosco? Eis que teu pai e eu ansiosos te procurávamos."},{c:2,v:49,t:"Respondeu-lhes ele: Por que me procuráveis? Não sabíeis que eu devia estar na casa de meu Pai?"},{c:2,v:50,t:"Eles, porém, não entenderam as palavras que lhes dissera."},{c:2,v:51,t:"Então, descendo com eles, foi para Nazaré, e era-lhes sujeito. E sua mãe guardava todas estas coisas em seu coração."},{c:2,v:52,t:"E crescia Jesus em sabedoria, em estatura e em graça diante de Deus e dos homens."}],
    comentario: "Única cena da adolescência em todo o Novo Testamento. O menino não ensina: ouve e pergunta, o método normal de aprendizado rabínico. Sua primeira fala registrada já reivindica uma relação própria com Deus, e Lucas anota sem suavizar que os pais não entenderam."
  },
  "Gl 1,19": {
    titulo: "Gálatas 1,19",
    tipo: "biblia",
    versos: [{c:1,v:19,t:"Mas não vi a nenhum outro dos apóstolos, senão a Tiago, irmão do Senhor."}],
    comentario: "Paulo, escrevendo nos anos 50, diz ter visto em Jerusalém apenas Pedro e Tiago, o irmão do Senhor. É a menção mais antiga a um parente de Jesus e uma das provas documentais mais fortes de sua existência histórica, feita por alguém que conheceu pessoalmente a família e os discípulos."
  },
  "Mc 1,1-8": {
    titulo: "Marcos 1,1-8",
    tipo: "biblia",
    versos: [{c:1,v:1,t:"Princípio do evangelho de Jesus Cristo, Filho de Deus."},{c:1,v:2,t:"Conforme está escrito no profeta Isaías: Eis que envio ante a tua face o meu mensageiro, que há de preparar o teu caminho;"},{c:1,v:3,t:"voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas;"},{c:1,v:4,t:"assim apareceu João, o Batista, no deserto, pregando o batismo de arrependimento para remissão dos pecados."},{c:1,v:5,t:"E saíam a ter com ele toda a terra da Judéia, e todos os moradores de Jerusalém; e eram por ele batizados no rio Jordão, confessando os seus pecados."},{c:1,v:6,t:"Ora, João usava uma veste de pêlos de camelo, e um cinto de couro em torno de seus lombos, e comia gafanhotos e mel silvestre."},{c:1,v:7,t:"E pregava, dizendo: Após mim vem aquele que é mais poderoso do que eu, de quem não sou digno de, inclinando-me, desatar a correia das alparcas."},{c:1,v:8,t:"Eu vos batizei em água; ele, porém, vos batizará no Espírito Santo."}],
    comentario: "A abertura do evangelho mais antigo: sem infância, sem genealogia, direto no deserto com João Batista. A citação inicial mistura Malaquias e Isaías, mas é atribuída só a Isaías — detalhe que copistas posteriores tentaram corrigir."
  },
  "Lc 3,1-18": {
    titulo: "Lucas 3,1-18",
    tipo: "biblia",
    versos: [{c:3,v:1,t:"No décimo quinto ano do reinado de Tibério César, sendo Pôncio Pilatos governador da Judéia, Herodes tetrarca da Galiléia, seu irmão Filipe tetrarca da região da Ituréia e de Traconites, e Lisânias tetrarca de Abilene,"},{c:3,v:2,t:"sendo Anás e Caifás sumos sacerdotes, veio a palavra de Deus a João, filho de Zacarias, no deserto."},{c:3,v:3,t:"E ele percorreu toda a circunvizinhança do Jordão, pregando o batismo de arrependimento para remissão de pecados;"},{c:3,v:4,t:"como está escrito no livro das palavras do profeta Isaías: Voz do que clama no deserto: Preparai o caminho do Senhor; endireitai as suas veredas."},{c:3,v:5,t:"Todo vale se encherá, e se abaixará todo monte e outeiro; o que é tortuoso se endireitará, e os caminhos escabrosos se aplanarão;"},{c:3,v:6,t:"e toda a carne verá a salvação de Deus."},{c:3,v:7,t:"João dizia, pois, às multidões que saíam para ser batizadas por ele: Raça de víboras, quem vos ensina a fugir da ira vindoura?"},{c:3,v:8,t:"Produzi, pois, frutos dignos de arrependimento; e não comeceis a dizer em vós mesmos: Temos por pai a Abrão; porque eu vos digo que até destas pedras Deus pode suscitar filhos a Abrão."},{c:3,v:9,t:"Também já está posto o machado à raiz das árvores; toda árvore, pois, que não produz bom fruto, é cortada e lançada no fogo."},{c:3,v:10,t:"Ao que lhe perguntavam as multidões: Que faremos, pois?"},{c:3,v:11,t:"Respondia-lhes então: Aquele que tem duas túnicas, reparta com o que não tem nenhuma, e aquele que tem alimentos, faça o mesmo."},{c:3,v:12,t:"Chegaram também uns publicanos para serem batizados, e perguntaram-lhe: Mestre, que havemos nós de fazer?"},{c:3,v:13,t:"Respondeu-lhes ele: Não cobreis além daquilo que vos foi prescrito."},{c:3,v:14,t:"Interrogaram-no também uns soldados: E nós, que faremos? Disse-lhes: A ninguém queirais extorquir coisa alguma; nem deis denúncia falsa; e contentai-vos com o vosso soldo."},{c:3,v:15,t:"Ora, estando o povo em expectativa e arrazoando todos em seus corações a respeito de João, se porventura seria ele o Cristo,"},{c:3,v:16,t:"respondeu João a todos, dizendo: Eu, na verdade, vos batizo em água, mas vem aquele que é mais poderoso do que eu, de quem não sou digno de desatar a correia das alparcas; ele vos batizará no Espírito Santo e em fogo."},{c:3,v:17,t:"A sua pá ele tem na mão para limpar bem a sua eira, e recolher o trigo ao seu celeiro; mas queimará a palha em fogo inextinguível."},{c:3,v:18,t:"Assim pois, com muitas outras exortações ainda, anunciava o evangelho ao povo."}],
    comentario: "A pregação de João com conteúdo social explícito: repartir a túnica, não cobrar além do estipulado, não extorquir. Lucas é o único a registrar essas instruções práticas a publicanos e soldados, e o único a datar a cena pelo calendário do império."
  },
  "Mc 1,9-11": {
    titulo: "Marcos 1,9-11",
    tipo: "biblia",
    versos: [{c:1,v:9,t:"E aconteceu naqueles dias que veio Jesus de Nazaré da Galiléia, e foi batizado por João no Jordão."},{c:1,v:10,t:"E logo, quando saía da água, viu os céus se abrirem, e o Espírito, qual pomba, a descer sobre ele;"},{c:1,v:11,t:"e ouviu-se dos céus esta voz: Tu és meu Filho amado; em ti me comprazo."}],
    comentario: "O batismo na versão mais antiga e mais crua: Jesus vem de Nazaré e é batizado, sem diálogo e sem explicação. A visão é dele — ele vê os céus se rasgarem e ouve a voz. Ser batizado num rito para remissão de pecados é constrangedor o bastante para que historiadores considerem o episódio inquestionável."
  },
  "Mt 3,13-17": {
    titulo: "Mateus 3,13-17",
    tipo: "biblia",
    versos: [{c:3,v:13,t:"Então veio Jesus da Galiléia ter com João, junto do Jordão, para ser batizado por ele."},{c:3,v:14,t:"Mas João o impedia, dizendo: Eu é que preciso ser batizado por ti, e tu vens a mim?"},{c:3,v:15,t:"Jesus, porém, lhe respondeu: Consente agora; porque assim nos convém cumprir toda a justiça. Então ele consentiu."},{c:3,v:16,t:"Batizado que foi Jesus, saiu logo da água; e eis que se lhe abriram os céus, e viu o Espírito Santo de Deus descendo como uma pomba e vindo sobre ele;"},{c:3,v:17,t:"e eis que uma voz dos céus dizia: Este é o meu Filho amado, em quem me comprazo."}],
    comentario: "Mateus percebe o problema e o resolve com um diálogo: João resiste, e Jesus responde que convém cumprir toda a justiça. A voz também muda de destinatário — fala na terceira pessoa, para quem estivesse presente. É possível ver, comparando com Marcos, o incômodo teológico crescendo dentro do próprio cânone."
  },
  "Lc 3,21-22": {
    titulo: "Lucas 3,21-22",
    tipo: "biblia",
    versos: [{c:3,v:21,t:"Quando todo o povo fora batizado, tendo sido Jesus também batizado, e estando ele a orar, o céu se abriu;"},{c:3,v:22,t:"e o Espírito Santo desceu sobre ele em forma corpórea, como uma pomba; e ouviu-se do céu esta voz: Tu és o meu Filho amado; em ti me comprazo."}],
    comentario: "Lucas menciona o batismo em uma oração subordinada e já colocou João na prisão dois versículos antes, de modo que nem fica claro quem batiza. A ênfase recai sobre Jesus em oração — tema recorrente neste evangelho."
  },
  "Jo 1,29-34": {
    titulo: "João 1,29-34",
    tipo: "biblia",
    versos: [{c:1,v:29,t:"No dia seguinte João viu a Jesus, que vinha para ele, e disse: Eis o Cordeiro de Deus, que tira o pecado do mundo."},{c:1,v:30,t:"este é aquele de quem eu disse: Depois de mim vem um varão que passou adiante de mim, porque antes de mim ele já existia."},{c:1,v:31,t:"Eu não o conhecia; mas, para que ele fosse manifestado a Israel, é que vim batizando em água."},{c:1,v:32,t:"E João deu testemunho, dizendo: Vi o Espírito descer do céu como pomba, e repousar sobre ele."},{c:1,v:33,t:"Eu não o conhecia; mas o que me enviou a batizar em água, esse me disse: Aquele sobre quem vires descer o Espírito, e sobre ele permanecer, esse é o que batiza no Espírito Santo."},{c:1,v:34,t:"Eu mesmo vi e já vos dei testemunho de que este é o Filho de Deus."}],
    comentario: "João não narra o batismo: registra apenas o testemunho do Batista, que vê o Espírito descer e declara Jesus o Cordeiro de Deus. A escolha é coerente com o programa do evangelho, em que João Batista existe sobretudo para apontar e depois diminuir."
  },
  "Mt 4,1-11": {
    titulo: "Mateus 4,1-11",
    tipo: "biblia",
    versos: [{c:4,v:1,t:"Então foi conduzido Jesus pelo Espírito ao deserto, para ser tentado pelo Diabo."},{c:4,v:2,t:"E, tendo jejuado quarenta dias e quarenta noites, depois teve fome."},{c:4,v:3,t:"Chegando, então, o tentador, disse-lhe: Se tu és Filho de Deus manda que estas pedras se tornem em pães."},{c:4,v:4,t:"Mas Jesus lhe respondeu: Está escrito: Nem só de pão viverá o homem, mas de toda palavra que sai da boca de Deus."},{c:4,v:5,t:"Então o Diabo o levou à cidade santa, colocou-o sobre o pináculo do templo,"},{c:4,v:6,t:"e disse-lhe: Se tu és Filho de Deus, lança-te daqui abaixo; porque está escrito: Aos seus anjos dará ordens a teu respeito; e: eles te susterão nas mãos, para que nunca tropeces em alguma pedra."},{c:4,v:7,t:"Replicou-lhe Jesus: Também está escrito: Não tentarás o Senhor teu Deus."},{c:4,v:8,t:"Novamente o Diabo o levou a um monte muito alto; e mostrou-lhe todos os reinos do mundo, e a glória deles;"},{c:4,v:9,t:"e disse-lhe: Tudo isto te darei, se, prostrado, me adorares."},{c:4,v:10,t:"Então ordenou-lhe Jesus: Vai-te, Satanás; porque está escrito: Ao Senhor teu Deus adorarás, e só a ele servirás."},{c:4,v:11,t:"Então o Diabo o deixou; e eis que vieram os anjos e o serviram."}],
    comentario: "As três tentações — pão, espetáculo e poder — com respostas tiradas todas do Deuteronômio, de passagens sobre Israel no deserto. Funciona como programa negativo do ministério: nada de messianismo econômico, de prodígio como prova ou de poder político. Lucas inverte a ordem das duas últimas."
  },
  "Lc 4,1-13": {
    titulo: "Lucas 4,1-13",
    tipo: "biblia",
    versos: [{c:4,v:1,t:"Jesus, pois, cheio do Espírito Santo, voltou do Jordão; e era levado pelo Espírito no deserto,"},{c:4,v:2,t:"durante quarenta dias, sendo tentado pelo Diabo. E naqueles dias não comeu coisa alguma; e terminados eles, teve fome."},{c:4,v:3,t:"Disse-lhe então o Diabo: Se tu és Filho de Deus, manda a esta pedra que se torne em pão."},{c:4,v:4,t:"Jesus, porém, lhe respondeu: Está escrito: Nem só de pão viverá o homem."},{c:4,v:5,t:"Então o Diabo, levando-o a um lugar elevado, mostrou-lhe num relance todos os reinos do mundo."},{c:4,v:6,t:"E disse-lhe: Dar-te-ei toda a autoridade e glória destes reinos, porque me foi entregue, e a dou a quem eu quiser;"},{c:4,v:7,t:"se tu, me adorares, será toda tua."},{c:4,v:8,t:"Respondeu-lhe Jesus: Está escrito: Ao Senhor teu Deus adorarás, e só a ele servirás."},{c:4,v:9,t:"Então o levou a Jerusalém e o colocou sobre o pináculo do templo e lhe disse: Se tu és Filho de Deus, lança-te daqui abaixo;"},{c:4,v:10,t:"porque está escrito: Aos seus anjos ordenará a teu respeito, que te guardem;"},{c:4,v:11,t:"e: eles te susterão nas mãos, para que nunca tropeces em alguma pedra."},{c:4,v:12,t:"Respondeu-lhe Jesus: Dito está: Não tentarás o Senhor teu Deus."},{c:4,v:13,t:"Assim, tendo o Diabo acabado toda sorte de tentação, retirou-se dele até ocasião oportuna."}],
    comentario: "A versão de Lucas encerra com uma frase inquietante: o diabo se afastou dele até um tempo oportuno — ou seja, a tentação volta, e voltará na paixão. O detalhe é exclusivo deste evangelho e organiza a leitura de tudo o que vem depois."
  },
  "Mc 1,12-13": {
    titulo: "Marcos 1,12-13",
    tipo: "biblia",
    versos: [{c:1,v:12,t:"Imediatamente o Espírito o impeliu para o deserto."},{c:1,v:13,t:"E esteve no deserto quarenta dias sentado tentado por Satanás; estava entre as feras, e os anjos o serviam."}],
    comentario: "Duas linhas, e nenhum diálogo: o Espírito impele Jesus ao deserto, ele fica quarenta dias entre as feras e os anjos o servem. A concisão de Marcos deixa ver o que Mateus e Lucas acrescentaram a partir da fonte comum de ditos."
  },
  "Mc 1,16-20": {
    titulo: "Marcos 1,16-20",
    tipo: "biblia",
    versos: [{c:1,v:16,t:"E, andando junto do mar da Galiléia, viu a Simão, e a André, irmão de Simão, os quais lançavam a rede ao mar, pois eram pescadores."},{c:1,v:17,t:"Disse-lhes Jesus: Vinde após mim, e eu farei que vos torneis pescadores de homens."},{c:1,v:18,t:"Então eles, deixando imediatamente as suas redes, o seguiram."},{c:1,v:19,t:"E ele, passando um pouco adiante, viu Tiago, filho de Zebedeu, e João, seu irmão, que estavam no barco, consertando as redes,"},{c:1,v:20,t:"e logo os chamou; eles, deixando seu pai Zebedeu no barco com os empregados, o seguiram."}],
    comentario: "O chamado dos primeiros discípulos, sem preparação e sem diálogo: passa, vê, chama, seguem. A brevidade é recurso literário. Repare que eles têm barcos, redes e empregados — não são miseráveis, e a decisão implica perda econômica real."
  },
  "Mt 9,9-13": {
    titulo: "Mateus 9,9-13",
    tipo: "biblia",
    versos: [{c:9,v:9,t:"Partindo Jesus dali, viu sentado na coletoria um homem chamado Mateus, e disse-lhe: Segue-me. E ele, levantando-se, o seguiu."},{c:9,v:10,t:"Ora, estando ele à mesa em casa, eis que chegaram muitos publicanos e pecadores, e se reclinaram à mesa juntamente com Jesus e seus discípulos."},{c:9,v:11,t:"E os fariseus, vendo isso, perguntavam aos discípulos: Por que come o vosso Mestre com publicanos e pecadores?"},{c:9,v:12,t:"Jesus, porém, ouvindo isso, respondeu: Não necessitam de médico os sãos, mas sim os enfermos."},{c:9,v:13,t:"Ide, pois, e aprendei o que significa: Misericórdia quero, e não sacrifícios. Porque eu não vim chamar justos, mas pecadores."}],
    comentario: "O chamado de um cobrador de impostos e a refeição que se segue são a cena que mais escandaliza os adversários: comer com publicanos e pecadores, num mundo em que a mesa definia pertencimento, era declaração pública. A resposta — não são os sãos que precisam de médico — resume a lógica do movimento."
  },
  "Mc 1–9": {
    titulo: "Marcos 1–9",
    tipo: "biblia",
    nota: "trecho de Marcos 1–9",
    versos: [{c:1,v:14,t:"Ora, depois que João foi entregue, veio Jesus para a Galiléia pregando o evangelho de Deus"},{c:1,v:15,t:"e dizendo: O tempo está cumprido, e é chegado o reino de Deus. Arrependei-vos, e crede no evangelho."},{c:1,v:16,t:"E, andando junto do mar da Galiléia, viu a Simão, e a André, irmão de Simão, os quais lançavam a rede ao mar, pois eram pescadores."},{c:1,v:17,t:"Disse-lhes Jesus: Vinde após mim, e eu farei que vos torneis pescadores de homens."},{c:1,v:18,t:"Então eles, deixando imediatamente as suas redes, o seguiram."},{c:1,v:19,t:"E ele, passando um pouco adiante, viu Tiago, filho de Zebedeu, e João, seu irmão, que estavam no barco, consertando as redes,"},{c:1,v:20,t:"e logo os chamou; eles, deixando seu pai Zebedeu no barco com os empregados, o seguiram."}],
    comentario: "Trecho de abertura do ministério na Galileia, com o resumo da mensagem: o tempo está cumprido, o Reino de Deus está próximo. Reino, na linguagem da época, não significava lugar após a morte, e sim o governo efetivo de Deus sobre o mundo — restauração, justiça, fim da opressão."
  },
  "Lc 4–9": {
    titulo: "Lucas 4–9",
    tipo: "biblia",
    nota: "trecho de Lucas 4–9",
    versos: [{c:4,v:16,t:"Chegando a Nazaré, onde fora criado; entrou na sinagoga no dia de sábado, segundo o seu costume, e levantou-se para ler."},{c:4,v:17,t:"Foi-lhe entregue o livro do profeta Isaías; e abrindo-o, achou o lugar em que estava escrito:"},{c:4,v:18,t:"O Espírito do Senhor está sobre mim, porquanto me ungiu para anunciar boas novas aos pobres; enviou-me para proclamar libertação aos cativos, e restauração da vista aos cegos, para pôr em liberdade os oprimidos,"},{c:4,v:19,t:"e para proclamar o ano aceitável do Senhor."},{c:4,v:20,t:"E fechando o livro, devolveu-o ao assistente e sentou-se; e os olhos de todos na sinagoga estavam fitos nele."},{c:4,v:21,t:"Então começou a dizer-lhes: Hoje se cumpriu esta escritura aos vossos ouvidos."}],
    comentario: "O trecho escolhido é o discurso de Nazaré, que em Lucas funciona como programa: Jesus lê Isaías 61 na sinagoga — boa nova aos pobres, liberdade aos cativos, ano de graça — e declara o texto cumprido. Termina com a cidade tentando despenhá-lo."
  },
  "Jo 2,1-11": {
    titulo: "João 2,1-11",
    tipo: "biblia",
    versos: [{c:2,v:1,t:"Três dias depois, houve um casamento em Caná da Galiléia, e estava ali a mãe de Jesus;"},{c:2,v:2,t:"e foi também convidado Jesus com seus discípulos para o casamento."},{c:2,v:3,t:"E, tendo acabado o vinho, a mãe de Jesus lhe disse: Eles não têm vinho."},{c:2,v:4,t:"Respondeu-lhes Jesus: Mulher, que tenho eu contigo? Ainda não é chegada a minha hora."},{c:2,v:5,t:"Disse então sua mãe aos serventes: Fazei tudo quanto ele vos disser."},{c:2,v:6,t:"Ora, estavam ali postas seis talhas de pedra, para as purificações dos judeus, e em cada uma cabiam duas ou três metretas."},{c:2,v:7,t:"Ordenou-lhe Jesus: Enchei de água essas talhas. E encheram- nas até em cima."},{c:2,v:8,t:"Então lhes disse: Tirai agora, e levai ao mestre-sala. E eles o fizeram."},{c:2,v:9,t:"Quando o mestre-sala provou a água tornada em vinho, não sabendo donde era, se bem que o sabiam os serventes que tinham tirado a água, chamou o mestre-sala ao noivo"},{c:2,v:10,t:"e lhe disse: Todo homem põe primeiro o vinho bom e, quando já têm bebido bem, então o inferior; mas tu guardaste até agora o bom vinho."},{c:2,v:11,t:"Assim deu Jesus início aos seus sinais em Caná da Galiléia, e manifestou a sua glória; e os seus discípulos creram nele."}],
    comentario: "O primeiro dos sete sinais de João. As talhas eram de purificação ritual, e o volume — entre 400 e 600 litros — é desproporcional de propósito: evoca a abundância prometida pelos profetas para os tempos messiânicos. A ironia do mestre-sala, que reclama da ordem invertida do vinho, é do evangelista."
  },
  "Jo 2,13-22": {
    titulo: "João 2,13-22",
    tipo: "biblia",
    versos: [{c:2,v:13,t:"Estando próxima a páscoa dos judeus, Jesus subiu a Jerusalém."},{c:2,v:14,t:"E achou no templo os que vendiam bois, ovelhas e pombas, e também os cambistas ali sentados;"},{c:2,v:15,t:"e tendo feito um azorrague de cordas, lançou todos fora do templo, bem como as ovelhas e os bois; e espalhou o dinheiro dos cambistas, e virou-lhes as mesas;"},{c:2,v:16,t:"e disse aos que vendiam as pombas: Tirai daqui estas coisas; não façais da casa de meu Pai casa de negócio."},{c:2,v:17,t:"Lembraram-se então os seus discípulos de que está escrito: O zelo da tua casa me devorará."},{c:2,v:18,t:"Protestaram, pois, os judeus, perguntando-lhe: Que sinal de autoridade nos mostras, uma vez que fazes isto?"},{c:2,v:19,t:"Respondeu-lhes Jesus: Derribai este santuário, e em três dias o levantarei."},{c:2,v:20,t:"Disseram, pois, os judeus: Em quarenta e seis anos foi edificado este santuário, e tu o levantarás em três dias?"},{c:2,v:21,t:"Mas ele falava do santuário do seu corpo."},{c:2,v:22,t:"Quando, pois ressurgiu dentre os mortos, seus discípulos se lembraram de que dissera isto, e creram na Escritura, e na palavra que Jesus havia dito."}],
    comentario: "A purificação do Templo, que João coloca no início do ministério enquanto os sinóticos a situam na última semana. Vem acompanhada do dito sobre destruir e reerguer o templo em três dias, que reaparecerá como acusação no julgamento — e que o evangelista explica ao leitor como referência ao corpo."
  },
  "Mc 11,15-19": {
    titulo: "Marcos 11,15-19",
    tipo: "biblia",
    versos: [{c:11,v:15,t:"Chegaram, pois, a Jerusalém. E entrando ele no templo, começou a expulsar os que ali vendiam e compravam; e derribou as mesas dos cambistas, e as cadeiras dos que vendiam pombas;"},{c:11,v:16,t:"e não consentia que ninguém atravessasse o templo levando qualquer utensílio;"},{c:11,v:17,t:"e ensinava, dizendo-lhes: Não está escrito: A minha casa será chamada casa de oração para todas as nações? Vós, porém, a tendes feito covil de salteadores."},{c:11,v:18,t:"Ora, os principais sacerdotes e os escribas ouviram isto, e procuravam um modo de o matar; pois o temiam, porque toda a multidão se maravilhava da sua doutrina."},{c:11,v:19,t:"Ao cair da tarde, saíam da cidade."}],
    comentario: "A mesma cena nos sinóticos, na semana da Páscoa: derrubar mesas de cambistas e vendedores de animais no maior pátio do mundo antigo, com a cidade cheia de peregrinos. Para boa parte dos historiadores, é o gesto que explica a prisão poucos dias depois."
  },
  "Jo 3,1-21": {
    titulo: "João 3,1-21",
    tipo: "biblia",
    versos: [{c:3,v:1,t:"Ora, havia entre os fariseus um homem chamado Nicodemos, um dos principais dos judeus."},{c:3,v:2,t:"Este foi ter com Jesus, de noite, e disse-lhe: Rabi, sabemos que és Mestre, vindo de Deus; pois ninguém pode fazer estes sinais que tu fazes, se Deus não estiver com ele."},{c:3,v:3,t:"Respondeu-lhe Jesus: Em verdade, em verdade te digo que se alguém não nascer de novo, não pode ver o reino de Deus."},{c:3,v:4,t:"Perguntou-lhe Nicodemos: Como pode um homem nascer, sendo velho? porventura pode tornar a entrar no ventre de sua mãe, e nascer?"},{c:3,v:5,t:"Jesus respondeu: Em verdade, em verdade te digo que se alguém não nascer da água e do Espírito, não pode entrar no reino de Deus."},{c:3,v:6,t:"O que é nascido da carne é carne, e o que é nascido do Espírito é espírito."},{c:3,v:7,t:"Não te admires de eu te haver dito: Necessário vos é nascer de novo."},{c:3,v:8,t:"O vento sopra onde quer, e ouves a sua voz; mas não sabes donde vem, nem para onde vai; assim é todo aquele que é nascido do Espírito."},{c:3,v:9,t:"Perguntou-lhe Nicodemos: Como pode ser isto?"},{c:3,v:10,t:"Respondeu-lhe Jesus: Tu és mestre em Israel, e não entendes estas coisas?"},{c:3,v:11,t:"Em verdade, em verdade te digo que nós dizemos o que sabemos e testemunhamos o que temos visto; e não aceitais o nosso testemunho!"},{c:3,v:12,t:"Se vos falei de coisas terrestres, e não credes, como crereis, se vos falar das celestiais?"},{c:3,v:13,t:"Ora, ninguém subiu ao céu, senão o que desceu do céu, o Filho do homem."},{c:3,v:14,t:"E como Moisés levantou a serpente no deserto, assim importa que o Filho do homem seja levantado;"},{c:3,v:15,t:"para que todo aquele que nele crê tenha a vida eterna."},{c:3,v:16,t:"Porque Deus amou o mundo de tal maneira que deu o seu Filho unigênito, para que todo aquele que nele crê não pereça, mas tenha a vida eterna."},{c:3,v:17,t:"Porque Deus enviou o seu Filho ao mundo, não para que julgasse o mundo, mas para que o mundo fosse salvo por ele."},{c:3,v:18,t:"Quem crê nele não é julgado; mas quem não crê, já está julgado; porquanto não crê no nome do unigênito Filho de Deus."},{c:3,v:19,t:"E o julgamento é este: A luz veio ao mundo, e os homens amaram antes as trevas que a luz, porque as suas obras eram más."},{c:3,v:20,t:"Porque todo aquele que faz o mal aborrece a luz, e não vem para a luz, para que as suas obras não sejam reprovadas."},{c:3,v:21,t:"Mas quem pratica a verdade vem para a luz, a fim de que seja manifesto que as suas obras são feitas em Deus."}],
    comentario: "O diálogo noturno com Nicodemos, construído sobre a ambiguidade do grego anothen — de novo e do alto. Do trecho saem a expressão nascer de novo, identidade de correntes evangélicas inteiras, e João 3,16. A leitura espírita entende a expressão como referência à reencarnação."
  },
  "Jo 4,1-42": {
    titulo: "João 4,1-42",
    tipo: "biblia",
    versos: [{c:4,v:1,t:"Quando, pois, o Senhor soube que os fariseus tinham ouvido dizer que ele, Jesus, fazia e batizava mais discípulos do que João"},{c:4,v:2,t:"(ainda que Jesus mesmo não batizava, mas os seus discípulos)"},{c:4,v:3,t:"deixou a Judéia, e foi outra vez para a Galiléia."},{c:4,v:4,t:"E era-lhe necessário passar por Samária."},{c:4,v:5,t:"Chegou, pois, a uma cidade de Samária, chamada Sicar, junto da herdade que Jacó dera a seu filho José;"},{c:4,v:6,t:"achava-se ali o poço de Jacó. Jesus, pois, cansado da viagem, sentou-se assim junto do poço; era cerca da hora sexta."},{c:4,v:7,t:"Veio uma mulher de Samária tirar água. Disse-lhe Jesus: Dá- me de beber."},{c:4,v:8,t:"Pois seus discípulos tinham ido à cidade comprar comida."},{c:4,v:9,t:"Disse-lhe então a mulher samaritana: Como, sendo tu judeu, me pedes de beber a mim, que sou mulher samaritana? (Porque os judeus não se comunicavam com os samaritanos.)"},{c:4,v:10,t:"Respondeu-lhe Jesus: Se tivesses conhecido o dom de Deus e quem é o que te diz: Dá-me de beber, tu lhe terias pedido e ele te haveria dado água viva."},{c:4,v:11,t:"Disse-lhe a mulher: Senhor, tu não tens com que tirá-la, e o poço é fundo; donde, pois, tens essa água viva?"},{c:4,v:12,t:"És tu, porventura, maior do que o nosso pai Jacó, que nos deu o poço, do qual também ele mesmo bebeu, e os filhos, e o seu gado?."},{c:4,v:13,t:"Replicou-lhe Jesus: Todo o que beber desta água tornará a ter sede;"},{c:4,v:14,t:"mas aquele que beber da água que eu lhe der nunca terá sede; pelo contrário, a água que eu lhe der se fará nele uma fonte de água que jorre para a vida eterna."},{c:4,v:15,t:"Disse-lhe a mulher: Senhor, dá-me dessa água, para que não mais tenha sede, nem venha aqui tirá-la."},{c:4,v:16,t:"Disse-lhe Jesus: Vai, chama o teu marido e vem cá."},{c:4,v:17,t:"Respondeu a mulher: Não tenho marido. Disse-lhe Jesus: Disseste bem: Não tenho marido;"},{c:4,v:18,t:"porque cinco maridos tiveste, e o que agora tens não é teu marido; isso disseste com verdade."},{c:4,v:19,t:"Disse-lhe a mulher: Senhor, vejo que és profeta."},{c:4,v:20,t:"Nossos pais adoraram neste monte, e vós dizeis que em Jerusalém é o lugar onde se deve adorar."},{c:4,v:21,t:"Disse-lhe Jesus: Mulher, crê-me, a hora vem, em que nem neste monte, nem em Jerusalém adorareis o Pai."},{c:4,v:22,t:"Vós adorais o que não conheceis; nós adoramos o que conhecemos; porque a salvação vem dos judeus."},{c:4,v:23,t:"Mas a hora vem, e agora é, em que os verdadeiros adoradores adorarão o Pai em espírito e em verdade; porque o Pai procura a tais que assim o adorem."},{c:4,v:24,t:"Deus é Espírito, e é necessário que os que o adoram o adorem em espírito e em verdade."},{c:4,v:25,t:"Replicou-lhe a mulher: Eu sei que vem o Messias (que se chama o Cristo); quando ele vier há de nos anunciar todas as coisas."},{c:4,v:26,t:"Disse-lhe Jesus: Eu o sou, eu que falo contigo."},{c:4,v:27,t:"E nisto vieram os seus discípulos, e se admiravam de que estivesse falando com uma mulher; todavia nenhum lhe perguntou: Que é que procuras? ou: Por que falas com ela?"},{c:4,v:28,t:"Deixou, pois, a mulher o seu cântaro, foi à cidade e disse àqueles homens:"},{c:4,v:29,t:"Vinde, vede um homem que me disse tudo quanto eu tenho feito; será este, porventura, o Cristo?"},{c:4,v:30,t:"Saíram, pois, da cidade e vinham ter com ele."},{c:4,v:31,t:"Entrementes os seus discípulos lhe rogavam, dizendo: Rabi, come."},{c:4,v:32,t:"Ele, porém, respondeu: Uma comida tenho para comer que vós não conheceis."},{c:4,v:33,t:"Então os discípulos diziam uns aos outros: Acaso alguém lhe trouxe de comer?"},{c:4,v:34,t:"Disse-lhes Jesus: A minha comida é fazer a vontade daquele que me enviou, e completar a sua obra."},{c:4,v:35,t:"Não dizeis vós: Ainda há quatro meses até que venha a ceifa? Ora, eu vos digo: levantai os vossos olhos, e vede os campos, que já estão brancos para a ceifa."},{c:4,v:36,t:"Quem ceifa já está recebendo recompensa e ajuntando fruto para a vida eterna; para que o que semeia e o que ceifa juntamente se regozijem."},{c:4,v:37,t:"Porque nisto é verdadeiro o ditado: Um é o que semeia, e outro o que ceifa."},{c:4,v:38,t:"Eu vos enviei a ceifar onde não trabalhaste; outros trabalharam, e vós entrastes no seu trabalho."},{c:4,v:39,t:"E muitos samaritanos daquela cidade creram nele, por causa da palavra da mulher, que testificava: Ele me disse tudo quanto tenho feito."},{c:4,v:40,t:"Indo, pois, ter com ele os samaritanos, rogaram-lhe que ficasse com eles; e ficou ali dois dias."},{c:4,v:41,t:"E muitos mais creram por causa da palavra dele;"},{c:4,v:42,t:"e diziam à mulher: Já não é pela tua palavra que nós cremos; pois agora nós mesmos temos ouvido e sabemos que este é verdadeiramente o Salvador do mundo."}],
    comentario: "O diálogo mais longo que Jesus mantém com alguém em todo o evangelho de João — e é com uma mulher, samaritana e de vida irregular. Ele atravessa três barreiras de uma vez, e é a ela que faz a declaração mais direta sobre a própria identidade."
  },
  "Mt 5–7": {
    titulo: "Mateus 5–7",
    tipo: "biblia",
    nota: "trecho do Sermão da Montanha (Mt 5–7)",
    versos: [{c:5,v:1,t:"Jesus, pois, vendo as multidões, subiu ao monte; e, tendo se assentado, aproximaram-se os seus discípulos,"},{c:5,v:2,t:"e ele se pôs a ensiná-los, dizendo:"},{c:5,v:3,t:"Bem-aventurados os humildes de espírito, porque deles é o reino dos céus."},{c:5,v:4,t:"Bem-aventurados os que choram, porque eles serão consolados."},{c:5,v:5,t:"Bem-aventurados os mansos, porque eles herdarão a terra."},{c:5,v:6,t:"Bem-aventurados os que têm fome e sede de justiça porque eles serão fartos."},{c:5,v:7,t:"Bem-aventurados os misericordiosos, porque eles alcançarão misericórdia."},{c:5,v:8,t:"Bem-aventurados os limpos de coração, porque eles verão a Deus."},{c:5,v:9,t:"Bem-aventurados os pacificadores, porque eles serão chamados filhos de Deus."},{c:5,v:10,t:"Bem-aventurados os que são perseguidos por causa da justiça, porque deles é o reino dos céus."},{c:5,v:11,t:"Bem-aventurados sois vós, quando vos injuriarem e perseguiram e, mentindo, disserem todo mal contra vós por minha causa."},{c:5,v:12,t:"Alegrai-vos e exultai, porque é grande o vosso galardão nos céus; porque assim perseguiram aos profetas que foram antes de vós."},{c:5,v:13,t:"Vós sois o sal da terra; mas se o sal se tornar insípido, com que se há de restaurar-lhe o sabor? para nada mais presta, senão para ser lançado fora, e ser pisado pelos homens."},{c:5,v:14,t:"Vós sois a luz do mundo. Não se pode esconder uma cidade situada sobre um monte;"},{c:5,v:15,t:"nem os que acendem uma candeia a colocam debaixo do alqueire, mas no velador, e assim ilumina a todos que estão na casa."},{c:5,v:16,t:"Assim resplandeça a vossa luz diante dos homens, para que vejam as vossas boas obras, e glorifiquem a vosso Pai, que está nos céus."}],
    comentario: "O trecho escolhido é a abertura do Sermão da Montanha: as bem-aventuranças e as imagens do sal e da luz. Não são conselhos, e sim declarações no presente sobre a quem pertence o Reino — e declaram felizes exatamente quem o senso comum considerava desafortunado."
  },
  "Lc 6,20-49": {
    titulo: "Lucas 6,20-49",
    tipo: "biblia",
    versos: [{c:6,v:20,t:"Então, levantando ele os olhos para os seus discípulos, dizia: Bem-aventurados vós, os pobres, porque vosso é o reino de Deus."},{c:6,v:21,t:"Bem-aventurados vós, que agora tendes fome, porque sereis fartos. Bem-aventurados vós, que agora chorais, porque haveis de rir."},{c:6,v:22,t:"Bem-aventurados sereis quando os homens vos odiarem, e quando vos expulsarem da sua companhia, e vos injuriarem, e rejeitarem o vosso nome como indigno, por causa do Filho do homem."},{c:6,v:23,t:"Regozijai-vos nesse dia e exultai, porque eis que é grande o vosso galardão no céu; pois assim faziam os seus pais aos profetas."},{c:6,v:24,t:"Mas ai de vós que sois ricos! porque já recebestes a vossa consolação."},{c:6,v:25,t:"Ai de vós, os que agora estais fartos! porque tereis fome. Ai de vós, os que agora rides! porque vos lamentareis e chorareis."},{c:6,v:26,t:"Ai de vós, quando todos os homens vos louvarem! porque assim faziam os seus pais aos falsos profetas."},{c:6,v:27,t:"Mas a vós que ouvis, digo: Amai a vossos inimigos, fazei bem aos que vos odeiam,"},{c:6,v:28,t:"bendizei aos que vos maldizem, e orai pelos que vos caluniam."},{c:6,v:29,t:"Ao que te ferir numa face, oferece-lhe também a outra; e ao que te houver tirado a capa, não lhe negues também a túnica."},{c:6,v:30,t:"Dá a todo o que te pedir; e ao que tomar o que é teu, não lho reclames."},{c:6,v:31,t:"Assim como quereis que os homens vos façam, do mesmo modo lhes fazei vós também."},{c:6,v:32,t:"Se amardes aos que vos amam, que mérito há nisso? Pois também os pecadores amam aos que os amam."},{c:6,v:33,t:"E se fizerdes bem aos que vos fazem bem, que mérito há nisso? Também os pecadores fazem o mesmo."},{c:6,v:34,t:"E se emprestardes àqueles de quem esperais receber, que mérito há nisso? Também os pecadores emprestam aos pecadores, para receberem outro tanto."},{c:6,v:35,t:"Amai, porém a vossos inimigos, fazei bem e emprestai, nunca desanimado; e grande será a vossa recompensa, e sereis filhos do Altíssimo; porque ele é benigno até para com os integrantes e maus."},{c:6,v:36,t:"Sede misericordiosos, como também vosso Pai é misericordioso."},{c:6,v:37,t:"Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; perdoai, e sereis perdoados."},{c:6,v:38,t:"Dai, e ser-vos-á dado; boa medida, recalcada, sacudida e transbordando vos deitarão no regaço; porque com a mesma medida com que medis, vos medirão a vós."},{c:6,v:39,t:"E propôs-lhes também uma parábola: Pode porventura um cego guiar outro cego? não cairão ambos no barranco?"},{c:6,v:40,t:"Não é o discípulo mais do que o seu mestre; mas todo o que for bem instruído será como o seu mestre."},{c:6,v:41,t:"Por que vês o argueiro no olho de teu irmão, e não reparas na trave que está no teu próprio olho?"},{c:6,v:42,t:"Ou como podes dizer a teu irmão: Irmão, deixa-me tirar o argueiro que está no teu olho, não vendo tu mesmo a trave que está no teu? Hipócrita! tira primeiro a trave do teu olho; e então verás bem para tirar o argueiro que está no olho de teu irmão."},{c:6,v:43,t:"Porque não há árvore boa que dê mau fruto nem tampouco árvore má que dê bom fruto."},{c:6,v:44,t:"Porque cada árvore se conhece pelo seu próprio fruto; pois dos espinheiros não se colhem figos, nem dos abrolhos se vindimam uvas."},{c:6,v:45,t:"O homem bom, do bom tesouro do seu coração tira o bem; e o homem mau, do seu mau tesouro tira o mal; pois do que há em abundância no coração, disso fala a boca."},{c:6,v:46,t:"E por que me chamais: Senhor, Senhor, e não fazeis o que eu vos digo?"},{c:6,v:47,t:"Todo aquele que vem a mim, e ouve as minhas palavras, e as pratica, eu vos mostrarei a quem é semelhante:"},{c:6,v:48,t:"É semelhante ao homem que, edificando uma casa, cavou, abriu profunda vala, e pôs os alicerces sobre a rocha; e vindo a enchente, bateu com ímpeto a torrente naquela casa, e não a pôde abalar, porque tinha sido bem edificada."},{c:6,v:49,t:"Mas o que ouve e não pratica é semelhante a um homem que edificou uma casa sobre terra, sem alicerces, na qual bateu com ímpeto a torrente, e logo caiu; e foi grande a ruína daquela casa."}],
    comentario: "A versão de Lucas é mais curta, acontece num lugar plano e vem em pares: quatro bem-aventuranças seguidas de quatro maldições (ai de vós, ricos). Onde Mateus escreve pobres em espírito, Lucas escreve simplesmente pobres — a comparação mostra dois modos de organizar o mesmo material."
  },
  "Mc 3,13-19": {
    titulo: "Marcos 3,13-19",
    tipo: "biblia",
    versos: [{c:3,v:13,t:"Depois subiu ao monte, e chamou a si os que ele mesmo queria; e vieram a ele."},{c:3,v:14,t:"Então designou doze para que estivessem com ele, e os mandasse a pregar;"},{c:3,v:15,t:"e para que tivessem autoridade de expulsar os demônios."},{c:3,v:16,t:"Designou, pois, os doze, a saber: Simão, a quem pôs o nome de Pedro;"},{c:3,v:17,t:"Tiago, filho de Zebedeu, e João, irmão de Tiago, aos quais pôs o nome de Boanerges, que significa: Filhos do trovão;"},{c:3,v:18,t:"André, Filipe, Bartolomeu, Mateus, Tomé, Tiago, filho de Alfeu, Tadeu, Simão, o cananeu,"},{c:3,v:19,t:"e Judas Iscariotes, aquele que o traiu."}],
    comentario: "A escolha dos Doze, com a função em duas partes: estar com ele e ser enviado a pregar. O número aponta para as doze tribos — escolher doze é dizer, em gesto, que Israel está sendo reconstituído. As listas dos Evangelhos não coincidem inteiramente nos nomes."
  },
  "Lc 6,12-16": {
    titulo: "Lucas 6,12-16",
    tipo: "biblia",
    versos: [{c:6,v:12,t:"Naqueles dias retirou-se para o monte a fim de orar; e passou a noite toda em oração a Deus."},{c:6,v:13,t:"Depois do amanhecer, chamou seus discípulos, e escolheu doze dentre eles, aos quais deu também o nome de apóstolos:"},{c:6,v:14,t:"Simão, ao qual também chamou Pedro, e André, seu irmão; Tiago e João; Filipe e Bartolomeu;"},{c:6,v:15,t:"Mateus e Tomé; Tiago, filho de Alfeu, e Simão, chamado Zelote;"},{c:6,v:16,t:"Judas, filho de Tiago; e Judas Iscariotes, que veio a ser o traidor."}],
    comentario: "Lucas antecede a escolha com uma noite inteira de oração e é o primeiro a chamar o grupo de apóstolos, isto é, enviados. Sua lista inclui Simão, chamado Zelote, ao lado de um ex-cobrador de impostos: adversários políticos na mesma mesa."
  },
  "Mc 1,21-45": {
    titulo: "Marcos 1,21-45",
    tipo: "biblia",
    versos: [{c:1,v:21,t:"Entraram em Cafarnaum; e, logo no sábado, indo ele à sinagoga, pôs-se a ensinar."},{c:1,v:22,t:"E maravilhavam-se da sua doutrina, porque os ensinava como tendo autoridade, e não como os escribas."},{c:1,v:23,t:"Ora, estava na sinagoga um homem possesso dum espírito imundo, o qual gritou:"},{c:1,v:24,t:"Que temos nós contigo, Jesus, nazareno? Vieste destruir-nos? Bem sei quem és: o Santo de Deus."},{c:1,v:25,t:"Mas Jesus o repreendeu, dizendo: Cala-te, e sai dele."},{c:1,v:26,t:"Então o espírito imundo, convulsionando-o e clamando com grande voz, saiu dele."},{c:1,v:27,t:"E todos se maravilharam a ponto de perguntarem entre si, dizendo: Que é isto? Uma nova doutrina com autoridade! Pois ele ordena aos espíritos imundos, e eles lhe obedecem!"},{c:1,v:28,t:"E logo correu a sua fama por toda a região da Galiléia."},{c:1,v:29,t:"Em seguida, saiu da sinagoga e foi a casa de Simão e André com Tiago e João."},{c:1,v:30,t:"A sogra de Simão estava de cama com febre, e logo lhe falaram a respeito dela."},{c:1,v:31,t:"Então Jesus, chegando-se e tomando-a pela mão, a levantou; e a febre a deixou, e ela os servia."},{c:1,v:32,t:"Sendo já tarde, tendo-se posto o sol, traziam-lhe todos os enfermos, e os endemoninhados;"},{c:1,v:33,t:"e toda a cidade estava reunida à porta;"},{c:1,v:34,t:"e ele curou muitos doentes atacados de diversas moléstias, e expulsou muitos demônios; mas não permitia que os demônios falassem, porque o conheciam."},{c:1,v:35,t:"De madrugada, ainda bem escuro, levantou-se, saiu e foi a um lugar deserto, e ali orava."},{c:1,v:36,t:"Foram, pois, Simão e seus companheiros procurá-lo;"},{c:1,v:37,t:"quando o encontraram, disseram-lhe: Todos te buscam."},{c:1,v:38,t:"Respondeu-lhes Jesus: Vamos a outras partes, às povoações vizinhas, para que eu pregue ali também; pois para isso é que vim."},{c:1,v:39,t:"Foi, então, por toda a Galiléia, pregando nas sinagogas deles e expulsando os demônios."},{c:1,v:40,t:"E veio a ele um leproso que, de joelhos, lhe rogava, dizendo: Se quiseres, bem podes tornar-me limpo."},{c:1,v:41,t:"Jesus, pois, compadecido dele, estendendo a mão, tocou-o e disse-lhe: Quero; sê limpo."},{c:1,v:42,t:"Imediatamente desapareceu dele a lepra e ficou limpo."},{c:1,v:43,t:"E Jesus, advertindo-o secretamente, logo o despediu,"},{c:1,v:44,t:"dizendo-lhe: Olha, não digas nada a ninguém; mas vai, mostra-te ao sacerdote e oferece pela tua purificação o que Moisés determinou, para lhes servir de testemunho."},{c:1,v:45,t:"Ele, porém, saindo dali, começou a publicar o caso por toda parte e a divulgá-lo, de modo que Jesus já não podia entrar abertamente numa cidade, mas conservava-se fora em lugares desertos; e de todos os lados iam ter com ele."}],
    comentario: "Um dia inteiro em Cafarnaum: ensino, exorcismo na sinagoga, cura da sogra de Pedro, a cidade à porta ao anoitecer e a cura de um leproso. O ritmo é criado pela palavra imediatamente, que Marcos repete dezenas de vezes. Curar um leproso é, antes de tudo, devolver alguém ao convívio."
  },
  "Mc 2,1-12": {
    titulo: "Marcos 2,1-12",
    tipo: "biblia",
    versos: [{c:2,v:1,t:"Alguns dias depois entrou Jesus outra vez em Cafarnaum, e soube-se que ele estava em casa."},{c:2,v:2,t:"Ajuntaram-se, pois, muitos, a ponta de não caberem nem mesmo diante da porta; e ele lhes anunciava a palavra."},{c:2,v:3,t:"Nisso vieram alguns a trazer-lhe um paralítico, carregado por quatro;"},{c:2,v:4,t:"e não podendo aproximar-se dele, por causa da multidão, descobriram o telhado onde estava e, fazendo uma abertura, baixaram o leito em que jazia o paralítico."},{c:2,v:5,t:"E Jesus, vendo-lhes a fé, disse ao paralítico: Filho, perdoados são os teus pecados."},{c:2,v:6,t:"Ora, estavam ali sentados alguns dos escribas, que arrazoavam em seus corações, dizendo:"},{c:2,v:7,t:"Por que fala assim este homem? Ele blasfema. Quem pode perdoar pecados senão um só, que é Deus?"},{c:2,v:8,t:"Mas Jesus logo percebeu em seu espírito que eles assim arrazoavam dentro de si, e perguntou-lhes: Por que arrazoais desse modo em vossos corações?"},{c:2,v:9,t:"Qual é mais fácil? dizer ao paralítico: Perdoados são os teus pecados; ou dizer: Levanta-te, toma o teu leito, e anda?"},{c:2,v:10,t:"Ora, para que saibais que o Filho do homem tem sobre a terra autoridade para perdoar pecados ( disse ao paralítico ),"},{c:2,v:11,t:"a ti te digo, levanta-te, toma o teu leito, e vai para tua casa."},{c:2,v:12,t:"Então ele se levantou e, tomando logo o leito, saiu à vista de todos; de modo que todos pasmavam e glorificavam a Deus, dizendo: Nunca vimos coisa semelhante."}],
    comentario: "O paralítico descido pelo telhado. Antes de mandá-lo andar, Jesus declara perdoados os seus pecados — e os escribas presentes entendem imediatamente a implicação. É o primeiro conflito público do evangelho, e ele nasce de uma cura."
  },
  "Mc 4,35-41": {
    titulo: "Marcos 4,35-41",
    tipo: "biblia",
    versos: [{c:4,v:35,t:"Naquele dia, quando já era tarde, disse-lhes: Passemos para o outro lado."},{c:4,v:36,t:"E eles, deixando a multidão, o levaram consigo, assim como estava, no barco; e havia com ele também outros barcos."},{c:4,v:37,t:"E se levantou grande tempestade de vento, e as ondas batiam dentro do barco, de modo que já se enchia."},{c:4,v:38,t:"Ele, porém, estava na popa dormindo sobre a almofada; e despertaram-no, e lhe perguntaram: Mestre, não se te dá que pereçamos?"},{c:4,v:39,t:"E ele, levantando-se, repreendeu o vento, e disse ao mar: Cala-te, aquieta-te. E cessou o vento, e fez-se grande bonança."},{c:4,v:40,t:"Então lhes perguntou: Por que sois assim tímidos? Ainda não tendes fé?"},{c:4,v:41,t:"Encheram-se de grande temor, e diziam uns aos outros: Quem, porventura, é este, que até o vento e o mar lhe obedecem?"}],
    comentario: "A tempestade acalmada. Os verbos usados para repreender o vento são os mesmos dos exorcismos, e no imaginário bíblico o mar é o caos que só Deus domina. A pergunta final — quem é este? — revela a função do relato: cristologia narrada."
  },
  "Mc 5,21-43": {
    titulo: "Marcos 5,21-43",
    tipo: "biblia",
    versos: [{c:5,v:21,t:"Tendo Jesus passado de novo no barco para o outro lado, ajuntou-se a ele uma grande multidão; e ele estava à beira do mar."},{c:5,v:22,t:"Chegou um dos chefes da sinagoga, chamado Jairo e, logo que viu a Jesus, lançou-se-lhe aos pés."},{c:5,v:23,t:"e lhe rogava com instância, dizendo: Minha filhinha está nas últimas; rogo-te que venhas e lhe imponhas as mãos para que sare e viva."},{c:5,v:24,t:"Jesus foi com ele, e seguia-o uma grande multidão, que o apertava."},{c:5,v:25,t:"Ora, certa mulher, que havia doze anos padecia de uma hemorragia,"},{c:5,v:26,t:"e que tinha sofrido bastante às mãos de muitos médicos, e despendido tudo quanto possuía sem nada aproveitar, antes indo a pior,"},{c:5,v:27,t:"tendo ouvido falar a respeito de Jesus, veio por detrás, entre a multidão, e tocou-lhe o manto;"},{c:5,v:28,t:"porque dizia: Se tão-somente tocar-lhe as vestes, ficaria curada."},{c:5,v:29,t:"E imediatamente cessou a sua hemorragia; e sentiu no corpo estar já curada do seu mal."},{c:5,v:30,t:"E logo Jesus, percebendo em si mesmo que saíra dele poder, virou-se no meio da multidão e perguntou: Quem me tocou as vestes?"},{c:5,v:31,t:"Responderam-lhe os seus discípulos: Vês que a multidão te aperta, e perguntas: Quem me tocou?"},{c:5,v:32,t:"Mas ele olhava em redor para ver a que isto fizera."},{c:5,v:33,t:"Então a mulher, atemorizada e trêmula, cônscia do que nela se havia operado, veio e prostrou-se diante dele, e declarou-lhe toda a verdade."},{c:5,v:34,t:"Disse-lhe ele: Filha, a tua fé te salvou; vai-te em paz, e fica livre desse teu mal."},{c:5,v:35,t:"Enquanto ele ainda falava, chegaram pessoas da casa do chefe da sinagoga, a quem disseram: A tua filha já morreu; por que ainda incomodas o Mestre?"},{c:5,v:36,t:"O que percebendo Jesus, disse ao chefe da sinagoga: Não temas, crê somente."},{c:5,v:37,t:"E não permitiu que ninguém o acompanhasse, senão Pedro, Tiago, e João, irmão de Tiago."},{c:5,v:38,t:"Quando chegaram a casa do chefe da sinagoga, viu Jesus um alvoroço, e os que choravam e faziam grande pranto."},{c:5,v:39,t:"E, entrando, disse-lhes: Por que fazeis alvoroço e chorais? a menina não morreu, mas dorme."},{c:5,v:40,t:"E riam-se dele; porém ele, tendo feito sair a todos, tomou consigo o pai e a mãe da menina, e os que com ele vieram, e entrou onde a menina estava."},{c:5,v:41,t:"E, tomando a mão da menina, disse-lhe: Talita cumi, que, traduzido, é: Menina, a ti te digo, levanta-te."},{c:5,v:42,t:"Imediatamente a menina se levantou, e pôs-se a andar, pois tinha doze anos. E logo foram tomados de grande espanto."},{c:5,v:43,t:"Então ordenou-lhes expressamente que ninguém o soubesse; e mandou que lhe dessem de comer."}],
    comentario: "Duas histórias encaixadas, unidas pelo número doze: a menina tem doze anos, a mulher sangra há doze. Em vez de a impureza contaminar quem é tocado, a cura passa para quem toca. O aramaico Talitha kum ficou preservado no texto grego, com tradução ao lado."
  },
  "Mc 6,14-29": {
    titulo: "Marcos 6,14-29",
    tipo: "biblia",
    versos: [{c:6,v:14,t:"E soube disso o rei Herodes (porque o nome de Jesus se tornara célebre), e disse: João, o Batista, ressuscitou dos mortos; e por isso estes poderes milagrosos operam nele."},{c:6,v:15,t:"Mas outros diziam: É Elias. E ainda outros diziam: É profeta como um dos profetas."},{c:6,v:16,t:"Herodes, porém, ouvindo isso, dizia: É João, aquele a quem eu mandei degolar: ele ressuscitou."},{c:6,v:17,t:"Porquanto o próprio Herodes mandara prender a João, e encerrá-lo maniatado no cárcere, por causa de Herodias, mulher de seu irmão Filipe; porque ele se havia casado com ela."},{c:6,v:18,t:"Pois João dizia a Herodes: Não te é lícito ter a mulher de teu irmão."},{c:6,v:19,t:"Por isso Herodias lhe guardava rancor e queria matá-lo, mas não podia;"},{c:6,v:20,t:"porque Herodes temia a João, sabendo que era varão justo e santo, e o guardava em segurança; e, ao ouvi-lo, ficava muito perplexo, contudo de boa mente o escutava."},{c:6,v:21,t:"Chegado, porém, um dia oportuno quando Herodes no seu aniversário natalício ofereceu um banquete aos grandes da sua corte, aos principais da Galiléia,"},{c:6,v:22,t:"entrou a filha da mesma Herodias e, dançando, agradou a Herodes e aos convivas. Então o rei disse à jovem: Pede-me o que quiseres, e eu to darei."},{c:6,v:23,t:"E jurou-lhe, dizendo: Tudo o que me pedires te darei, ainda que seja metade do meu reino."},{c:6,v:24,t:"Tendo ela saído, perguntou a sua mãe: Que pedirei? Ela respondeu: A cabeça de João, o Batista."},{c:6,v:25,t:"E tornando logo com pressa à presença do rei, pediu, dizendo: Quero que imediatamente me dês num prato a cabeça de João, o Batista."},{c:6,v:26,t:"Ora, entristeceu-se muito o rei; todavia, por causa dos seus juramentos e por causa dos que estavam à mesa, não lha quis negar."},{c:6,v:27,t:"O rei, pois, enviou logo um soldado da sua guarda com ordem de trazer a cabeça de João. Então ele foi e o degolou no cárcere,"},{c:6,v:28,t:"e trouxe a cabeça num prato e a deu à jovem, e a jovem a deu à sua mãe."},{c:6,v:29,t:"Quando os seus discípulos ouviram isso, vieram, tomaram o seu corpo e o puseram num sepulcro."}],
    comentario: "A execução de João Batista contada em flashback. Marcos descreve um Antipas ambíguo, que temia João e gostava de ouvi-lo, preso pela própria promessa numa festa. Josefo dá outra explicação — medo de revolta — e situa a morte na fortaleza de Maquerus; as duas versões não se excluem."
  },
  "Mc 6,30-44": {
    titulo: "Marcos 6,30-44",
    tipo: "biblia",
    versos: [{c:6,v:30,t:"Reuniram-se os apóstolos com Jesus e contaram-lhe tudo o que tinham feito e ensinado."},{c:6,v:31,t:"Ao que ele lhes disse: Vinde vós, à parte, para um lugar deserto, e descansai um pouco. Porque eram muitos os que vinham e iam, e não tinham tempo nem para comer."},{c:6,v:32,t:"Retiraram-se, pois, no barco para um lugar deserto, à parte."},{c:6,v:33,t:"Muitos, porém, os viram partir, e os reconheceram; e para lá correram a pé de todas as cidades, e ali chegaram primeiro do que eles."},{c:6,v:34,t:"E Jesus, ao desembarcar, viu uma grande multidão e compadeceu-se deles, porque eram como ovelhas que não têm pastor; e começou a ensinar-lhes muitas coisas."},{c:6,v:35,t:"Estando a hora já muito adiantada, aproximaram-se dele seus discípulos e disseram: O lugar é deserto, e a hora já está muito adiantada;"},{c:6,v:36,t:"despede-os, para que vão aos sítios e às aldeias, em redor, e comprem para si o que comer."},{c:6,v:37,t:"Ele, porém, lhes respondeu: Dai-lhes vós de comer. Então eles lhe perguntaram: Havemos de ir comprar duzentos denários de pão e dar-lhes de comer?"},{c:6,v:38,t:"Ao que ele lhes disse: Quantos pães tendes? Ide ver. E, tendo-se informado, responderam: Cinco pães e dois peixes."},{c:6,v:39,t:"Então lhes ordenou que a todos fizessem reclinar-se, em grupos, sobre a relva verde."},{c:6,v:40,t:"E reclinaram-se em grupos de cem e de cinquenta."},{c:6,v:41,t:"E tomando os cinco pães e os dois peixes, e erguendo os olhos ao céu, os abençoou; partiu os pães e os entregava a seus discípulos para lhos servirem; também repartiu os dois peixes por todos."},{c:6,v:42,t:"E todos comeram e se fartaram."},{c:6,v:43,t:"Em seguida, recolheram doze cestos cheios dos pedaços de pão e de peixe."},{c:6,v:44,t:"Ora, os que comeram os pães eram cinco mil homens."}],
    comentario: "A multiplicação dos pães, único milagre nos quatro Evangelhos. Os quatro verbos — tomou, abençoou, partiu, deu — reaparecem na Última Ceia. Ninguém descreve o instante da multiplicação: há só o antes e as doze cestas de sobra, e a multidão sentada em grupos, como o acampamento do Êxodo."
  },
  "Jo 6,1-15": {
    titulo: "João 6,1-15",
    tipo: "biblia",
    versos: [{c:6,v:1,t:"Depois disto partiu Jesus para o outro lado do mar da Galiléia, também chamado de Tiberíades."},{c:6,v:2,t:"E seguia-o uma grande multidão, porque via os sinais que operava sobre os enfermos."},{c:6,v:3,t:"Subiu, pois, Jesus ao monte e sentou-se ali com seus discípulos."},{c:6,v:4,t:"Ora, a páscoa, a festa dos judeus, estava próxima."},{c:6,v:5,t:"Então Jesus, levantando os olhos, e vendo que uma grande multidão vinha ter com ele, disse a Felipe: Onde compraremos pão, para estes comerem?"},{c:6,v:6,t:"Mas dizia isto para o experimentar; pois ele bem sabia o que ia fazer."},{c:6,v:7,t:"Respondeu-lhe Felipe: Duzentos denários de pão não lhes bastam, para que cada um receba um pouco."},{c:6,v:8,t:"Ao que lhe disse um dos seus discípulos, André, irmão de Simão Pedro:"},{c:6,v:9,t:"Está aqui um rapaz que tem cinco pães de cevada e dois peixinhos; mas que é isto para tantos?"},{c:6,v:10,t:"Disse Jesus: Fazei reclinar-se o povo. Ora, naquele lugar havia muita relva. Reclinaram-se aí, pois, os homens em número de quase cinco mil."},{c:6,v:11,t:"Jesus, então, tomou os pães e, havendo dado graças, repartiu-os pelos que estavam reclinados; e de igual modo os peixes, quanto eles queriam."},{c:6,v:12,t:"E quando estavam saciados, disse aos seus discípulos: Recolhei os pedaços que sobejaram, para que nada se perca."},{c:6,v:13,t:"Recolheram-nos, pois e encheram doze cestos de pedaços dos cinco pães de cevada, que sobejaram aos que haviam comido."},{c:6,v:14,t:"Vendo, pois, aqueles homens o sinal que Jesus operara, diziam: este é verdadeiramente o profeta que havia de vir ao mundo."},{c:6,v:15,t:"Percebendo, pois, Jesus que estavam prestes a vir e levá-lo à força para o fazerem rei, tornou a retirar-se para o monte, ele sozinho."}],
    comentario: "A versão de João é a mais política: percebendo que queriam arrebatá-lo para fazê-lo rei, Jesus se retira sozinho para o monte. É um indício de por que um movimento assim preocupava Antipas e Roma. No dia seguinte virá o discurso do pão da vida, que afastará boa parte dos seguidores."
  },
  "Mc 6,45-52": {
    titulo: "Marcos 6,45-52",
    tipo: "biblia",
    versos: [{c:6,v:45,t:"Logo em seguida obrigou os seus discípulos a entrar no barco e passar adiante, para o outro lado, a Betsaida, enquanto ele despedia a multidão."},{c:6,v:46,t:"E, tendo-a despedido, foi ao monte para orar."},{c:6,v:47,t:"Chegada a tardinha, estava o barco no meio do mar, e ele sozinho em terra."},{c:6,v:48,t:"E, vendo-os fatigados a remar, porque o vento lhes era contrário, pela quarta vigília da noite, foi ter com eles, andando sobre o mar; e queria passar-lhes adiante;"},{c:6,v:49,t:"eles, porém, ao vê-lo andando sobre o mar, pensaram que era um fantasma e gritaram;"},{c:6,v:50,t:"porque todos o viram e se assustaram; mas ele imediatamente falou com eles e disse-lhes: Tende ânimo; sou eu; não temais."},{c:6,v:51,t:"E subiu para junto deles no barco, e o vento cessou; e ficaram, no seu íntimo, grandemente pasmados;"},{c:6,v:52,t:"pois não tinham compreendido o milagre dos pães, antes o seu coração estava endurecido."}],
    comentario: "Caminhar sobre as águas. A resposta de Jesus é ego eimi, eu sou — a fórmula do nome divino —, e Marcos acrescenta um detalhe antiquíssimo: queria passar ao lado deles, expressão que ecoa as teofanias a Moisés e Elias. Fecha com a dureza habitual sobre a incompreensão dos discípulos."
  },
  "Mt 14,22-33": {
    titulo: "Mateus 14,22-33",
    tipo: "biblia",
    versos: [{c:14,v:22,t:"Logo em seguida obrigou os seus discípulos a entrar no barco, e passar adiante dele para o outro lado, enquanto ele despedia as multidões."},{c:14,v:23,t:"Tendo-as despedido, subiu ao monte para orar à parte. Ao anoitecer, estava ali sozinho."},{c:14,v:24,t:"Entrementes, o barco já estava a muitos estádios da terra, açoitado pelas ondas; porque o vento era contrário."},{c:14,v:25,t:"Â quarta vigília da noite, foi Jesus ter com eles, andando sobre o mar."},{c:14,v:26,t:"Os discípulos, porém, ao vê-lo andando sobre o mar, assustaram-se e disseram: É um fantasma. E gritaram de medo."},{c:14,v:27,t:"Jesus, porém, imediatamente lhes falou, dizendo: Tende ânimo; sou eu; não temais."},{c:14,v:28,t:"Respondeu-lhe Pedro: Senhor! se és tu, manda-me ir ter contigo sobre as águas."},{c:14,v:29,t:"Disse-lhe ele: Vem. Pedro, descendo do barco, e andando sobre as águas, foi ao encontro de Jesus."},{c:14,v:30,t:"Mas, sentindo o vento, teve medo; e, começando a submergir, clamou: Senhor, salva-me."},{c:14,v:31,t:"Imediatamente estendeu Jesus a mão, segurou-o, e disse-lhe: Homem de pouca fé, por que duvidaste?"},{c:14,v:32,t:"E logo que subiram para o barco, o vento cessou."},{c:14,v:33,t:"Então os que estavam no barco adoraram-no, dizendo: Verdadeiramente tu és Filho de Deus."}],
    comentario: "Mateus acrescenta o episódio de Pedro, que caminha alguns passos, vê o vento e afunda. A frase homem de pouca fé virou proverbial. A cena termina com adoração e com a confissão de que ele é Filho de Deus — antecipação do que Pedro dirá em Cesareia."
  },
  "Mc 8,27-30": {
    titulo: "Marcos 8,27-30",
    tipo: "biblia",
    versos: [{c:8,v:27,t:"E saiu Jesus com os seus discípulos para as aldeias de Cesaréia de Filipe, e no caminho interrogou os discípulos, dizendo: Quem dizem os homens que eu sou?"},{c:8,v:28,t:"Responderam-lhe eles: Uns dizem: João, o Batista; outros: Elias; e ainda outros: Algum dos profetas."},{c:8,v:29,t:"Então lhes perguntou: Mas vós, quem dizeis que eu sou? Respondendo, Pedro lhe disse: Tu és o Cristo."},{c:8,v:30,t:"E ordenou-lhes Jesus que a ninguém dissessem aquilo a respeito dele."}],
    comentario: "A confissão de Pedro na versão mais antiga: tu és o Cristo, seguido da ordem de não dizer isso a ninguém. Não há chaves nem igreja — esses elementos aparecem só em Mateus. Logo depois vem o primeiro anúncio da paixão e a repreensão mais dura que Jesus dirige a alguém."
  },
  "Mt 16,13-20": {
    titulo: "Mateus 16,13-20",
    tipo: "biblia",
    versos: [{c:16,v:13,t:"Tendo Jesus chegado às regiões de Cesaréia de Felipe, interrogou os seus discípulos, dizendo: Quem dizem os homens ser o Filho do homem?"},{c:16,v:14,t:"Responderam eles: Uns dizem que é João, o Batista; outros, Elias; outros, Jeremias, ou algum dos profetas."},{c:16,v:15,t:"Mas vós, perguntou-lhes Jesus, quem dizeis que eu sou?"},{c:16,v:16,t:"Respondeu-lhe Simão Pedro: Tu és o Cristo, o Filho do Deus vivo."},{c:16,v:17,t:"Disse-lhe Jesus: Bem-aventurado és tu, Simão Barjonas, porque não foi carne e sangue que to revelou, mas meu Pai, que está nos céus."},{c:16,v:18,t:"Pois também eu te digo que tu és Pedro, e sobre esta pedra edificarei a minha igreja, e as portas do hades não prevalecerão contra ela;"},{c:16,v:19,t:"dar-te-ei as chaves do reino dos céus; o que ligares, pois, na terra será ligado nos céus, e o que desligares na terra será desligado nos céus."},{c:16,v:20,t:"Então ordenou aos discípulos que a ninguém dissessem que ele era o Cristo."}],
    comentario: "Aqui está o texto mais disputado do cristianismo ocidental: tu és Pedro, e sobre esta pedra edificarei a minha igreja. Católicos leem o fundamento do papado; ortodoxos, a fé confessada e primazia de honra; a Reforma, a confissão e não a pessoa. A palavra igreja só aparece nos Evangelhos neste livro."
  },
  "Mc 9,2-8": {
    titulo: "Marcos 9,2-8",
    tipo: "biblia",
    versos: [{c:9,v:2,t:"Seis dias depois tomou Jesus consigo a Pedro, a Tiago, e a João, e os levou à parte sós, a um alto monte; e foi transfigurado diante deles;"},{c:9,v:3,t:"as suas vestes tornaram-se resplandecentes, extremamente brancas, tais como nenhum lavandeiro sobre a terra as poderia branquear."},{c:9,v:4,t:"E apareceu-lhes Elias com Moisés, e falavam com Jesus."},{c:9,v:5,t:"Pedro, tomando a palavra, disse a Jesus: Mestre, bom é estarmos aqui; faça-mos, pois, três cabanas, uma para ti, outra para Moisés, e outra para Elias."},{c:9,v:6,t:"Pois não sabia o que havia de dizer, porque ficaram atemorizados."},{c:9,v:7,t:"Nisto veio uma nuvem que os cobriu, e dela saiu uma voz que dizia: Este é o meu Filho amado; a ele ouvi."},{c:9,v:8,t:"De repente, tendo olhado em redor, não viram mais a ninguém consigo, senão só a Jesus."}],
    comentario: "A Transfiguração, com a comparação caseira de Marcos: vestes mais brancas do que qualquer lavadeiro conseguiria. A nuvem é a mesma que cobria a tenda do encontro, e a voz repete o batismo acrescentando um imperativo: a ele ouvi. No Oriente, esta luz é energia incriada de Deus, não símbolo."
  },
  "Lc 10,25-37": {
    titulo: "Lucas 10,25-37",
    tipo: "biblia",
    versos: [{c:10,v:25,t:"E eis que se levantou certo doutor da lei e, para o experimentar, disse: Mestre, que farei para herdar a vida eterna?"},{c:10,v:26,t:"Perguntou-lhe Jesus: Que está escrito na lei? Como lês tu?"},{c:10,v:27,t:"Respondeu-lhe ele: Amarás ao Senhor teu Deus de todo o teu coração, de toda a tua alma, de todas as tuas forças e de todo o teu entendimento, e ao teu próximo como a ti mesmo."},{c:10,v:28,t:"Tornou-lhe Jesus: Respondeste bem; faze isso, e viverás."},{c:10,v:29,t:"Ele, porém, querendo justificar-se, perguntou a Jesus: E quem é o meu próximo?"},{c:10,v:30,t:"Jesus, prosseguindo, disse: Um homem descia de Jerusalém a Jericó, e caiu nas mãos de salteadores, os quais o despojaram e espancando-o, se retiraram, deixando-o meio morto."},{c:10,v:31,t:"Casualmente, descia pelo mesmo caminho certo sacerdote; e vendo-o, passou de largo."},{c:10,v:32,t:"De igual modo também um levita chegou àquele lugar, viu-o, e passou de largo."},{c:10,v:33,t:"Mas um samaritano, que ia de viagem, chegou perto dele e, vendo-o, encheu-se de compaixão;"},{c:10,v:34,t:"e aproximando-se, atou-lhe as feridas, deitando nelas azeite e vinho; e pondo-o sobre a sua cavalgadura, levou-o para uma estalagem e cuidou dele."},{c:10,v:35,t:"No dia seguinte tirou dois denários, deu-os ao hospedeiro e disse-lhe: Cuida dele; e tudo o que gastares a mais, eu to pagarei quando voltar."},{c:10,v:36,t:"Qual, pois, destes três te parece ter sido o próximo daquele que caiu nas mãos dos salteadores?"},{c:10,v:37,t:"Respondeu o doutor da lei: Aquele que usou de misericórdia para com ele. Disse-lhe, pois, Jesus: Vai, e faze tu o mesmo."}],
    comentario: "O bom samaritano. A estrada de Jerusalém a Jericó desce mais de mil metros em vinte e sete quilômetros e era conhecida por assaltos. O herói é um herege aos olhos do auditório, e a pergunta inicial é invertida no fim: não quem é meu próximo, mas quem se fez próximo."
  },
  "Lc 15,11-32": {
    titulo: "Lucas 15,11-32",
    tipo: "biblia",
    versos: [{c:15,v:11,t:"Disse-lhe mais: Certo homem tinha dois filhos."},{c:15,v:12,t:"O mais moço deles disse ao pai: Pai, dá-me a parte dos bens que me toca. Repartiu-lhes, pois, os seus haveres."},{c:15,v:13,t:"Poucos dias depois, o filho mais moço ajuntando tudo, partiu para um país distante, e ali desperdiçou os seus bens, vivendo dissolutamente."},{c:15,v:14,t:"E, havendo ele dissipado tudo, houve naquela terra uma grande fome, e começou a passar necessidades."},{c:15,v:15,t:"Então foi encontrar-se a um dos cidadãos daquele país, o qual o mandou para os seus campos a apascentar porcos."},{c:15,v:16,t:"E desejava encher o estômago com as alfarrobas que os porcos comiam; e ninguém lhe dava nada."},{c:15,v:17,t:"Caindo, porém, em si, disse: Quantos empregados de meu pai têm abundância de pão, e eu aqui pereço de fome!"},{c:15,v:18,t:"Levantar-me-ei, irei ter com meu pai e dir-lhe-ei: Pai, pequei contra o céu e diante de ti;"},{c:15,v:19,t:"já não sou digno de ser chamado teu filho; trata-me como um dos teus empregados."},{c:15,v:20,t:"Levantou-se, pois, e foi para seu pai. Estando ele ainda longe, seu pai o viu, encheu-se de compaixão e, correndo, lançou-se-lhe ao pescoço e o beijou."},{c:15,v:21,t:"Disse-lhe o filho: Pai, pequei conta o céu e diante de ti; já não sou digno de ser chamado teu filho."},{c:15,v:22,t:"Mas o pai disse aos seus servos: Trazei depressa a melhor roupa, e vesti-lha, e ponde-lhe um anel no dedo e alparcas nos pés;"},{c:15,v:23,t:"trazei também o bezerro, cevado e matai-o; comamos, e regozijemo-nos,"},{c:15,v:24,t:"porque este meu filho estava morto, e reviveu; tinha-se perdido, e foi achado. E começaram a regozijar-se."},{c:15,v:25,t:"Ora, o seu filho mais velho estava no campo; e quando voltava, ao aproximar-se de casa, ouviu a música e as danças;"},{c:15,v:26,t:"e chegando um dos servos, perguntou-lhe que era aquilo."},{c:15,v:27,t:"Respondeu-lhe este: Chegou teu irmão; e teu pai matou o bezerro cevado, porque o recebeu são e salvo."},{c:15,v:28,t:"Mas ele se indignou e não queria entrar. Saiu então o pai e instava com ele."},{c:15,v:29,t:"Ele, porém, respondeu ao pai: Eis que há tantos anos te sirvo, e nunca transgredi um mandamento teu; contudo nunca me deste um cabrito para eu me regozijar com os meus amigos;"},{c:15,v:30,t:"vindo, porém, este teu filho, que desperdiçou os teus bens com as meretrizes, mataste-lhe o bezerro cevado."},{c:15,v:31,t:"Replicou-lhe o pai: Filho, tu sempre estás comigo, e tudo o que é meu é teu;"},{c:15,v:32,t:"era justo, porém, regozijarmo-nos e alegramo-nos, porque este teu irmão estava morto, e reviveu; tinha-se perdido, e foi achado."}],
    comentario: "O filho pródigo. Pedir a herança em vida equivalia a desejar a morte do pai; um homem de posição correndo em público era indignidade. A parábola não termina na festa: fica em aberto se o filho mais velho, que ficou e obedeceu, aceita entrar."
  },
  "Jo 7,53–8,11": {
    titulo: "João 7,53–8,11",
    tipo: "biblia",
    versos: [{c:7,v:53,t:"[E cada um foi para sua casa."},{c:8,v:1,t:"Mas Jesus foi para o Monte das Oliveiras."},{c:8,v:2,t:"Pela manhã cedo voltou ao templo, e todo o povo vinha ter com ele; e Jesus, sentando-se o ensinava."},{c:8,v:3,t:"Então os escribas e fariseus trouxeram-lhe uma mulher apanhada em adultério; e pondo-a no meio,"},{c:8,v:4,t:"disseram-lhe: Mestre, esta mulher foi apanhada em flagrante adultério."},{c:8,v:5,t:"Ora, Moisés nos ordena na lei que as tais sejam apedrejadas. Tu, pois, que dizes?"},{c:8,v:6,t:"Isto diziam eles, tentando-o, para terem de que o acusar. Jesus, porém, inclinando-se, começou a escrever no chão com o dedo."},{c:8,v:7,t:"Mas, como insistissem em perguntar-lhe, ergueu-se e disse- lhes: Aquele dentre vós que está sem pecado seja o primeiro que lhe atire uma pedra."},{c:8,v:8,t:"E, tornando a inclinar-se, escrevia na terra."},{c:8,v:9,t:"Quando ouviram isto foram saindo um a um, a começar pelos mais velhos, até os últimos; ficou só Jesus, e a mulher ali em pé."},{c:8,v:10,t:"Então, erguendo-se Jesus e não vendo a ninguém senão a mulher, perguntou-lhe: Mulher, onde estão aqueles teus acusadores? Ninguém te condenou?"},{c:8,v:11,t:"Respondeu ela: Ninguém, Senhor. E disse-lhe Jesus: Nem eu te condeno; vai-te, e não peques mais.]"}],
    comentario: "A mulher adúltera — o episódio mais famoso de João que não estava em João. Falta nos manuscritos gregos mais antigos e migra de lugar entre cópias, inclusive para dentro de Lucas. É provavelmente tradição antiga que circulou solta antes de encontrar abrigo no texto; Bíblias de estudo a trazem entre colchetes."
  },
  "Lc 8,1-3": {
    titulo: "Lucas 8,1-3",
    tipo: "biblia",
    versos: [{c:8,v:1,t:"Logo depois disso, andava Jesus de cidade em cidade, e de aldeia em aldeia, pregando e anunciando o evangelho do reino de Deus; e iam com ele os doze,"},{c:8,v:2,t:"bem como algumas mulheres que haviam sido curadas de espíritos malignos e de enfermidades: Maria, chamada Madalena, da qual tinham saído sete demônios."},{c:8,v:3,t:"Joana, mulher de Cuza, procurador de Herodes, Susana, e muitas outras que os serviam com os seus bens."}],
    comentario: "Três versículos com um dado social notável: mulheres acompanhavam o grupo e o sustentavam com seus bens, uma delas casada com um administrador de Herodes. Ninguém inventaria isso depois — é justamente por ser incômodo que historiadores tratam a informação como antiga."
  },
  "Mc 15,40-41": {
    titulo: "Marcos 15,40-41",
    tipo: "biblia",
    versos: [{c:15,v:40,t:"Também ali estavam algumas mulheres olhando de longe, entre elas Maria Madalena, Maria, mãe de Tiago o Menor e de José, e Salomé;"},{c:15,v:41,t:"as quais o seguiam e o serviam quando ele estava na Galiléia; e muitas outras que tinham subido com ele a Jerusalém."}],
    comentario: "Na crucificação, Marcos anota que as mulheres o seguiam e serviam desde a Galileia e que estavam ali, olhando de longe. É o contraponto silencioso à fuga dos discípulos, narrada poucos versículos antes."
  },
  "Jo 11,1-53": {
    titulo: "João 11,1-53",
    tipo: "biblia",
    versos: [{c:11,v:1,t:"Ora, estava enfermo um homem chamado Lázaro, de Betânia, aldeia de Maria e de sua irmã Marta."},{c:11,v:2,t:"E Maria, cujo irmão Lázaro se achava enfermo, era a mesma que ungiu o Senhor com bálsamo, e lhe enxugou os pés com os seus cabelos."},{c:11,v:3,t:"Mandaram, pois, as irmãs dizer a Jesus: Senhor, eis que está enfermo aquele que tu amas."},{c:11,v:4,t:"Jesus, porém, ao ouvir isto, disse: Esta enfermidade não é para a morte, mas para glória de Deus, para que o Filho de Deus seja glorificado por ela."},{c:11,v:5,t:"Ora, Jesus amava a Marta, e a sua irmã, e a Lázaro."},{c:11,v:6,t:"Quando, pois, ouviu que estava enfermo, ficou ainda dois dias no lugar onde se achava."},{c:11,v:7,t:"Depois disto, disse a seus discípulos: Vamos outra vez para Judéia."},{c:11,v:8,t:"Disseram-lhe eles: Rabi, ainda agora os judeus procuravam apedrejar-te, e voltas para lá?"},{c:11,v:9,t:"Respondeu Jesus: Não são doze as horas do dia? Se alguém andar de dia, não tropeça, porque vê a luz deste mundo;"},{c:11,v:10,t:"mas se andar de noite, tropeça, porque nele não há luz."},{c:11,v:11,t:"E, tendo assim falado, acrescentou: Lázaro, o nosso amigo, dorme, mas vou despertá-lo do sono."},{c:11,v:12,t:"Disseram-lhe, pois, os discípulos: Senhor, se dorme, ficará bom."},{c:11,v:13,t:"Mas Jesus falara da sua morte; eles, porém, entenderam que falava do repouso do sono."},{c:11,v:14,t:"Então Jesus lhes disse claramente: Lázaro morreu;"},{c:11,v:15,t:"e, por vossa causa, folgo de que eu lá não estivesse, para para que creiais; mas vamos ter com ele."},{c:11,v:16,t:"Disse, pois, Tomé, chamado Dídimo, aos seus condiscípulos: Vamos nós também, para morrermos com ele."},{c:11,v:17,t:"Chegando pois Jesus, encontrou-o já com quatro dias de sepultura."},{c:11,v:18,t:"Ora, Betânia distava de Jerusalém cerca de quinze estádios."},{c:11,v:19,t:"E muitos dos judeus tinham vindo visitar Marta e Maria, para as consolar acerca de seu irmão."},{c:11,v:20,t:"Marta, pois, ao saber que Jesus chegava, saiu-lhe ao encontro; Maria, porém, ficou sentada em casa."},{c:11,v:21,t:"Disse, pois, Marta a Jesus: Senhor, se meu irmão não teria morrido."},{c:11,v:22,t:"E mesmo agora sei que tudo quanto pedires a Deus, Deus to concederá."},{c:11,v:23,t:"Respondeu-lhe Jesus: Teu irmão há de ressurgir."},{c:11,v:24,t:"Disse-lhe Marta: Sei que ele há de ressurgir na ressurreição, no último dia."},{c:11,v:25,t:"Declarou-lhe Jesus: Eu sou a ressurreição e a vida; quem crê em mim, ainda que morra, viverá;"},{c:11,v:26,t:"e todo aquele que vive, e crê em mim, jamais morrerá. Crês isto?"},{c:11,v:27,t:"Respondeu-lhe Marta: Sim, Senhor, eu creio que tu és o Cristo, o Filho de Deus, que havia de vir ao mundo."},{c:11,v:28,t:"Dito isto, retirou-se e foi chamar em segredo a Maria, sua irmã, e lhe disse: O Mestre está aí, e te chama."},{c:11,v:29,t:"Ela, ouvindo isto, levantou-se depressa, e foi ter com ele."},{c:11,v:30,t:"Pois Jesus ainda não havia entrado na aldeia, mas estava no lugar onde Marta o encontrara."},{c:11,v:31,t:"Então os judeus que estavam com Maria em casa e a consolavam, vendo-a levantar-se apressadamente e sair, seguiram-na, pensando que ia ao sepulcro para chorar ali."},{c:11,v:32,t:"Tendo, pois, Maria chegado ao lugar onde Jesus estava, e vendo-a, lançou-se-lhe aos pés e disse: Senhor, se tu estiveras aqui, meu irmão não teria morrido."},{c:11,v:33,t:"Jesus, pois, quando a viu chorar, e chorarem também os judeus que com ela vinham, comoveu-se em espírito, e perturbou-se,"},{c:11,v:34,t:"e perguntou: Onde o puseste? Responderam-lhe: Senhor, vem e vê."},{c:11,v:35,t:"Jesus chorou."},{c:11,v:36,t:"Disseram então os judeus: Vede como o amava."},{c:11,v:37,t:"Mas alguns deles disseram: Não podia ele, que abriu os olhos ao cego, fazer também que este não morreste?"},{c:11,v:38,t:"Jesus, pois, comovendo-se outra vez, profundamente, foi ao sepulcro; era uma gruta, e tinha uma pedra posta sobre ela."},{c:11,v:39,t:"Disse Jesus: Tirai a pedra. Marta, irmã do defunto, disse- lhe: Senhor, já cheira mal, porque está morto há quase quatro dias."},{c:11,v:40,t:"Respondeu-lhe Jesus: Não te disse que, se creres, verás a glória de Deus?"},{c:11,v:41,t:"Tiraram então a pedra. E Jesus, levantando os olhos ao céu, disse: Pai, graças te dou, porque me ouviste."},{c:11,v:42,t:"Eu sabia que sempre me ouves; mas por causa da multidão que está em redor é que assim falei, para que eles creiam que tu me enviaste."},{c:11,v:43,t:"E, tendo dito isso, clamou em alta voz: Lázaro, vem para fora!"},{c:11,v:44,t:"Saiu o que estivera morto, ligados os pés e as mãos com faixas, e o seu rosto envolto num lenço. Disse-lhes Jesus: Desligai-o e deixai-o ir."},{c:11,v:45,t:"Muitos, pois, dentre os judeus que tinham vindo visitar Maria, e que tinham visto o que Jesus fizera, creram nele."},{c:11,v:46,t:"Mas alguns deles foram ter com os fariseus e disseram-lhes o que Jesus tinha feito."},{c:11,v:47,t:"Então os principais sacerdotes e os fariseus reuniram o sinédrio e diziam: Que faremos? porquanto este homem vem operando muitos sinais."},{c:11,v:48,t:"Se o deixarmos assim, todos crerão nele, e virão os romanos, e nos tirarão tanto o nosso lugar como a nossa nação."},{c:11,v:49,t:"Um deles, porém, chamado Caifás, que era sumo sacerdote naquele ano, disse-lhes: Vós nada sabeis,"},{c:11,v:50,t:"nem considerais que vos convém que morra um só homem pelo povo, e que não pereça a nação toda."},{c:11,v:51,t:"Ora, isso não disse ele por si mesmo; mas, sendo o sumo sacerdote naquele ano, profetizou que Jesus havia de morrer pela nação,"},{c:11,v:52,t:"e não somente pela nação, mas também para congregar num só corpo os filhos de Deus que estão dispersos."},{c:11,v:53,t:"Desde aquele dia, pois, tomavam conselho para o matarem."}],
    comentario: "A ressurreição de Lázaro, sétimo e último sinal de João e clímax antes da paixão. Contém o versículo mais curto da Bíblia — Jesus chorou — e a declaração eu sou a ressurreição e a vida. O silêncio dos outros três Evangelhos sobre episódio de tal magnitude é o principal argumento para lê-lo como composição teológica."
  },
  "Mc 11,1-11": {
    titulo: "Marcos 11,1-11",
    tipo: "biblia",
    versos: [{c:11,v:1,t:"Ora, quando se aproximavam de Jerusalém, de Betfagé e de Betânia, junto do Monte das Oliveiras, enviou Jesus dois dos seus discípulos"},{c:11,v:2,t:"e disse-lhes: Ide à aldeia que está defronte de vós; e logo que nela entrardes, encontrareis preso um jumentinho, em que ainda ninguém montou; desprendei-o e trazei-o."},{c:11,v:3,t:"E se alguém vos perguntar: Por que fazeis isso? respondei: O Senhor precisa dele, e logo tornará a enviá-lo para aqui."},{c:11,v:4,t:"Foram, pois, e acharam o jumentinho preso ao portão do lado de fora na rua, e o desprenderam."},{c:11,v:5,t:"E alguns dos que ali estavam lhes perguntaram: Que fazeis, desprendendo o jumentinho?"},{c:11,v:6,t:"Responderam como Jesus lhes tinha mandado; e lho deixaram levar."},{c:11,v:7,t:"Então trouxeram a Jesus o jumentinho e lançaram sobre ele os seus mantos; e Jesus montou nele."},{c:11,v:8,t:"Muitos também estenderam pelo caminho os seus mantos, e outros, ramagens que tinham cortado nos campos."},{c:11,v:9,t:"E tanto os que o precediam como os que o seguiam, clamavam: Hosana! bendito o que vem em nome do Senhor!"},{c:11,v:10,t:"Bendito o reino que vem, o reino de nosso pai Davi! Hosana nas alturas!"},{c:11,v:11,t:"Tendo Jesus entrado em Jerusalém, foi ao templo; e tendo observado tudo em redor, como já fosse tarde, saiu para Betânia com os doze."}],
    comentario: "A entrada em Jerusalém montado num jumento cita Zacarias 9,9: um rei que chega humilde, não em cavalo de guerra. Marcos encerra o dia de modo anticlimático — Jesus olha tudo em volta e, como já era tarde, sai para Betânia."
  },
  "Mc 14,12-25": {
    titulo: "Marcos 14,12-25",
    tipo: "biblia",
    versos: [{c:14,v:12,t:"Ora, no primeiro dia dos pães ázimos, quando imolavam a páscoa, disseram-lhe seus discípulos: Aonde queres que vamos fazer os preparativos para comeres a páscoa?"},{c:14,v:13,t:"Enviou, pois, dois dos seus discípulos, e disse-lhes: Ide à cidade, e vos sairá ao encontro um homem levando um cântaro de água; seguí-o;"},{c:14,v:14,t:"e, onde ele entrar, dizei ao dono da casa: O Mestre manda perguntar: Onde está o meu aposento em que hei de comer a páscoa com os meus discípulos?"},{c:14,v:15,t:"E ele vos mostrará um grande cenáculo mobiliado e pronto; aí fazei-nos os preparativos."},{c:14,v:16,t:"Partindo, pois, os discípulos, foram à cidade, onde acharam tudo como ele lhes dissera, e prepararam a páscoa."},{c:14,v:17,t:"Ao anoitecer chegou ele com os doze."},{c:14,v:18,t:"E, quando estavam reclinados à mesa e comiam, disse Jesus: Em verdade vos digo que um de vós, que comigo come, há de trair-me."},{c:14,v:19,t:"Ao que eles começaram a entristecer-se e a perguntar-lhe um após outro: Porventura sou eu?"},{c:14,v:20,t:"Respondeu-lhes: É um dos doze, que mete comigo a mão no prato."},{c:14,v:21,t:"Pois o Filho do homem vai, conforme está escrito a seu respeito; mas ai daquele por quem o Filho do homem é traído! bom seria para esse homem se não houvera nascido."},{c:14,v:22,t:"Enquanto comiam, Jesus tomou pão e, abençoando-o, o partiu e deu-lho, dizendo: Tomai; isto é o meu corpo."},{c:14,v:23,t:"E tomando um cálice, rendeu graças e deu-lho; e todos beberam dele."},{c:14,v:24,t:"E disse-lhes: Isto é o meu sangue, o sangue do pacto, que por muitos é derramado."},{c:14,v:25,t:"Em verdade vos digo que não beberei mais do fruto da videira, até aquele dia em que o beber, novo, no reino de Deus."}],
    comentario: "A Última Ceia nos sinóticos é uma refeição pascal. As palavras sobre o pão e o cálice são o texto que a Reforma dividiria: presença real para Lutero, presença espiritual para Calvino, memorial para Zuínglio. Em João, a mesma noite não tem instituição eucarística — tem o lava-pés."
  },
  "Jo 13": {
    titulo: "João 13",
    tipo: "biblia",
    versos: [{c:13,v:1,t:"Antes da festa da páscoa, sabendo Jesus que era chegada a sua hora de passar deste mundo para o Pai, e havendo amado os seus que estavam no mundo, amou-os até o fim."},{c:13,v:2,t:"Enquanto ceavam, tendo já o Diabo posto no coração de Judas, filho de Simão Iscariotes, que o traísse,"},{c:13,v:3,t:"Jesus, sabendo que o Pai lhe entregara tudo nas mãos, e que viera de Deus e para Deus voltava,"},{c:13,v:4,t:"levantou-se da ceia, tirou o manto e, tomando uma toalha, cingiu-se."},{c:13,v:5,t:"Depois deitou água na bacia e começou a lavar os pés aos discípulos, e a enxugar-lhos com a toalha com que estava cingido."},{c:13,v:6,t:"Chegou, pois, a Simão Pedro, que lhe disse: Senhor, lavas-me os pés a mim?"},{c:13,v:7,t:"Respondeu-lhe Jesus: O que eu faço, tu não o sabes agora; mas depois o entenderás."},{c:13,v:8,t:"Tornou-lhe Pedro: Nunca me lavarás os pés. Replicou-lhe Jesus: Se eu não te lavar, não tens parte comigo."},{c:13,v:9,t:"Disse-lhe Simão Pedro: Senhor, não somente os meus pés, mas também as mãos e a cabeça."},{c:13,v:10,t:"Respondeu-lhe Jesus: Aquele que se banhou não necessita de lavar senão os pés, pois no mais está todo limpo; e vós estais limpos, mas não todos."},{c:13,v:11,t:"Pois ele sabia quem o estava traindo; por isso disse: Nem todos estais limpos."},{c:13,v:12,t:"Ora, depois de lhes ter lavado os pés, tomou o manto, tornou a reclinar-se à mesa e perguntou-lhes: Entendeis o que vos tenho feito?"},{c:13,v:13,t:"Vós me chamais Mestre e Senhor; e dizeis bem, porque eu o sou."},{c:13,v:14,t:"Ora, se eu, o Senhor e Mestre, vos lavei os pés, também vós deveis lavar os pés uns aos outros."},{c:13,v:15,t:"Porque eu vos dei exemplo, para que, como eu vos fiz, façais vós também."},{c:13,v:16,t:"Em verdade, em verdade vos digo: Não é o servo maior do que o seu senhor, nem o enviado maior do que aquele que o enviou."},{c:13,v:17,t:"Se sabeis estas coisas, bem-aventurados sois se as praticardes."},{c:13,v:18,t:"Não falo de todos vós; eu conheço aqueles que escolhi; mas para que se cumprisse a escritura: O que comia do meu pão, levantou contra mim o seu calcanhar."},{c:13,v:19,t:"Desde já no-lo digo, antes que suceda, para que, quando suceder, creiais que eu sou."},{c:13,v:20,t:"Em verdade, em verdade vos digo: Quem receber aquele que eu enviar, a mim me recebe; e quem me recebe a mim, recebe aquele que me enviou."},{c:13,v:21,t:"Tendo Jesus dito isto, turbou-se em espírito, e declarou: Em verdade, em verdade vos digo que um de vós me há de trair."},{c:13,v:22,t:"Os discípulos se entreolhavam, perplexos, sem saber de quem ele falava."},{c:13,v:23,t:"Ora, achava-se reclinado sobre o peito de Jesus um de seus discípulos, aquele a quem Jesus amava."},{c:13,v:24,t:"A esse, pois, fez Simão Pedro sinal, e lhe pediu: Pergunta- lhe de quem é que fala."},{c:13,v:25,t:"Aquele discípulo, recostando-se assim ao peito de Jesus, perguntou-lhe: Senhor, quem é?"},{c:13,v:26,t:"Respondeu Jesus: É aquele a quem eu der o pedaço de pão molhado. Tendo, pois, molhado um bocado de pão, deu-o a Judas, filho de Simão Iscariotes."},{c:13,v:27,t:"E, logo após o bocado, entrou nele Satanás. Disse-lhe, pois, Jesus: O que fazes, faze-o depressa."},{c:13,v:28,t:"E nenhum dos que estavam à mesa percebeu a que propósito lhe disse isto;"},{c:13,v:29,t:"pois, como Judas tinha a bolsa, pensavam alguns que Jesus lhe queria dizer: Compra o que nos é necessário para a festa; ou, que desse alguma coisa aos pobres."},{c:13,v:30,t:"Então ele, tendo recebido o bocado saiu logo. E era noite."},{c:13,v:31,t:"Tendo ele, pois, saído, disse Jesus: Agora é glorificado o Filho do homem, e Deus é glorificado nele;"},{c:13,v:32,t:"se Deus é glorificado nele, também Deus o glorificará em si mesmo, e logo o há de glorificar."},{c:13,v:33,t:"Filhinhos, ainda por um pouco estou convosco. Procurar-me- eis; e, como eu disse aos judeus, também a vós o digo agora: Para onde eu vou, não podeis vós ir."},{c:13,v:34,t:"Um novo mandamento vos dou: que vos ameis uns aos outros; assim como eu vos amei a vós, que também vós vos ameis uns aos outros."},{c:13,v:35,t:"Nisto conhecerão todos que sois meus discípulos, se tiverdes amor uns aos outros."},{c:13,v:36,t:"Perguntou-lhe Simão Pedro: Senhor, para onde vais? Respondeu Jesus; Para onde eu vou, não podes agora seguir-me; mais tarde, porém, me seguirás."},{c:13,v:37,t:"Disse-lhe Pedro: Por que não posso seguir-te agora? Por ti darei a minha vida."},{c:13,v:38,t:"Respondeu Jesus: Darás a tua vida por mim? Em verdade, em verdade te digo: Não cantará o galo até que me tenhas negado três vezes."}],
    comentario: "O capítulo inteiro da última noite em João: lava-pés, anúncio da traição, saída de Judas na noite e o mandamento novo. Nada de pão e cálice — a substituição é escolha teológica deliberada, e o gesto de serviço ocupa o lugar do rito."
  },
  "Jo 13,1-17": {
    titulo: "João 13,1-17",
    tipo: "biblia",
    versos: [{c:13,v:1,t:"Antes da festa da páscoa, sabendo Jesus que era chegada a sua hora de passar deste mundo para o Pai, e havendo amado os seus que estavam no mundo, amou-os até o fim."},{c:13,v:2,t:"Enquanto ceavam, tendo já o Diabo posto no coração de Judas, filho de Simão Iscariotes, que o traísse,"},{c:13,v:3,t:"Jesus, sabendo que o Pai lhe entregara tudo nas mãos, e que viera de Deus e para Deus voltava,"},{c:13,v:4,t:"levantou-se da ceia, tirou o manto e, tomando uma toalha, cingiu-se."},{c:13,v:5,t:"Depois deitou água na bacia e começou a lavar os pés aos discípulos, e a enxugar-lhos com a toalha com que estava cingido."},{c:13,v:6,t:"Chegou, pois, a Simão Pedro, que lhe disse: Senhor, lavas-me os pés a mim?"},{c:13,v:7,t:"Respondeu-lhe Jesus: O que eu faço, tu não o sabes agora; mas depois o entenderás."},{c:13,v:8,t:"Tornou-lhe Pedro: Nunca me lavarás os pés. Replicou-lhe Jesus: Se eu não te lavar, não tens parte comigo."},{c:13,v:9,t:"Disse-lhe Simão Pedro: Senhor, não somente os meus pés, mas também as mãos e a cabeça."},{c:13,v:10,t:"Respondeu-lhe Jesus: Aquele que se banhou não necessita de lavar senão os pés, pois no mais está todo limpo; e vós estais limpos, mas não todos."},{c:13,v:11,t:"Pois ele sabia quem o estava traindo; por isso disse: Nem todos estais limpos."},{c:13,v:12,t:"Ora, depois de lhes ter lavado os pés, tomou o manto, tornou a reclinar-se à mesa e perguntou-lhes: Entendeis o que vos tenho feito?"},{c:13,v:13,t:"Vós me chamais Mestre e Senhor; e dizeis bem, porque eu o sou."},{c:13,v:14,t:"Ora, se eu, o Senhor e Mestre, vos lavei os pés, também vós deveis lavar os pés uns aos outros."},{c:13,v:15,t:"Porque eu vos dei exemplo, para que, como eu vos fiz, façais vós também."},{c:13,v:16,t:"Em verdade, em verdade vos digo: Não é o servo maior do que o seu senhor, nem o enviado maior do que aquele que o enviou."},{c:13,v:17,t:"Se sabeis estas coisas, bem-aventurados sois se as praticardes."}],
    comentario: "O lava-pés era tarefa de escravo, e a resistência de Pedro mostra que ele entendeu o desconforto. A conclusão transforma o gesto em norma: se eu, o Mestre, lavei os vossos pés, também vós deveis lavar os pés uns dos outros."
  },
  "Mc 14,32-42": {
    titulo: "Marcos 14,32-42",
    tipo: "biblia",
    versos: [{c:14,v:32,t:"Então chegaram a um lugar chamado Getsêmane, e disse Jesus a seus discípulos: Sentai-vos aqui, enquanto eu oro."},{c:14,v:33,t:"E levou consigo a Pedro, a Tiago e a João, e começou a ter pavor e a angustiar-se;"},{c:14,v:34,t:"e disse-lhes: A minha alma está triste até a morte; ficai aqui e vigiai."},{c:14,v:35,t:"E adiantando-se um pouco, prostrou-se em terra; e orava para que, se fosse possível, passasse dele aquela hora."},{c:14,v:36,t:"E dizia: Aba, Pai, tudo te é possível; afasta de mim este cálice; todavia não seja o que eu quero, mas o que tu queres."},{c:14,v:37,t:"Voltando, achou-os dormindo; e disse a Pedro: Simão, dormes? não pudeste vigiar uma hora?"},{c:14,v:38,t:"Vigiai e orai, para que não entreis em tentação; o espírito, na verdade, está pronto, mas a carne é fraca."},{c:14,v:39,t:"Retirou-se de novo e orou, dizendo as mesmas palavras."},{c:14,v:40,t:"E voltando outra vez, achou-os dormindo, porque seus olhos estavam carregados; e não sabiam o que lhe responder."},{c:14,v:41,t:"Ao voltar pela terceira vez, disse-lhes: Dormi agora e descansai. - Basta; é chegada a hora. Eis que o Filho do homem está sendo entregue nas mãos dos pecadores."},{c:14,v:42,t:"Levantai-vos, vamo-nos; eis que é chegado aquele que me trai."}],
    comentario: "A agonia no Getsêmani. Jesus pede que o cálice passe e chama Deus de Abba, palavra aramaica preservada no texto grego. A pergunta clássica — se todos dormiam, quem ouviu a oração? — mostra o caráter construído da cena sem eliminar a memória de angústia real."
  },
  "Lc 22,44": {
    titulo: "Lucas 22,44",
    tipo: "biblia",
    versos: [{c:22,v:44,t:"E, posto em agonia, orava mais intensamente; e o seu suor tornou-se como grandes gotas de sangue, que caíam sobre o chão."}],
    comentario: "O suor como gotas de sangue aparece só em Lucas, e falta em manuscritos antigos importantes: é provável acréscimo. O fenômeno descrito (hematidrose) existe clinicamente, em situações de estresse extremo, o que alimenta as duas leituras — a médica e a literária."
  },
  "Mc 14,43-52": {
    titulo: "Marcos 14,43-52",
    tipo: "biblia",
    versos: [{c:14,v:43,t:"E logo, enquanto ele ainda falava, chegou Judas, um dos doze, e com ele uma multidão com espadas e varapaus, vinda da parte dos principais sacerdotes, dos escribas e dos anciãos."},{c:14,v:44,t:"Ora, o que o traía lhes havia dado um sinal, dizendo: Aquele que eu beijar, esse é; prendei-o e levai-o com segurança."},{c:14,v:45,t:"E, logo que chegou, aproximando-se de Jesus, disse: Rabi! E o beijou."},{c:14,v:46,t:"Ao que eles lhes lançaram as mãos, e o prenderam."},{c:14,v:47,t:"Mas um dos que ali estavam, puxando da espada, feriu o servo do sumo sacerdote e cortou-lhe uma orelha."},{c:14,v:48,t:"Disse-lhes Jesus: Saístes com espadas e varapaus para me prender, como a um salteador?"},{c:14,v:49,t:"Todos os dias estava convosco no templo, a ensinar, e não me prendestes; mas isto é para que se cumpram as Escrituras."},{c:14,v:50,t:"Nisto, todos o deixaram e fugiram."},{c:14,v:51,t:"Ora, seguia-o certo jovem envolto em um lençol sobre o corpo nu; e o agarraram."},{c:14,v:52,t:"Mas ele, largando o lençol, fugiu despido."}],
    comentario: "A prisão, com o beijo de Judas como sinal combinado. Marcos acrescenta um detalhe que ninguém explicou até hoje: um jovem que fugiu nu, deixando nas mãos dos guardas o lençol que o cobria."
  },
  "Jo 18,1-11": {
    titulo: "João 18,1-11",
    tipo: "biblia",
    versos: [{c:18,v:1,t:"Tendo Jesus dito isto, saiu com seus discípulos para o outro lado do ribeiro de Cedrom, onde havia um jardim, e com eles ali entrou."},{c:18,v:2,t:"Ora, Judas, que o traía, também conhecia aquele lugar, porque muitas vezes Jesus se reunira ali com os discípulos."},{c:18,v:3,t:"Tendo, pois, Judas tomado a coorte e uns guardas da parte dos principais sacerdotes e fariseus, chegou ali com lanternas archotes e armas."},{c:18,v:4,t:"Sabendo, pois, Jesus tudo o que lhe havia de suceder, adiantou-se e perguntou-lhes: A quem buscais?"},{c:18,v:5,t:"Responderam-lhe: A Jesus, o nazareno. Disse-lhes Jesus: Sou eu. E Judas, que o traía, também estava com eles."},{c:18,v:6,t:"Quando Jesus lhes disse: Sou eu, recuaram, e cairam por terra."},{c:18,v:7,t:"Tornou-lhes então a perguntar: A quem buscais? e responderam: A Jesus, o nazareno."},{c:18,v:8,t:"Replicou-lhes Jesus: Já vos disse que sou eu; se, pois, é a mim que buscais, deixai ir estes;"},{c:18,v:9,t:"para que se cumprisse a palavra que dissera: Dos que me tens dado, nenhum deles perdi."},{c:18,v:10,t:"Então Simão Pedro, que tinha uma espada, desembainhou-a e feriu o servo do sumo sacerdote, cortando-lhe a orelha direita. O nome do servo era Malco."},{c:18,v:11,t:"Disse, pois, Jesus a Pedro: Mete a tua espada na bainha; não hei de beber o cálice que o Pai me deu?"}],
    comentario: "Em João não há beijo nem angústia: Jesus se apresenta, a tropa recua e cai por terra ao ouvir eu sou, e ele negocia a saída dos discípulos. O evangelista constrói um Jesus que conduz a própria prisão, coerente com toda a sua cristologia."
  },
  "Mc 14,53-65": {
    titulo: "Marcos 14,53-65",
    tipo: "biblia",
    versos: [{c:14,v:53,t:"Levaram Jesus ao sumo sacerdote, e ajuntaram-se todos os principais sacerdotes, os anciãos e os escribas."},{c:14,v:54,t:"E Pedro o seguiu de longe até dentro do pátio do sumo sacerdote, e estava sentado com os guardas, aquentando-se ao fogo."},{c:14,v:55,t:"Os principais sacerdotes testemunho contra Jesus para o matar, e não o achavam."},{c:14,v:56,t:"Porque contra ele muitos depunham falsamente, mas os testemunhos não concordavam."},{c:14,v:57,t:"Levantaram-se por fim alguns que depunham falsamente contra ele, dizendo:"},{c:14,v:58,t:"Nós o ouvimos dizer: Eu destruirei este santuário, construído por mãos de homens, e em três dias edificarei outro, não feito por mãos de homens."},{c:14,v:59,t:"E nem assim concordava o seu testemunho."},{c:14,v:60,t:"Levantou-se então o sumo sacerdote no meio e perguntou a Jesus: Não respondes coisa alguma? Que é que estes depõem conta ti?"},{c:14,v:61,t:"Ele, porém, permaneceu calado, e nada respondeu. Tornou o sumo sacerdote a interrogá-lo, perguntando-lhe: És tu o Cristo, o Filho do Deus bendito?"},{c:14,v:62,t:"Respondeu Jesus: Eu o sou; e vereis o Filho do homem assentado à direita do Poder e vindo com as nuvens do céu."},{c:14,v:63,t:"Então o sumo sacerdote, rasgando as suas vestes, disse: Para que precisamos ainda de testemunhas?"},{c:14,v:64,t:"Acabais de ouvir a blasfêmia; que vos parece? E todos o condenaram como réu de morte."},{c:14,v:65,t:"E alguns começaram a cuspir nele, e a cobrir-lhe o rosto, e a dar-lhe socos, e a dizer-lhe: Profetiza. E os guardas receberam-no a bofetadas."}],
    comentario: "A audiência diante do sumo sacerdote. As testemunhas não concordam entre si, e a acusação decisiva nasce de uma pergunta direta sobre ser o Cristo. O procedimento — à noite, na véspera de festa, com sentença imediata — viola regras que a Mishná fixaria depois."
  },
  "Jo 18,12-24": {
    titulo: "João 18,12-24",
    tipo: "biblia",
    versos: [{c:18,v:12,t:"Então a coorte, e o comandante, e os guardas dos judeus prenderam a Jesus, e o maniataram."},{c:18,v:13,t:"E conduziram-no primeiramente a Anás; pois era sogro de Caifás, sumo sacerdote naquele ano."},{c:18,v:14,t:"Ora, Caifás era quem aconselhara aos judeus que convinha morrer um homem pelo povo."},{c:18,v:15,t:"Simão Pedro e outro discípulo seguiam a Jesus. Este discípulo era conhecido do sumo sacerdote, e entrou com Jesus no pátio do sumo sacerdote,"},{c:18,v:16,t:"enquanto Pedro ficava da parte de fora, à porta. Saiu, então, o outro discípulo que era conhecido do sumo sacerdote, falou à porteira, e levou Pedro para dentro."},{c:18,v:17,t:"Então a porteira perguntou a Pedro: Não és tu também um dos discípulos deste homem? Respondeu ele: Não sou."},{c:18,v:18,t:"Ora, estavam ali os servos e os guardas, que tinham acendido um braseiro e se aquentavam, porque fazia frio; e também Pedro estava ali em pé no meio deles, aquentando-se."},{c:18,v:19,t:"Então o sumo sacerdote interrogou Jesus acerca dos seus discípulos e da sua doutrina."},{c:18,v:20,t:"Respondeu-lhe Jesus: Eu tenho falado abertamente ao mundo; eu sempre ensinei nas sinagogas e no templo, onde todos os judeus se congregam, e nada falei em oculto."},{c:18,v:21,t:"Por que me perguntas a mim? pergunta aos que me ouviram o que é que lhes falei; eis que eles sabem o que eu disse."},{c:18,v:22,t:"E, havendo ele dito isso, um dos guardas que ali estavam deu uma bofetada em Jesus, dizendo: É assim que respondes ao sumo sacerdote?"},{c:18,v:23,t:"Respondeu-lhe Jesus: Se falei mal, dá testemunho do mal; mas, se bem, por que me feres?"},{c:18,v:24,t:"Então Anás o enviou, maniatado, a Caifás, o sumo sacerdote."}],
    comentario: "João acrescenta a passagem pela casa de Anás, sogro de Caifás e chefe da família sacerdotal, antes do interrogatório oficial. Também é o único a intercalar essa cena com as negações de Pedro, criando dois julgamentos simultâneos: o do mestre e o do discípulo."
  },
  "Mc 14,66-72": {
    titulo: "Marcos 14,66-72",
    tipo: "biblia",
    versos: [{c:14,v:66,t:"Ora, estando Pedro em baixo, no átrio, chegou uma das criadas do sumo sacerdote"},{c:14,v:67,t:"e, vendo a Pedro, que se estava aquentando, encarou-o e disse: Tu também estavas com o nazareno, esse Jesus."},{c:14,v:68,t:"Mas ele o negou, dizendo: Não sei nem compreendo o que dizes. E saiu para o alpendre."},{c:14,v:69,t:"E a criada, vendo-o, começou de novo a dizer aos que ali estavam: Esse é um deles."},{c:14,v:70,t:"Mas ele o negou outra vez. E pouco depois os que ali estavam disseram novamente a Pedro: Certamente tu és um deles; pois és também galileu."},{c:14,v:71,t:"Ele, porém, começou a praguejar e a jurar: Não conheço esse homem de quem falais."},{c:14,v:72,t:"Nesse instante o galo cantou pela segunda vez. E Pedro lembrou-se da palavra que lhe dissera Jesus: Antes que o galo cante duas vezes, três vezes me negarás. E caindo em si, começou a chorar."}],
    comentario: "As três negações, no pátio, junto ao fogo. Um relato que expõe o líder da comunidade primitiva em situação vexatória tem forte presunção de autenticidade — e é o sotaque galileu que o denuncia, detalhe linguístico precioso."
  },
  "Mc 15,1-15": {
    titulo: "Marcos 15,1-15",
    tipo: "biblia",
    versos: [{c:15,v:1,t:"Logo de manhã tiveram conselho os principais sacerdotes com os anciãos, os escribas e todo o sinédrio; e maniatando a Jesus, o levaram e o entregaram a Pilatos."},{c:15,v:2,t:"Pilatos lhe perguntou: És tu o rei dos judeus? Respondeu-lhe Jesus: É como dizes."},{c:15,v:3,t:"e os principais dos sacerdotes o acusavam de muitas coisas."},{c:15,v:4,t:"Tornou Pilatos a interrogá-lo, dizendo: Não respondes nada? Vê quantas acusações te fazem."},{c:15,v:5,t:"Mas Jesus nada mais respondeu, de maneira que Pilatos se admirava."},{c:15,v:6,t:"Ora, por ocasião da festa costumava soltar-lhes um preso qualquer que eles pedissem."},{c:15,v:7,t:"E havia um, chamado Barrabás, preso com outros sediciosos, os quais num motim haviam cometido um homicídio."},{c:15,v:8,t:"E a multidão subiu e começou a pedir o que lhe costumava fazer."},{c:15,v:9,t:"Ao que Pilatos lhes perguntou: Quereis que vos solte o rei dos judeus?"},{c:15,v:10,t:"Pois ele sabia que por inveja os principais sacerdotes lho haviam entregado."},{c:15,v:11,t:"Mas os principais sacerdotes incitaram a multidão a pedir que lhes soltasse antes a Barrabás."},{c:15,v:12,t:"E Pilatos, tornando a falar, perguntou-lhes: Que farei então daquele a quem chamais reis dos judeus?"},{c:15,v:13,t:"Novamente clamaram eles: Crucifica-o!"},{c:15,v:14,t:"Disse-lhes Pilatos: Mas que mal fez ele? Ao que eles clamaram ainda mais: Crucifica-o!"},{c:15,v:15,t:"Então Pilatos, querendo satisfazer a multidão, soltou-lhe Barrabás; e tendo mandado açoitar a Jesus, o entregou para ser crucificado."}],
    comentario: "Diante de Pilatos, a acusação muda de tom: de blasfêmia para pretensão régia, ameaça política que Roma julgava. A cena de Barrabás e a hesitação do prefeito contrastam com o administrador duro descrito por Fílon e Josefo — os textos cristãos tendem a aliviar Roma."
  },
  "Jo 18,28–19,16": {
    titulo: "João 18,28–19,16",
    tipo: "biblia",
    versos: [{c:18,v:28,t:"Depois conduziram Jesus da presença de Caifás para o pretório; era de manhã cedo; e eles não entraram no pretório, para não se contaminarem, mas poderem comer a páscoa."},{c:18,v:29,t:"Então Pilatos saiu a ter com eles, e perguntou: Que acusação trazeis contra este homem?"},{c:18,v:30,t:"Responderam-lhe: Se ele não fosse malfeitor, não to entregaríamos."},{c:18,v:31,t:"Disse-lhes, então, Pilatos: Tomai-o vós, e julgai-o segundo a vossa lei. Disseram-lhe os judeus: A nós não nos é lícito tirar a vida a ninguém."},{c:18,v:32,t:"Isso foi para que se cumprisse a palavra que dissera Jesus, significando de que morte havia de morrer."},{c:18,v:33,t:"Pilatos, pois, tornou a entrar no pretório, chamou a Jesus e perguntou-lhe: És tu o rei dos judeus?"},{c:18,v:34,t:"Respondeu Jesus: Dizes isso de ti mesmo, ou foram outros que to disseram de mim?"},{c:18,v:35,t:"Replicou Pilatos: Porventura sou eu judeu? O teu povo e os principais sacerdotes entregaram-te a mim; que fizeste?"},{c:18,v:36,t:"Respondeu Jesus: O meu reino não é deste mundo; se o meu reino fosse deste mundo, pelejariam os meus servos, para que eu não fosse entregue aos judeus; entretanto o meu reino não é daqui."},{c:18,v:37,t:"Perguntou-lhe, pois, Pilatos: Logo tu és rei? Respondeu Jesus: Tu dizes que eu sou rei. Eu para isso nasci, e para isso vim ao mundo, a fim de dar testemunho da verdade. Todo aquele que é da verdade ouve a minha voz."},{c:18,v:38,t:"Perguntou-lhe Pilatos: Que é a verdade? E dito isto, de novo saiu a ter com os judeus, e disse-lhes: Não acho nele crime algum."},{c:18,v:39,t:"Tendes, porém, por costume que eu vos solte alguém por ocasião da páscoa; quereis, pois, que vos solte o rei dos judeus?"},{c:18,v:40,t:"Então todos tornaram a clamar dizendo: Este não, mas Barrabás. Ora, Barrabás era salteador."},{c:19,v:1,t:"Nisso, pois, Pilatos tomou a Jesus, e mandou açoitá-lo."},{c:19,v:2,t:"E os soldados, tecendo uma coroa de espinhos, puseram-lha sobre a cabeça, e lhe vestiram um manto de púrpura;"},{c:19,v:3,t:"e chegando-se a ele, diziam: Salve, rei dos judeus! e e davam-lhe bofetadas."},{c:19,v:4,t:"Então Pilatos saiu outra vez, e disse-lhes: Eis aqui vo-lo trago fora, para que saibais que não acho nele crime algum."},{c:19,v:5,t:"Saiu, pois, Jesus, trazendo a coroa de espinhos e o manto de púrpura. E disse-lhes Pilatos: Eis o homem!"},{c:19,v:6,t:"Quando o viram os principais sacerdotes e os guardas, clamaram, dizendo: Crucifica-o! Crucifica-o! Disse-lhes Pilatos: Tomai-o vós, e crucificai-o; porque nenhum crime acho nele."},{c:19,v:7,t:"Responderam-lhe os judeus: Nós temos uma lei, e segundo esta lei ele deve morrer, porque se fez Filho de Deus."},{c:19,v:8,t:"Ora, Pilatos, quando ouviu esta palavra, mais atemorizado ficou;"},{c:19,v:9,t:"e entrando outra vez no pretório, perguntou a Jesus: Donde és tu? Mas Jesus não lhe deu resposta."},{c:19,v:10,t:"Disse-lhe, então, Pilatos: Não me respondes? não sabes que tenho autoridade para te soltar, e autoridade para te crucificar?"},{c:19,v:11,t:"Respondeu-lhe Jesus: Nenhuma autoridade terias sobre mim, se de cima não te fora dado; por isso aquele que me entregou a ti, maior pecado tem."},{c:19,v:12,t:"Daí em diante Pilatos procurava soltá-lo; mas os judeus clamaram: Se soltares a este, não és amigo de César; todo aquele que se faz rei é contra César."},{c:19,v:13,t:"Pilatos, pois, quando ouviu isto, trouxe Jesus para fora e sentou-se no tribunal, no lugar chamado Pavimento, e em hebraico Gabatá."},{c:19,v:14,t:"Ora, era a preparação da páscoa, e cerca da hora sexta. E disse aos judeus: Eis o vosso rei."},{c:19,v:15,t:"Mas eles clamaram: Tira-o! tira-o! crucifica-o! Disse-lhes Pilatos: Hei de crucificar o vosso rei? responderam, os principais sacerdotes: Não temos rei, senão César."},{c:19,v:16,t:"Então lho entregou para ser crucificado."}],
    comentario: "O julgamento romano em João, construído como diálogo sobre reino, verdade e poder, alternando dentro e fora do pretório. Inclui a frase que é o quê, a verdade? e o dado cronológico decisivo: aqui a condenação acontece na véspera da Páscoa, quando os cordeiros eram imolados — diferente dos sinóticos."
  },
  "Mc 15,15-20": {
    titulo: "Marcos 15,15-20",
    tipo: "biblia",
    versos: [{c:15,v:15,t:"Então Pilatos, querendo satisfazer a multidão, soltou-lhe Barrabás; e tendo mandado açoitar a Jesus, o entregou para ser crucificado."},{c:15,v:16,t:"Os soldados, pois, levaram-no para dentro, ao pátio, que é o pretório, e convocaram toda a coorte;"},{c:15,v:17,t:"vestiram-no de púrpura e puseram-lhe na cabeça uma coroa de espinhos que haviam tecido;"},{c:15,v:18,t:"e começaram a saudá-lo: Salve, rei dos judeus!"},{c:15,v:19,t:"Davam-lhe com uma cana na cabeça, cuspiam nele e, postos de joelhos, o adoravam."},{c:15,v:20,t:"Depois de o terem assim escarnecido, despiram-lhe a púrpura, e lhe puseram as vestes. Então o levaram para fora, a fim de o crucificarem."}],
    comentario: "A flagelação e o escárnio militar: manto de púrpura, coroa de espinhos, saudações de troça. O açoite romano precedia rotineiramente a crucificação e podia matar — é uma das explicações para a morte relativamente rápida na cruz."
  },
  "Jo 19,1-5": {
    titulo: "João 19,1-5",
    tipo: "biblia",
    versos: [{c:19,v:1,t:"Nisso, pois, Pilatos tomou a Jesus, e mandou açoitá-lo."},{c:19,v:2,t:"E os soldados, tecendo uma coroa de espinhos, puseram-lha sobre a cabeça, e lhe vestiram um manto de púrpura;"},{c:19,v:3,t:"e chegando-se a ele, diziam: Salve, rei dos judeus! e e davam-lhe bofetadas."},{c:19,v:4,t:"Então Pilatos saiu outra vez, e disse-lhes: Eis aqui vo-lo trago fora, para que saibais que não acho nele crime algum."},{c:19,v:5,t:"Saiu, pois, Jesus, trazendo a coroa de espinhos e o manto de púrpura. E disse-lhes Pilatos: Eis o homem!"}],
    comentario: "A cena do Ecce Homo: Pilatos apresenta o condenado à multidão com as palavras eis o homem. João transforma o escárnio em ironia teológica — quem é exibido como rei de mentira é, para o evangelista, o rei verdadeiro."
  },
  "Mc 15,16-20": {
    titulo: "Marcos 15,16-20",
    tipo: "biblia",
    versos: [{c:15,v:16,t:"Os soldados, pois, levaram-no para dentro, ao pátio, que é o pretório, e convocaram toda a coorte;"},{c:15,v:17,t:"vestiram-no de púrpura e puseram-lhe na cabeça uma coroa de espinhos que haviam tecido;"},{c:15,v:18,t:"e começaram a saudá-lo: Salve, rei dos judeus!"},{c:15,v:19,t:"Davam-lhe com uma cana na cabeça, cuspiam nele e, postos de joelhos, o adoravam."},{c:15,v:20,t:"Depois de o terem assim escarnecido, despiram-lhe a púrpura, e lhe puseram as vestes. Então o levaram para fora, a fim de o crucificarem."}],
    comentario: "O mesmo escárnio na versão de Marcos, dentro do pretório, com a coorte inteira reunida. A paródia de realeza é completa: manto, coroa, saudação e golpes com o caniço que fazia de cetro."
  },
  "Jo 19,2-5": {
    titulo: "João 19,2-5",
    tipo: "biblia",
    versos: [{c:19,v:2,t:"E os soldados, tecendo uma coroa de espinhos, puseram-lha sobre a cabeça, e lhe vestiram um manto de púrpura;"},{c:19,v:3,t:"e chegando-se a ele, diziam: Salve, rei dos judeus! e e davam-lhe bofetadas."},{c:19,v:4,t:"Então Pilatos saiu outra vez, e disse-lhes: Eis aqui vo-lo trago fora, para que saibais que não acho nele crime algum."},{c:19,v:5,t:"Saiu, pois, Jesus, trazendo a coroa de espinhos e o manto de púrpura. E disse-lhes Pilatos: Eis o homem!"}],
    comentario: "Repete a coroação de espinhos com o foco no gesto de exibição. É deste par de versículos que nasce toda uma iconografia — o Cristo coroado, de manto vermelho, apresentado ao povo — de Bosch a Ciseri."
  },
  "Mc 15,21-22": {
    titulo: "Marcos 15,21-22",
    tipo: "biblia",
    versos: [{c:15,v:21,t:"E obrigaram certo Simão, cireneu, pai de Alexandre e de Rufo, que por ali passava, vindo do campo, a carregar-lhe a cruz."},{c:15,v:22,t:"Levaram-no, pois, ao lugar do Gólgota, que quer dizer, lugar da Caveira."}],
    comentario: "Simão de Cirene é obrigado a carregar a cruz, e Marcos o identifica como pai de Alexandre e Rufo — sinal de que a família era conhecida da comunidade para a qual ele escrevia. O condenado carregava apenas a travessa horizontal; o poste já estava fixado no local."
  },
  "Lc 23,26-32": {
    titulo: "Lucas 23,26-32",
    tipo: "biblia",
    versos: [{c:23,v:26,t:"Quando o levaram dali tomaram um certo Simão, cireneu, que vinha do campo, e puseram-lhe a cruz às costas, para que a levasse após Jesus."},{c:23,v:27,t:"Seguia-o grande multidão de povo e de mulheres, as quais o pranteavam e lamentavam."},{c:23,v:28,t:"Jesus, porém, voltando-se para elas, disse: Filhas de Jerusalém, não choreis por mim; chorai antes por vós mesmas, e por vossos filhos."},{c:23,v:29,t:"Porque dias hão de vir em que se dirá: Bem-aventuradas as estéreis, e os ventres que não geraram, e os peitos que não amamentaram!"},{c:23,v:30,t:"Então começarão a dizer aos montes: Caí sobre nós; e aos outeiros: Cobri-nos."},{c:23,v:31,t:"Porque, se isto se faz no lenho verde, que se fará no seco?"},{c:23,v:32,t:"E levavam também com ele outros dois, que eram malfeitores, para serem mortos."}],
    comentario: "Lucas acrescenta as mulheres de Jerusalém que choravam, e a resposta dura: não choreis por mim, chorai por vós e por vossos filhos. A frase é lida por muitos exegetas como referência à catástrofe de 70, o que ajuda a datar a redação do evangelho."
  },
  "Mc 15,22-32": {
    titulo: "Marcos 15,22-32",
    tipo: "biblia",
    versos: [{c:15,v:22,t:"Levaram-no, pois, ao lugar do Gólgota, que quer dizer, lugar da Caveira."},{c:15,v:23,t:"E ofereciam-lhe vinho misturado com mirra; mas ele não o tomou."},{c:15,v:24,t:"Então o crucificaram, e repartiram entre si as vestes dele, lançando sortes sobre elas para ver o que cada um levaria."},{c:15,v:25,t:"E era a hora terceira quando o crucificaram."},{c:15,v:26,t:"Por cima dele estava escrito o título da sua acusação: O REI DOS JUDEUS."},{c:15,v:27,t:"Também, com ele, crucificaram dois salteadores, um à sua direita, e outro à esquerda."},{c:15,v:28,t:"[E cumpriu-se a escritura que diz: E com os malfeitores foi contado.]"},{c:15,v:29,t:"E os que iam passando blasfemavam dele, meneando a cabeça e dizendo: Ah! tu que destróis o santuário e em três dias o reedificas."},{c:15,v:30,t:"salva-te a ti mesmo, descendo da cruz."},{c:15,v:31,t:"De igual modo também os principais sacerdotes, com os escribas, escarnecendo-o, diziam entre si: A outros salvou; a si mesmo não pode salvar;"},{c:15,v:32,t:"desça agora da cruz o Cristo, o rei de Israel, para que vejamos e creiamos, Também os que com ele foram crucificados o injuriavam."}],
    comentario: "A crucificação em Marcos, contada com sobriedade quase administrativa: crucificaram-no, repartiram as vestes, era a hora terceira. O letreiro declara o motivo da pena — o rei dos judeus —, acusação política que confirma a natureza romana da execução."
  },
  "Jo 19,17-27": {
    titulo: "João 19,17-27",
    tipo: "biblia",
    versos: [{c:19,v:17,t:"Tomaram, pois, a Jesus; e ele, carregando a sua própria cruz, saiu para o lugar chamado Caveira, que em hebraico se chama Gólgota,"},{c:19,v:18,t:"onde o crucificaram, e com ele outros dois, um de cada lado, e Jesus no meio."},{c:19,v:19,t:"E Pilatos escreveu também um título, e o colocou sobre a cruz; e nele estava escrito: JESUS O NAZARENO, O REI DOS JUDEUS."},{c:19,v:20,t:"Muitos dos judeus, pois, leram este título; porque o lugar onde Jesus foi crucificado era próximo da cidade; e estava escrito em hebraico, latim e grego."},{c:19,v:21,t:"Diziam então a Pilatos os principais sacerdotes dos judeus: Não escrevas: O rei dos judeus; mas que ele disse: Sou rei dos judeus."},{c:19,v:22,t:"Respondeu Pilatos: O que escrevi, escrevi."},{c:19,v:23,t:"Tendo, pois, os soldados crucificado a Jesus, tomaram as suas vestes, e fizeram delas quatro partes, para cada soldado uma parte. Tomaram também a túnica; ora a túnica não tinha costura, sendo toda tecida de alto a baixo."},{c:19,v:24,t:"Pelo que disseram uns aos outros: Não a rasguemos, mas lancemos sortes sobre ela, para ver de quem será (para que se cumprisse a escritura que diz: Repartiram entre si as minhas vestes, e lançaram sortes). E, de fato, os soldados assim fizeram."},{c:19,v:25,t:"Estavam em pé, junto à cruz de Jesus, sua mãe, e a irmã de sua mãe, e Maria, mulher de Clôpas, e Maria Madalena."},{c:19,v:26,t:"Ora, Jesus, vendo ali sua mãe, e ao lado dela o discípulo a quem ele amava, disse a sua mãe: Mulher, eis aí o teu filho."},{c:19,v:27,t:"Então disse ao discípulo: Eis aí tua mãe. E desde aquela hora o discípulo a recebeu em sua casa."}],
    comentario: "João acrescenta a discussão sobre o letreiro escrito em três línguas, a túnica sem costura e, sobretudo, a cena da mãe e do discípulo amado, que fundou séculos de teologia mariana. Aqui Jesus carrega a própria cruz, sem Simão de Cirene."
  },
  "Mc 15,33-41": {
    titulo: "Marcos 15,33-41",
    tipo: "biblia",
    versos: [{c:15,v:33,t:"E, chegada a hora sexta, houve trevas sobre a terra, até a hora nona."},{c:15,v:34,t:"E, à hora nona, bradou Jesus em alta voz: Eloí, Eloí, lamá, sabactani? que, traduzido, é: Deus meu, Deus meu, por que me desamparaste?"},{c:15,v:35,t:"Alguns dos que ali estavam, ouvindo isso, diziam: Eis que chama por Elias."},{c:15,v:36,t:"Correu um deles, ensopou uma esponja em vinagre e, pondo-a numa cana, dava-lhe de beber, dizendo: Deixai, vejamos se Elias virá tirá-lo."},{c:15,v:37,t:"Mas Jesus, dando um grande brado, expirou."},{c:15,v:38,t:"Então o véu do santuário se rasgou em dois, de alto a baixo."},{c:15,v:39,t:"Ora, o centurião, que estava defronte dele, vendo-o assim expirar, disse: Verdadeiramente este homem era filho de Deus."},{c:15,v:40,t:"Também ali estavam algumas mulheres olhando de longe, entre elas Maria Madalena, Maria, mãe de Tiago o Menor e de José, e Salomé;"},{c:15,v:41,t:"as quais o seguiam e o serviam quando ele estava na Galiléia; e muitas outras que tinham subido com ele a Jerusalém."}],
    comentario: "A morte em Marcos: trevas por três horas, o grito Eloí, Eloí, lemá sabactâni — preservado em aramaico — e o véu do Templo rasgado. Quem faz a confissão final é um centurião romano. Nenhum eclipse é possível na lua cheia da Páscoa: a escuridão é linguagem apocalíptica."
  },
  "Lc 23,44-49": {
    titulo: "Lucas 23,44-49",
    tipo: "biblia",
    versos: [{c:23,v:44,t:"Era já quase a hora sexta, e houve trevas em toda a terra até a hora nona, pois o sol se escurecera;"},{c:23,v:45,t:"e rasgou-se ao meio o véu do santuário."},{c:23,v:46,t:"Jesus, clamando com grande voz, disse: Pai, nas tuas mãos entrego o meu espírito. E, havendo dito isso, expirou."},{c:23,v:47,t:"Quando o centurião viu o que acontecera, deu glória a Deus, dizendo: Na verdade, este homem era justo."},{c:23,v:48,t:"E todas as multidões que presenciaram este espetáculo, vendo o que havia acontecido, voltaram batendo no peito."},{c:23,v:49,t:"Entretanto, todos os conhecidos de Jesus, e as mulheres que o haviam seguido desde a Galiléia, estavam de longe vendo estas coisas."}],
    comentario: "Lucas troca o grito de abandono por uma entrega serena — Pai, nas tuas mãos entrego o meu espírito — e acrescenta o perdão aos algozes e o bom ladrão. As diferenças entre as últimas palavras nos quatro Evangelhos mostram quatro teologias da cruz."
  },
  "Jo 19,28-30": {
    titulo: "João 19,28-30",
    tipo: "biblia",
    versos: [{c:19,v:28,t:"Depois, sabendo Jesus que todas as coisas já estavam consumadas, para que se cumprisse a Escritura, disse: Tenho sede."},{c:19,v:29,t:"Estava ali um vaso cheio de vinagre. Puseram, pois, numa cana de hissopo uma esponja ensopada de vinagre, e lha chegaram à boca."},{c:19,v:30,t:"Então Jesus, depois de ter tomado o vinagre, disse: está consumado. E, inclinando a cabeça, entregou o espírito."}],
    comentario: "Em João, a última palavra é está consumado, e a morte é ato voluntário: ele inclina a cabeça e entrega o espírito. Tudo acontece na véspera da Páscoa, na hora em que os cordeiros eram imolados no Templo — a cronologia sustenta a teologia do Cordeiro."
  },
  "Mc 15,42-46": {
    titulo: "Marcos 15,42-46",
    tipo: "biblia",
    versos: [{c:15,v:42,t:"Ao cair da tarde, como era o dia da preparação, isto é, a véspera do sábado,"},{c:15,v:43,t:"José de Arimatéia, ilustre membro do sinédrio, que também esperava o reino de Deus, cobrando ânimo foi Pilatos e pediu o corpo de Jesus."},{c:15,v:44,t:"Admirou-se Pilatos de que já tivesse morrido; e chamando o centurião, perguntou-lhe se, de fato, havia morrido."},{c:15,v:45,t:"E, depois que o soube do centurião, cedeu o cadáver a José;"},{c:15,v:46,t:"o qual, tendo comprado um pano de linho, tirou da cruz o corpo, envolveu-o no pano e o depositou num sepulcro aberto em rocha; e rolou uma pedra para a porta do sepulcro."}],
    comentario: "José de Arimateia, membro do Sinédrio, pede o corpo a Pilatos. Que um crucificado fosse entregue para sepultamento é excepcional, mas atestado: o ossuário de Yehohanan, achado em Jerusalém em 1968, tem um calcanhar perfurado por um prego."
  },
  "Jo 19,38-40": {
    titulo: "João 19,38-40",
    tipo: "biblia",
    versos: [{c:19,v:38,t:"Depois disto, José de Arimatéia, que era discípulo de Jesus, embora oculto por medo dos judeus, rogou a Pilatos que lhe permitisse tirar o corpo de Jesus; e Pilatos lho permitiu. Então foi e o tirou."},{c:19,v:39,t:"E Nicodemos, aquele que anteriormente viera ter com Jesus de noite, foi também, levando cerca de cem libras duma mistura de mirra e aloés."},{c:19,v:40,t:"Tomaram, pois, o corpo de Jesus, e o envolveram em panos de linho com as especiarias, como os judeus costumavam fazer na preparação para a sepultura."}],
    comentario: "João acrescenta Nicodemos e uma quantidade absurda de mirra e aloés — cerca de trinta e quatro quilos, quantidade de funeral real. O gesto contradiz a pressa e serve para dizer, sem palavras, quem estava sendo sepultado."
  },
  "Jo 19,25-27": {
    titulo: "João 19,25-27",
    tipo: "biblia",
    versos: [{c:19,v:25,t:"Estavam em pé, junto à cruz de Jesus, sua mãe, e a irmã de sua mãe, e Maria, mulher de Clôpas, e Maria Madalena."},{c:19,v:26,t:"Ora, Jesus, vendo ali sua mãe, e ao lado dela o discípulo a quem ele amava, disse a sua mãe: Mulher, eis aí o teu filho."},{c:19,v:27,t:"Então disse ao discípulo: Eis aí tua mãe. E desde aquela hora o discípulo a recebeu em sua casa."}],
    comentario: "Junto à cruz estão a mãe, a irmã dela, Maria de Cléofas, Maria Madalena e o discípulo amado. A entrega mútua — eis o teu filho, eis a tua mãe — é lida na tradição católica como maternidade espiritual de Maria sobre a Igreja."
  },
  "Mc 15,46-47": {
    titulo: "Marcos 15,46-47",
    tipo: "biblia",
    versos: [{c:15,v:46,t:"o qual, tendo comprado um pano de linho, tirou da cruz o corpo, envolveu-o no pano e o depositou num sepulcro aberto em rocha; e rolou uma pedra para a porta do sepulcro."},{c:15,v:47,t:"E Maria Madalena e Maria, mãe de José, observavam onde fora posto."}],
    comentario: "O corpo é envolto em linho e posto num túmulo escavado na rocha, fechado com uma pedra. Marcos faz questão de registrar que as mulheres observavam onde ele fora colocado — detalhe que prepara a manhã de domingo e responde à objeção de que teriam ido ao túmulo errado."
  },
  "Jo 19,41-42": {
    titulo: "João 19,41-42",
    tipo: "biblia",
    versos: [{c:19,v:41,t:"No lugar onde Jesus foi crucificado havia um jardim, e nesse jardim um sepulcro novo, em que ninguém ainda havia sido posto."},{c:19,v:42,t:"Ali, pois, por ser a vespera do sábado dos judeus, e por estar perto aquele sepulcro, puseram a Jesus."}],
    comentario: "João situa o sepulcro num jardim próximo ao lugar da crucificação e explica a pressa pela véspera do sábado. A tradição identifica o local desde o século IV com o Santo Sepulcro; o Túmulo do Jardim, preferido por parte dos protestantes, foi identificado só no século XIX."
  },
  "Mc 16,1-8": {
    titulo: "Marcos 16,1-8",
    tipo: "biblia",
    versos: [{c:16,v:1,t:"Ora, passado o sábado, Maria Madalena, Maria, mãe de Tiago, e Salomé, compraram aromas para irem ungi-lo."},{c:16,v:2,t:"E, no primeiro dia da semana, foram ao sepulcro muito cedo, ao levantar do sol."},{c:16,v:3,t:"E diziam umas às outras: Quem nos revolverá a pedra da porta do sepulcro?"},{c:16,v:4,t:"Mas, levantando os olhos, notaram que a pedra, que era muito grande, já estava revolvida;"},{c:16,v:5,t:"e entrando no sepulcro, viram um moço sentado à direita, vestido de alvo manto; e ficaram atemorizadas."},{c:16,v:6,t:"Ele, porém, lhes disse: Não vos atemorizeis; buscais a Jesus, o nazareno, que foi crucificado; ele ressurgiu; não está aqui; eis o lugar onde o puseram."},{c:16,v:7,t:"Mas ide, dizei a seus discípulos, e a Pedro, que ele vai adiante de vós para a Galiléia; ali o vereis, como ele vos disse."},{c:16,v:8,t:"E, saindo elas, fugiram do sepulcro, porque estavam possuídas de medo e assombro; e não disseram nada a ninguém, porque temiam."}],
    comentario: "O final mais antigo de Marcos: mulheres encontram a pedra removida, um jovem de vestes brancas anuncia a ressurreição, e elas fogem tremendo e não dizem nada a ninguém, porque tinham medo. Os manuscritos mais antigos terminam exatamente aí — os versículos seguintes são acréscimo posterior."
  },
  "Jo 20": {
    titulo: "João 20",
    tipo: "biblia",
    versos: [{c:20,v:1,t:"No primeiro dia da semana Maria Madalena foi ao sepulcro de madrugada, sendo ainda escuro, e viu que a pedra fora removida do sepulcro."},{c:20,v:2,t:"Correu, pois, e foi ter com Simão Pedro, e o outro discípulo, a quem Jesus amava, e disse-lhes: Tiraram do sepulcro o Senhor, e não sabemos onde o puseram."},{c:20,v:3,t:"Saíram então Pedro e o outro discípulo e foram ao sepulcro."},{c:20,v:4,t:"Corriam os dois juntos, mas o outro discípulo correu mais ligeiro do que Pedro, e chegou primeiro ao sepulcro;"},{c:20,v:5,t:"e, abaixando-se viu os panos de linho ali deixados, todavia não entrou."},{c:20,v:6,t:"Chegou, pois, Simão Pedro, que o seguia, e entrou no sepulcro e viu os panos de linho ali deixados,"},{c:20,v:7,t:"e que o lenço, que estivera sobre a cabeça de Jesus, não estava com os panos, mas enrolado num lugar à parte."},{c:20,v:8,t:"Então entrou também o outro discípulo, que chegara primeiro ao sepulcro, e viu e creu."},{c:20,v:9,t:"Porque ainda não entendiam a escritura, que era necessário que ele ressurgisse dentre os mortos."},{c:20,v:10,t:"Tornaram, pois, os discípulos para casa."},{c:20,v:11,t:"Maria, porém, estava em pé, diante do sepulcro, a chorar. Enquanto chorava, abaixou-se a olhar para dentro do sepulcro,"},{c:20,v:12,t:"e viu dois anjos vestidos de branco sentados onde jazera o corpo de Jesus, um à cabeceira e outro aos pés."},{c:20,v:13,t:"E perguntaram-lhe eles: Mulher, por que choras? Respondeu- lhes: Porque tiraram o meu Senhor, e não sei onde o puseram."},{c:20,v:14,t:"Ao dizer isso, voltou-se para trás, e viu a Jesus ali em pé, mas não sabia que era Jesus."},{c:20,v:15,t:"Perguntou-lhe Jesus: Mulher, por que choras? A quem procuras? Ela, julgando que fosse o jardineiro, respondeu-lhe: Senhor, se tu o levaste, dize-me onde o puseste, e eu o levarei."},{c:20,v:16,t:"Disse-lhe Jesus: Maria! Ela, virando-se, disse-lhe em hebraico: Raboni! - que quer dizer, Mestre."},{c:20,v:17,t:"Disse-lhe Jesus: Deixa de me tocar, porque ainda não subi ao Pai; mas vai a meus irmãos e dize-lhes que eu subo para meu Pai e vosso Pai, meu Deus e vosso Deus."},{c:20,v:18,t:"E foi Maria Madalena anunciar aos discípulos: Vi o Senhor! - e que ele lhe dissera estas coisas."},{c:20,v:19,t:"Chegada, pois, a tarde, naquele dia, o primeiro da semana, e estando os discípulos reunidos com as portas cerradas por medo dos judeus, chegou Jesus, pôs-se no meio e disse-lhes: Paz seja convosco."},{c:20,v:20,t:"Dito isto, mostrou-lhes as mãos e o lado. Alegraram-se, pois, os discípulos ao verem o Senhor."},{c:20,v:21,t:"Disse-lhes, então, Jesus segunda vez: Paz seja convosco; assim como o Pai me enviou, também eu vos envio a vós."},{c:20,v:22,t:"E havendo dito isso, assoprou sobre eles, e disse-lhes: Recebei o Espírito Santo."},{c:20,v:23,t:"Âqueles a quem perdoardes os pecados, são-lhes perdoados; e àqueles a quem os retiverdes, são-lhes retidos."},{c:20,v:24,t:"Ora, Tomé, um dos doze, chamado Dídimo, não estava com eles quando veio Jesus."},{c:20,v:25,t:"Diziam-lhe, pois, ou outros discípulos: Vimos o Senhor. Ele, porém, lhes respondeu: Se eu não vir o sinal dos cravos nas mãos, e não meter a mão no seu lado, de maneira nenhuma crerei."},{c:20,v:26,t:"Oito dias depois estavam os discípulos outra vez ali reunidos, e Tomé com eles. Chegou Jesus, estando as portas fechadas, pôs-se no meio deles e disse: Paz seja convosco."},{c:20,v:27,t:"Depois disse a Tomé: Chega aqui o teu dedo, e vê as minhas mãos; chega a tua mão, e mete-a no meu lado; e não mais sejas incrédulo, mas crente."},{c:20,v:28,t:"Respondeu-lhe Tomé: Senhor meu, e Deus meu!"},{c:20,v:29,t:"Disse-lhe Jesus: Porque me viste, creste? Bem-aventurados os que não viram e creram."},{c:20,v:30,t:"Jesus, na verdade, operou na presença de seus discípulos ainda muitos outros sinais que não estão escritos neste livro;"},{c:20,v:31,t:"estes, porém, estão escritos para que creiais que Jesus é o Cristo, o Filho de Deus, e para que, crendo, tenhais vida em seu nome."}],
    comentario: "O capítulo pascal de João: a corrida ao túmulo, Madalena no jardim, a aparição aos discípulos com o dom do Espírito e Tomé oito dias depois. Termina com uma declaração de propósito — estes sinais foram escritos para que creiais — que parecia ser o fim do evangelho antes do capítulo 21."
  },
  "Jo 20,11-18": {
    titulo: "João 20,11-18",
    tipo: "biblia",
    versos: [{c:20,v:11,t:"Maria, porém, estava em pé, diante do sepulcro, a chorar. Enquanto chorava, abaixou-se a olhar para dentro do sepulcro,"},{c:20,v:12,t:"e viu dois anjos vestidos de branco sentados onde jazera o corpo de Jesus, um à cabeceira e outro aos pés."},{c:20,v:13,t:"E perguntaram-lhe eles: Mulher, por que choras? Respondeu- lhes: Porque tiraram o meu Senhor, e não sei onde o puseram."},{c:20,v:14,t:"Ao dizer isso, voltou-se para trás, e viu a Jesus ali em pé, mas não sabia que era Jesus."},{c:20,v:15,t:"Perguntou-lhe Jesus: Mulher, por que choras? A quem procuras? Ela, julgando que fosse o jardineiro, respondeu-lhe: Senhor, se tu o levaste, dize-me onde o puseste, e eu o levarei."},{c:20,v:16,t:"Disse-lhe Jesus: Maria! Ela, virando-se, disse-lhe em hebraico: Raboni! - que quer dizer, Mestre."},{c:20,v:17,t:"Disse-lhe Jesus: Deixa de me tocar, porque ainda não subi ao Pai; mas vai a meus irmãos e dize-lhes que eu subo para meu Pai e vosso Pai, meu Deus e vosso Deus."},{c:20,v:18,t:"E foi Maria Madalena anunciar aos discípulos: Vi o Senhor! - e que ele lhe dissera estas coisas."}],
    comentario: "Madalena chora, confunde Jesus com o jardineiro e o reconhece quando ele a chama pelo nome. Recebe o encargo de anunciar aos outros, o que lhe valeu o título de apóstola dos apóstolos. Que a primeira testemunha seja uma mulher, num contexto em que seu testemunho tinha pouco valor legal, é considerado indício de antiguidade."
  },
  "Lc 24,13-35": {
    titulo: "Lucas 24,13-35",
    tipo: "biblia",
    versos: [{c:24,v:13,t:"Nesse mesmo dia, iam dois deles para uma aldeia chamada Emaús, que distava de Jerusalém sessenta estádios;"},{c:24,v:14,t:"e iam comentando entre si tudo aquilo que havia sucedido."},{c:24,v:15,t:"Enquanto assim comentavam e discutiam, o próprio Jesus se aproximou, e ia com eles;"},{c:24,v:16,t:"mas os olhos deles estavam como que fechados, de sorte que não o reconheceram."},{c:24,v:17,t:"Então ele lhes perguntou: Que palavras são essas que, caminhando, trocais entre vós? Eles então pararam tristes."},{c:24,v:18,t:"E um deles, chamado Cleopas, respondeu-lhe: És tu o único peregrino em Jerusalém que não soube das coisas que nela têm sucedido nestes dias?"},{c:24,v:19,t:"Ao que ele lhes perguntou: Quais? Disseram-lhe: As que dizem respeito a Jesus, o nazareno, que foi profeta, poderoso em obras e palavras diante de Deus e de todo o povo."},{c:24,v:20,t:"e como os principais sacerdotes e as nossas autoridades e entregaram para ser condenado à morte, e o crucificaram."},{c:24,v:21,t:"Ora, nós esperávamos que fosse ele quem havia de remir Israel; e, além de tudo isso, é já hoje o terceiro dia desde que essas coisas aconteceram."},{c:24,v:22,t:"Verdade é, também, que algumas mulheres do nosso meio nos encheram de espanto; pois foram de madrugada ao sepulcro"},{c:24,v:23,t:"e, não achando o corpo dele voltaram, declarando que tinham tido uma visão de anjos que diziam estar ele vivo."},{c:24,v:24,t:"Além disso, alguns dos que estavam conosco foram ao sepulcro, e acharam ser assim como as mulheres haviam dito; a ele, porém, não o viram."},{c:24,v:25,t:"Então ele lhes disse: Ó néscios, e tardos de coração para crerdes tudo o que os profetas disseram!"},{c:24,v:26,t:"Porventura não importa que o Cristo padecesse essas coisas e entrasse na sua glória?"},{c:24,v:27,t:"E, começando por Moisés, e por todos os profetas, explicou-lhes o que dele se achava em todas as Escrituras."},{c:24,v:28,t:"Quando se aproximaram da aldeia para onde iam, ele fez como quem ia para mais longe."},{c:24,v:29,t:"Eles, porém, o constrangeram, dizendo: Fica conosco; porque é tarde, e já declinou o dia. E entrou para ficar com eles."},{c:24,v:30,t:"Estando com eles à mesa, tomou o pão e o abençoou; e, partindo-o, lho dava."},{c:24,v:31,t:"Abriram-se-lhes então os olhos, e o reconheceram; nisto ele desapareceu de diante deles."},{c:24,v:32,t:"E disseram um para o outro: Porventura não se nos abrasava o coração, quando pelo caminho nos falava, e quando nos abria as Escrituras?"},{c:24,v:33,t:"E na mesma hora levantaram-se e voltaram para Jerusalém, e encontraram reunidos os onze e os que estavam com eles,"},{c:24,v:34,t:"os quais diziam: Realmente o Senhor ressurgiu, e apareceu a Simão."},{c:24,v:35,t:"Então os dois contaram o que acontecera no caminho, e como se lhes fizera conhecer no partir do pão."}],
    comentario: "Emaús: dois discípulos caminham conversando com um estranho e só o reconhecem quando ele parte o pão — e ele desaparece. A estrutura da cena é a da liturgia cristã: Escritura explicada no caminho, pão partido à mesa."
  },
  "Jo 20,24-29": {
    titulo: "João 20,24-29",
    tipo: "biblia",
    versos: [{c:20,v:24,t:"Ora, Tomé, um dos doze, chamado Dídimo, não estava com eles quando veio Jesus."},{c:20,v:25,t:"Diziam-lhe, pois, ou outros discípulos: Vimos o Senhor. Ele, porém, lhes respondeu: Se eu não vir o sinal dos cravos nas mãos, e não meter a mão no seu lado, de maneira nenhuma crerei."},{c:20,v:26,t:"Oito dias depois estavam os discípulos outra vez ali reunidos, e Tomé com eles. Chegou Jesus, estando as portas fechadas, pôs-se no meio deles e disse: Paz seja convosco."},{c:20,v:27,t:"Depois disse a Tomé: Chega aqui o teu dedo, e vê as minhas mãos; chega a tua mão, e mete-a no meu lado; e não mais sejas incrédulo, mas crente."},{c:20,v:28,t:"Respondeu-lhe Tomé: Senhor meu, e Deus meu!"},{c:20,v:29,t:"Disse-lhe Jesus: Porque me viste, creste? Bem-aventurados os que não viram e creram."}],
    comentario: "Tomé exige ver e tocar. Jesus oferece, mas o texto não diz que ele tocou — quem decide que sim é a pintura, sobretudo Caravaggio. A confissão meu Senhor e meu Deus é o ponto alto cristológico de João, e a bem-aventurança dos que creram sem ver fala diretamente aos leitores do fim do século I."
  },
  "Jo 21": {
    titulo: "João 21",
    tipo: "biblia",
    versos: [{c:21,v:1,t:"Depois disto manifestou-se Jesus outra vez aos discípulos junto do mar de Tiberíades; e manifestou-se deste modo:"},{c:21,v:2,t:"Estavam juntos Simão Pedro, Tomé, chamado Dídimo, Natanael, que era de Caná da Galiléia, os filhos de Zebedeu, e outros dois dos seus discípulos."},{c:21,v:3,t:"Disse-lhes Simão Pedro: Vou pescar. Responderam-lhe: Nós também vamos contigo. Saíram e entraram no barco; e naquela noite nada apanharam."},{c:21,v:4,t:"Mas ao romper da manhã, Jesus se apresentou na praia; todavia os discípulos não sabiam que era ele."},{c:21,v:5,t:"Disse-lhes, pois, Jesus: Filhos, não tendes nada que comer? Responderam-lhe: Não."},{c:21,v:6,t:"Disse-lhes ele: Lançai a rede à direita do barco, e achareis. Lançaram-na, pois, e já não a podiam puxar por causa da grande quantidade de peixes."},{c:21,v:7,t:"Então aquele discípulo a quem Jesus amava disse a Pedro: Senhor. Quando, pois, Simão Pedro ouviu que era o Senhor, cingiu-se com a túnica, porque estava despido, e lançou-se ao mar;"},{c:21,v:8,t:"mas os outros discípulos vieram no barquinho, puxando a rede com os peixes, porque não estavam distantes da terra senão cerca de duzentos côvados."},{c:21,v:9,t:"Ora, ao saltarem em terra, viram ali brasas, e um peixe posto em cima delas, e pão."},{c:21,v:10,t:"Disse-lhes Jesus: Trazei alguns dos peixes que agora apanhastes."},{c:21,v:11,t:"Entrou Simão Pedro no barco e puxou a rede para terra, cheia de cento e cinquenta e três grandes peixes; e, apesar de serem tantos, não se rompeu a rede."},{c:21,v:12,t:"Disse-lhes Jesus: Vinde, comei. Nenhum dos discípulos ousava perguntar-lhe: Quem és tu? sabendo que era o Senhor."},{c:21,v:13,t:"Chegou Jesus, tomou o pão e deu-lho, e semelhantemente o peixe."},{c:21,v:14,t:"Foi esta a terceira vez que Jesus se manifestou aos seus discípulos, depois de ter ressurgido dentre os mortos."},{c:21,v:15,t:"Depois de terem comido, perguntou Jesus a Simão Pedro: Simão Pedro: Simão, filho de João, amas-me mais do que estes? Respondeu- lhe: Sim, Senhor; tu sabes que te amo. Disse-lhe: Apascenta os meus cordeirinhos."},{c:21,v:16,t:"Tornou a perguntar-lhe: Simão, filho de João, amas-me? Respondeu-lhe: Sim, Senhor; tu sabes que te amo. Disse-lhe: Pastoreia as minhas ovelhas."},{c:21,v:17,t:"Perguntou-lhe terceira vez: Simão, filho de João, amas-me? Entristeceu-se Pedro por lhe ter perguntado pela terceira vez: Amas- me? E respondeu-lhe: Senhor, tu sabes todas as coisas; tu sabes que te amo. Disse-lhe Jesus: Apascenta as minhas ovelhas."},{c:21,v:18,t:"Em verdade, em verdade te digo que, quando eras mais moço, te cingias a ti mesmo, e andavas por onde querias; mas, quando fores velho, estenderás as mãos e outro te cingirá, e te levará para onde tu não queres."},{c:21,v:19,t:"Ora, isto ele disse, significando com que morte havia Pedro de glorificar a Deus. E, havendo dito isto, ordenou-lhe: Segue-me."},{c:21,v:20,t:"E Pedro, virando-se, viu que o seguia aquele discípulo a quem Jesus amava, o mesmo que na ceia se recostara sobre o peito de Jesus e perguntara: Senhor, quem é o que te trai?"},{c:21,v:21,t:"Ora, vendo Pedro a este, perguntou a Jesus: Senhor, e deste que será?"},{c:21,v:22,t:"Respondeu-lhe Jesus: Se eu quiser que ele fique até que eu venha, que tens tu com isso? Segue-me tu."},{c:21,v:23,t:"Divulgou-se, pois, entre os irmãos este dito, que aquele discípulo não havia de morrer. Jesus, porém, não disse que não morreria, mas: se eu quiser que ele fique até que eu venha, que tens tu com isso?"},{c:21,v:24,t:"Este é o discípulo que dá testemunho destas coisas e as escreveu; e sabemos que o seu testemunho é verdadeiro."},{c:21,v:25,t:"E ainda muitas outras coisas há que Jesus fez; as quais, se fossem escritas uma por uma, creio que nem ainda no mundo inteiro caberiam os livros que se escrevessem."}],
    comentario: "O capítulo é apêndice: o evangelho já havia terminado no anterior. Traz a pesca abundante, o café da manhã na praia e a reabilitação de Pedro em três perguntas sobre amor, uma para cada negação. O apascenta as minhas ovelhas é lido pela tradição católica como confirmação do encargo pastoral."
  },
  "Lc 24,50-53": {
    titulo: "Lucas 24,50-53",
    tipo: "biblia",
    versos: [{c:24,v:50,t:"Então os levou fora, até Betânia; e levantando as mãos, os abençoou."},{c:24,v:51,t:"E aconteceu que, enquanto os abençoava, apartou-se deles; e foi elevado ao céu."},{c:24,v:52,t:"E, depois de o adorarem, voltaram com grande júbilo para Jerusalém;"},{c:24,v:53,t:"e estavam continuamente no templo, bendizendo a Deus."}],
    comentario: "A ascensão no fim do evangelho de Lucas acontece no mesmo dia da ressurreição; em Atos, do mesmo autor, quarenta dias depois. A diferença mostra que o intervalo é recurso narrativo, não cronologia — e que o próprio autor não via contradição em contar de dois modos."
  },
  "Gl 1,11-17": {
    titulo: "Gálatas 1,11-17",
    tipo: "biblia",
    versos: [{c:1,v:11,t:"Mas faço-vos saber, irmãos, que o evangelho que por mim foi anunciado não é segundo os homens;"},{c:1,v:12,t:"porque não o recebi de homem algum, nem me foi ensinado; mas o recebi por revelação de Jesus Cristo."},{c:1,v:13,t:"Pois já ouvistes qual foi outrora o meu procedimento no judaísmo, como sobremaneira perseguia a igreja de Deus e a assolava,"},{c:1,v:14,t:"e na minha nação excedia em judaísmo a muitos da minha idade, sendo extremamente zeloso das tradições de meus pais."},{c:1,v:15,t:"Mas, quando aprouve a Deus, que desde o ventre de minha mãe me separou, e me chamou pela sua graça,"},{c:1,v:16,t:"revelar seu Filho em mim, para que eu o pregasse entre os gentios, não consultei carne e sangue,"},{c:1,v:17,t:"nem subi a Jerusalém para estar com os que já antes de mim eram apóstolos, mas parti para a Arábia, e voltei outra vez a Damasco."}],
    comentario: "Paulo narra a própria conversão sem cavalo, sem queda e sem luz: diz apenas que Deus revelou nele o seu Filho. Insiste que não consultou ninguém e que só três anos depois subiu a Jerusalém — argumento de independência apostólica. É o relato mais antigo, feito pelo próprio protagonista."
  },
  "Gl 2,1-10": {
    titulo: "Gálatas 2,1-10",
    tipo: "biblia",
    versos: [{c:2,v:1,t:"Depois, passados catorze anos, subi outra vez a Jerusalém com Barnabé, levando também comigo a Tito."},{c:2,v:2,t:"E subi devido a uma revelação, e lhes expus o evangelho que prego entre os gentios, mas em particular aos que eram de destaque, para que de algum modo não estivesse correndo ou não tivesse corrido em vão."},{c:2,v:3,t:"Mas nem mesmo Tito, que estava comigo, embora sendo grego, foi constrangido a circuncidar-se;"},{c:2,v:4,t:"e isto por causa dos falsos irmãos intrusos, os quais furtivamente entraram a espiar a nossa liberdade, que temos em Cristo Jesus, para nos escravizar;"},{c:2,v:5,t:"aos quais nem ainda por uma hora cedemos em sujeição, para que a verdade do evangelho permanecesse entre vós."},{c:2,v:6,t:"Ora, daqueles que pareciam ser alguma coisa (quais outrora tenham sido, nada me importa; Deus não aceita a aparência do homem), esses, digo, que pareciam ser alguma coisa, nada me acrescentaram;"},{c:2,v:7,t:"antes, pelo contrário, quando viram que o evangelho da incircuncisão me fora confiado, como a Pedro o da circuncisão"},{c:2,v:8,t:"(porque aquele que operou a favor de Pedro para o apostolado da circuncisão, operou também a meu favor para com os gentios),"},{c:2,v:9,t:"e quando conheceram a graça que me fora dada, Tiago, Cefas e João, que pareciam ser as colunas, deram a mim e a Barnabé as destras de comunhão, para que nós fôssemos aos gentios, e eles à circuncisão;"},{c:2,v:10,t:"recomendando-nos somente que nos lembrássemos dos pobres; o que também procurei fazer com diligência."}],
    comentario: "A versão de Paulo do encontro de Jerusalém, escrita por um participante: acordo sobre a missão aos incircuncisos, aperto de mão com Tiago, Cefas e João, e o pedido de lembrar-se dos pobres. Difere em tom e detalhes da narrativa de Atos 15 — e é a mais antiga das duas."
  },
  "Mc 13": {
    titulo: "Marcos 13",
    tipo: "biblia",
    versos: [{c:13,v:1,t:"Quando saía do templo, disse-lhe um dos seus discípulos: Mestre, olha que pedras e que edifícios!"},{c:13,v:2,t:"Ao que Jesus lhe disse: Vês estes grandes edifícios? Não se deixará aqui pedra sobre pedra que não seja derribada."},{c:13,v:3,t:"Depois estando ele sentado no Monte das Oliveiras, defronte do templo, Pedro, Tiago, João e André perguntaram-lhe em particular:"},{c:13,v:4,t:"Dize-nos, quando sucederão essas coisas, e que sinal haverá quando todas elas estiverem para se cumprir?"},{c:13,v:5,t:"Então Jesus começou a dizer-lhes: Acautelai-vos; ninguém vos engane;"},{c:13,v:6,t:"muitos virão em meu nome, dizendo: Sou eu; e a muitos enganarão."},{c:13,v:7,t:"Quando, porém, ouvirdes falar em guerras e rumores de guerras, não vos perturbeis; forçoso é que assim aconteça: mas ainda não é o fim."},{c:13,v:8,t:"Pois se levantará nação contra nação, e reino contra reino; e haverá terremotos em diversos lugares, e haverá fomes. Isso será o princípio das dores."},{c:13,v:9,t:"Mas olhai por vós mesmos; pois por minha causa vos hão de entregar aos sinédrios e às sinagogas, e sereis açoitados; também sereis levados perante governadores e reis, para lhes servir de testemunho."},{c:13,v:10,t:"Mas importa que primeiro o evangelho seja pregado entre todas as nações."},{c:13,v:11,t:"Quando, pois, vos conduzirem para vos entregar, não vos preocupeis com o que haveis de dizer; mas, o que vos for dado naquela hora, isso falai; porque não sois vós que falais, mas sim o Espírito Santo."},{c:13,v:12,t:"Um irmão entregará à morte a seu irmão, e um pai a seu filho; e filhos se levantarão contra os pais e os matarão."},{c:13,v:13,t:"E sereis odiados de todos por causa do meu nome; mas aquele que perseverar até o fim, esse será salvo."},{c:13,v:14,t:"Ora, quando vós virdes a abominação da desolação estar onde não deve estar (quem lê, entenda), então os que estiverem na Judéia fujam para os montes;"},{c:13,v:15,t:"quem estiver no eirado não desça, nem entre para tirar alguma coisa da sua casa;"},{c:13,v:16,t:"e quem estiver no campo não volte atrás para buscar a sua capa."},{c:13,v:17,t:"Mas ai das que estiverem grávidas, e das que amamentarem naqueles dias!"},{c:13,v:18,t:"Orai, pois, para que isto não suceda no inverno;"},{c:13,v:19,t:"porque naqueles dias haverá uma tribulação tal, qual nunca houve desde o princípio da criação, que Deus criou, até agora, nem jamais haverá."},{c:13,v:20,t:"Se o Senhor não abreviasse aqueles dias, ninguém se salvaria mas ele, por causa dos eleitos que escolheu, abreviou aqueles dias."},{c:13,v:21,t:"Então, se alguém vos disser: Eis aqui o Cristo! ou: Ei-lo ali! não acrediteis."},{c:13,v:22,t:"Porque hão de surgir falsos cristos e falsos profetas, e farão sinais e prodígios para enganar, se possível, até os escolhidos."},{c:13,v:23,t:"Ficai vós, pois, de sobreaviso; eis que de antemão vos tenho dito tudo."},{c:13,v:24,t:"Mas naqueles dias, depois daquela tribulação, o sol escurecerá, e a lua não dará a sua luz;"},{c:13,v:25,t:"as estrelas cairão do céu, e os poderes que estão nos céus, serão abalados."},{c:13,v:26,t:"Então verão vir o Filho do homem nas nuvens, com grande poder e glória."},{c:13,v:27,t:"E logo enviará os seus anjos, e ajuntará os seus eleitos, desde os quatro ventos, desde a extremidade da terra até a extremidade do céu."},{c:13,v:28,t:"Da figueira, pois, aprendei a parábola: Quando já o seu ramo se torna tenro e brota folhas, sabeis que está próximo o verão."},{c:13,v:29,t:"Assim também vós, quando virdes sucederem essas coisas, sabei que ele está próximo, mesmo às portas."},{c:13,v:30,t:"Em verdade vos digo que não passará esta geração, até que todas essas coisas aconteçam."},{c:13,v:31,t:"Passará o céu e a terra, mas as minhas palavras não passarão."},{c:13,v:32,t:"Quanto, porém, ao dia e à hora, ninguém sabe, nem os anjos no céu nem o Filho, senão o Pai."},{c:13,v:33,t:"Olhai! vigiai! porque não sabeis quando chegará o tempo."},{c:13,v:34,t:"É como se um homem, devendo viajar, ao deixar a sua casa, desse autoridade aos seus servos, a cada um o seu trabalho, e ordenasse também ao porteiro que vigiasse."},{c:13,v:35,t:"Vigiai, pois; porque não sabeis quando virá o senhor da casa; se à tarde, se à meia-noite, se ao cantar do galo, se pela manhã;"},{c:13,v:36,t:"para que, vindo de improviso, não vos ache dormindo."},{c:13,v:37,t:"O que vos digo a vós, a todos o digo: Vigiai."}],
    comentario: "O discurso apocalíptico, com a previsão de que não ficará pedra sobre pedra no Templo. A precisão da descrição do cerco é o principal argumento para datar Marcos por volta de 70. O capítulo termina com uma advertência dupla: vigiar sempre e não confiar em quem calcula datas."
  },
  "Mc 1,1": {
    titulo: "Marcos 1,1",
    tipo: "biblia",
    versos: [{c:1,v:1,t:"Princípio do evangelho de Jesus Cristo, Filho de Deus."}],
    comentario: "A primeira linha do evangelho mais antigo funciona como título: princípio do evangelho de Jesus Cristo, Filho de Deus. A expressão Filho de Deus falta em alguns manuscritos importantes, e a palavra evangelho — boa notícia — era vocabulário imperial antes de ser cristão."
  },
  "Mc 16,8": {
    titulo: "Marcos 16,8",
    tipo: "biblia",
    versos: [{c:16,v:8,t:"E, saindo elas, fugiram do sepulcro, porque estavam possuídas de medo e assombro; e não disseram nada a ninguém, porque temiam."}],
    comentario: "O verso final nos manuscritos mais antigos: as mulheres fugiram e nada disseram a ninguém, porque tinham medo. Em grego, a frase termina numa conjunção, o que soa abrupto. Se é final proposital ou perda material, discute-se há séculos — e os dois finais alternativos foram acrescentados justamente para resolver o desconforto."
  },
  "Mt 1": {
    titulo: "Mateus 1",
    tipo: "biblia",
    versos: [{c:1,v:1,t:"Livro da genealogia de Jesus Cristo, filho de Davi, filho de Abraão."},{c:1,v:2,t:"A Abraão nasceu Isaque; a Isaque nasceu Jacó; a Jacó nasceram Judá e seus irmãos;"},{c:1,v:3,t:"a Judá nasceram, de Tamar, Farés e Zará; a Farés nasceu Esrom; a Esrom nasceu Arão;"},{c:1,v:4,t:"a Arão nasceu Aminadabe; a Aminadabe nasceu Nasom; a Nasom nasceu Salmom;"},{c:1,v:5,t:"a Salmom nasceu, de Raabe, Booz; a Booz nasceu, de Rute, Obede; a Obede nasceu Jessé;"},{c:1,v:6,t:"e a Jessé nasceu o rei Davi. A Davi nasceu Salomão da que fora mulher de Urias;"},{c:1,v:7,t:"a Salomão nasceu Roboão; a Roboão nasceu Abias; a Abias nasceu Asafe;"},{c:1,v:8,t:"a Asafe nasceu Josafá; a Josafá nasceu Jorão; a Jorão nasceu Ozias;"},{c:1,v:9,t:"a Ozias nasceu Joatão; a Joatão nasceu Acaz; a Acaz nasceu Ezequias;"},{c:1,v:10,t:"a Ezequias nasceu Manassés; a Manassés nasceu Amom; a Amom nasceu Josias;"},{c:1,v:11,t:"a Josias nasceram Jeconias e seus irmãos, no tempo da deportação para Babilônia."},{c:1,v:12,t:"Depois da deportação para Babilônia nasceu a Jeconias, Salatiel; a Salatiel nasceu Zorobabel;"},{c:1,v:13,t:"a Zorobabel nasceu Abiúde; a Abiúde nasceu Eliaquim; a Eliaquim nasceu Azor;"},{c:1,v:14,t:"a Azor nasceu Sadoque; a Sadoque nasceu Aquim; a Aquim nasceu Eliúde;"},{c:1,v:15,t:"a Eliúde nasceu Eleazar; a Eleazar nasceu Matã; a Matã nasceu Jacó;"},{c:1,v:16,t:"e a Jacó nasceu José, marido de Maria, da qual nasceu JESUS, que se chama Cristo."},{c:1,v:17,t:"De sorte que todas as gerações, desde Abraão até Davi, são catorze gerações; e desde Davi até a deportação para Babilônia, catorze gerações; e desde a deportação para Babilônia até o Cristo, catorze gerações."},{c:1,v:18,t:"Ora, o nascimento de Jesus Cristo foi assim: Estando Maria, sua mãe, desposada com José, antes de se ajuntarem, ela se achou ter concebido do Espírito Santo."},{c:1,v:19,t:"E como José, seu esposo, era justo, e não a queria infamar, intentou deixá-la secretamente."},{c:1,v:20,t:"E, projetando ele isso, eis que em sonho lhe apareceu um anjo do Senhor, dizendo: José, filho de Davi, não temas receber a Maria, tua mulher, pois o que nela se gerou é do Espírito Santo;"},{c:1,v:21,t:"ela dará à luz um filho, a quem chamarás JESUS; porque ele salvará o seu povo dos seus pecados."},{c:1,v:22,t:"Ora, tudo isso aconteceu para que se cumprisse o que fora dito da parte do Senhor pelo profeta:"},{c:1,v:23,t:"Eis que a virgem conceberá e dará à luz um filho, o qual será chamado EMANUEL, que traduzido é: Deus conosco."},{c:1,v:24,t:"E José, tendo despertado do sono, fez como o anjo do Senhor lhe ordenara, e recebeu sua mulher;"},{c:1,v:25,t:"e não a conheceu enquanto ela não deu à luz um filho; e pôs-lhe o nome de JESUS."}],
    comentario: "A genealogia de Mateus organiza a ascendência em três séries de catorze gerações, número que corresponde ao valor das letras do nome Davi em hebraico. Inclui quatro mulheres, todas com histórias irregulares ou estrangeiras — Tamar, Raabe, Rute e a mulher de Urias."
  },
  "Lc 1,1-4": {
    titulo: "Lucas 1,1-4",
    tipo: "biblia",
    versos: [{c:1,v:1,t:"Visto que muitos têm empreendido fazer uma narração coordenada dos fatos que entre nós se realizaram,"},{c:1,v:2,t:"segundo no-los transmitiram os que desde o princípio foram testemunhas oculares e ministros da palavra,"},{c:1,v:3,t:"também a mim, depois de haver investido tudo cuidadosamente desde o começo, pareceu-me bem, ó excelentíssimo Teófilo, escrever-te uma narração em ordem."},{c:1,v:4,t:"para que conheças plenamente a verdade das coisas em que foste instruído."}],
    comentario: "O prólogo de Lucas é o texto mais próximo de um método historiográfico no Novo Testamento: menciona muitos que tentaram narrar, testemunhas oculares, investigação cuidadosa e ordem. Escreve para um destinatário, Teófilo, e promete segurança quanto ao que foi ensinado."
  },
  "Jo 1,1-18": {
    titulo: "João 1,1-18",
    tipo: "biblia",
    versos: [{c:1,v:1,t:"No princípio era o Verbo, e o Verbo estava com Deus, e o Verbo era Deus."},{c:1,v:2,t:"Ele estava no princípio com Deus."},{c:1,v:3,t:"Todas as coisas foram feitas por intermédio dele, e sem ele nada do que foi feito se fez."},{c:1,v:4,t:"Nele estava a vida, e a vida era a luz dos homens;"},{c:1,v:5,t:"a luz resplandece nas trevas, e as trevas não prevaleceram contra ela."},{c:1,v:6,t:"Houve um homem enviado de Deus, cujo nome era João."},{c:1,v:7,t:"Este veio como testemunha, a fim de dar testemunho da luz, para que todos cressem por meio dele."},{c:1,v:8,t:"Ele não era a luz, mas veio para dar testemunho da luz."},{c:1,v:9,t:"Pois a verdadeira luz, que alumia a todo homem, estava chegando ao mundo."},{c:1,v:10,t:"Estava ele no mundo, e o mundo foi feito por intermédio dele, e o mundo não o conheceu."},{c:1,v:11,t:"Veio para o que era seu, e os seus não o receberam."},{c:1,v:12,t:"Mas, a todos quantos o receberam, aos que crêem no seu nome, deu-lhes o poder de se tornarem filhos de Deus;"},{c:1,v:13,t:"os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do varão, mas de Deus."},{c:1,v:14,t:"E o Verbo se fez carne, e habitou entre nós, cheio de graça e de verdade; e vimos a sua glória, como a glória do unigênito do Pai."},{c:1,v:15,t:"João deu testemunho dele, e clamou, dizendo: Este é aquele de quem eu disse: O que vem depois de mim, passou adiante de mim; porque antes de mim ele já existia."},{c:1,v:16,t:"Pois todos nós recebemos da sua plenitude, e graça sobre graça."},{c:1,v:17,t:"Porque a lei foi dada por meio de Moisés; a graça e a verdade vieram por Jesus Cristo."},{c:1,v:18,t:"Ninguém jamais viu a Deus. O Deus unigênito, que está no seio do Pai, esse o deu a conhecer."}],
    comentario: "O prólogo de João desloca o começo da história para antes da criação: no princípio era o Verbo. A frase e o Verbo se fez carne é a base da teologia da Encarnação, e o vocabulário (logos) dialoga tanto com a sabedoria judaica quanto com a filosofia grega."
  },
  "Jo 20,30-31": {
    titulo: "João 20,30-31",
    tipo: "biblia",
    versos: [{c:20,v:30,t:"Jesus, na verdade, operou na presença de seus discípulos ainda muitos outros sinais que não estão escritos neste livro;"},{c:20,v:31,t:"estes, porém, estão escritos para que creiais que Jesus é o Cristo, o Filho de Deus, e para que, crendo, tenhais vida em seu nome."}],
    comentario: "A declaração de propósito do evangelho: muitos outros sinais fez Jesus, que não estão escritos neste livro; estes foram escritos para que creiais. O autor admite seleção deliberada — é literatura de persuasão, e diz isso com todas as letras."
  },
  "At 5,37": {
    titulo: "Atos dos Apóstolos 5,37",
    tipo: "biblia",
    versos: [{c:5,v:37,t:"Depois dele levantou-se Judas, o galileu, nos dias do recenseamento, e levou muitos após si; mas também este pereceu, e todos quantos lhe obedeciam foram dispersos."}],
    comentario: "O discurso de Gamaliel cita Judas, o Galileu, que se levantou nos dias do recenseamento e arrastou o povo. É a confirmação, dentro do Novo Testamento, de que o censo de Quirino provocou revolta — o mesmo censo que Lucas usa para levar a família a Belém."
  },
  "Os 11,1": {
    titulo: "Oseias 11,1",
    tipo: "biblia",
    versos: [{c:11,v:1,t:"Quando Israel era menino, eu o amei, e do Egito chamei a meu filho."}],
    comentario: "Do Egito chamei o meu filho: no original, o oráculo fala do povo de Israel saindo da escravidão. Mateus aplica a frase a Jesus, revelando sua chave de leitura — a vida do Messias refaz a trajetória do povo."
  },
  "2Pd 1,16-18": {
    titulo: "2 Pedro 1,16-18",
    tipo: "biblia",
    versos: [{c:1,v:16,t:"Porque não seguimos fábulas engenhosas quando vos fizemos conhecer o poder e a vinda de nosso Senhor Jesus Cristo, pois nós fôramos testemunhas oculares da sua majestade."},{c:1,v:17,t:"Porquanto ele recebeu de Deus Pai honra e glória, quando pela Glória Magnífica lhe foi dirigida a seguinte voz: Este é o meu Filho amado, em quem me comprazo;"},{c:1,v:18,t:"e essa voz, dirigida do céu, ouvimo-la nós mesmos, estando com ele no monte santo."}],
    comentario: "A carta reivindica a Transfiguração como testemunho ocular e nega expressamente que se trate de fábula engenhosa. A maioria dos estudiosos considera 2Pedro pseudoepígrafa tardia, o que faz do texto um documento sobre como a segunda geração cristã defendia sua memória."
  },
  "Zc 9,9": {
    titulo: "Zacarias 9,9",
    tipo: "biblia",
    versos: [{c:9,v:9,t:"Alegra-te muito, ó filha de Sião; exulta, ó filha de Jerusalém; eis que vem a ti o teu rei; ele é justo e traz a salvação; ele é humilde e vem montado sobre um jumento, sobre um jumentinho, filho de jumenta."}],
    comentario: "Alegra-te, filha de Sião: teu rei vem a ti, humilde, montado num jumento. É a profecia que a entrada em Jerusalém encena deliberadamente — um rei que chega em animal de paz, não em cavalo de guerra."
  },
  "1Cor 11,23-26": {
    titulo: "1 Coríntios 11,23-26",
    tipo: "biblia",
    versos: [{c:11,v:23,t:"Porque eu recebi do Senhor o que também vos entreguei: que o Senhor Jesus, na noite em que foi traído, tomou pão;"},{c:11,v:24,t:"e, havendo dado graças, o partiu e disse: Isto é o meu corpo que é por vós; fazei isto em memória de mim."},{c:11,v:25,t:"Semelhantemente também, depois de cear, tomou o cálice, dizendo: Este cálice é o novo pacto no meu sangue; fazei isto, todas as vezes que o beberdes, em memória de mim."},{c:11,v:26,t:"Porque todas as vezes que comerdes deste pão e beberdes do cálice estareis anunciando a morte do Senhor, até que ele venha."}],
    comentario: "O registro mais antigo da Última Ceia, escrito nos anos 50, antes de qualquer evangelho. Paulo diz ter recebido e transmitido a fórmula, o que indica tradição já fixada. É o texto que cada tradição cristã lê de um jeito ao definir o que acontece na eucaristia."
  },
  "1Pd 3,18-20": {
    titulo: "1 Pedro 3,18-20",
    tipo: "biblia",
    versos: [{c:3,v:18,t:"Porque também Cristo morreu uma só vez pelos pecados, o justo pelos injustos, para levar-nos a Deus; sendo, na verdade, morto na carne, mas vivificado no espírito;"},{c:3,v:19,t:"no qual também foi, e pregou aos espíritos em prisão;"},{c:3,v:20,t:"os quais noutro tempo foram rebeldes, quando a longanimidade de Deus esperava, nos dias de Noé, enquanto se preparava a arca; na qual poucas, isto é, oito almas se salvaram através da água,"}],
    comentario: "A base bíblica da descida ao Hades: Cristo foi pregar aos espíritos em prisão. O versículo é obscuro e gerou leituras divergentes — no Oriente virou a imagem central da Páscoa, e no Ocidente entrou no Credo como desceu à mansão dos mortos."
  },
  "1Cor 15,3-8": {
    titulo: "1 Coríntios 15,3-8",
    tipo: "biblia",
    versos: [{c:15,v:3,t:"Porque primeiramente vos entreguei o que também recebi: que Cristo morreu por nossos pecados, segundo as Escrituras;"},{c:15,v:4,t:"que foi sepultado; que foi ressuscitado ao terceiro dia, segundo as Escrituras;"},{c:15,v:5,t:"que apareceu a Cefas, e depois aos doze;"},{c:15,v:6,t:"depois apareceu a mais de quinhentos irmãos duma vez, dos quais vive ainda a maior parte, mas alguns já dormiram;"},{c:15,v:7,t:"depois apareceu a Tiago, então a todos os apóstolos;"},{c:15,v:8,t:"e por derradeiro de todos apareceu também a mim, como a um abortivo."}],
    comentario: "O texto mais importante para a história da fé pascal: um credo que Paulo diz ter recebido, com a lista de aparições — Cefas, os Doze, mais de quinhentos irmãos, Tiago, todos os apóstolos e, por último, ele mesmo. A fórmula foi provavelmente composta nos anos 30, poucos anos após a crucificação."
  },
  "At 1,6-11": {
    titulo: "Atos dos Apóstolos 1,6-11",
    tipo: "biblia",
    versos: [{c:1,v:6,t:"Aqueles, pois, que se haviam reunido perguntavam-lhe, dizendo: Senhor, é nesse tempo que restauras o reino a Israel?"},{c:1,v:7,t:"Respondeu-lhes: A vós não vos compete saber os tempos ou as épocas, que o Pai reservou à sua própria autoridade."},{c:1,v:8,t:"Mas recebereis poder, ao descer sobre vós o Espírito Santo, e ser-me-eis testemunhas, tanto em Jerusalém, como em toda a Judéia e Samária, e até os confins da terra."},{c:1,v:9,t:"Tendo ele dito estas coisas, foi levado para cima, enquanto eles olhavam, e uma nuvem o recebeu, ocultando-o a seus olhos."},{c:1,v:10,t:"Estando eles com os olhos fitos no céu, enquanto ele subia, eis que junto deles apareceram dois varões vestidos de branco,"},{c:1,v:11,t:"os quais lhes disseram: Varões galileus, por que ficais aí olhando para o céu? Esse Jesus, que dentre vós foi elevado para o céu, há de vir assim como para o céu o vistes ir."}],
    comentario: "A ascensão em Atos, com a pergunta dos discípulos (vais restaurar o reino a Israel?) que mostra que a expectativa política continuava viva. A resposta desloca o foco para o testemunho até os confins da terra — programa do livro inteiro."
  },
  "At 2": {
    titulo: "Atos dos Apóstolos 2",
    tipo: "biblia",
    versos: [{c:2,v:1,t:"Ao cumprir-se o dia de Pentecostes, estavam todos reunidos no mesmo lugar."},{c:2,v:2,t:"De repente veio do céu um ruído, como que de um vento impetuoso, e encheu toda a casa onde estavam sentados."},{c:2,v:3,t:"E lhes apareceram umas línguas como que de fogo, que se distribuíam, e sobre cada um deles pousou uma."},{c:2,v:4,t:"E todos ficaram cheios do Espírito Santo, e começaram a falar noutras línguas, conforme o Espírito lhes concedia que falassem."},{c:2,v:5,t:"Habitavam então em Jerusalém judeus, homens piedosos, de todas as nações que há debaixo do céu."},{c:2,v:6,t:"Ouvindo-se, pois, aquele ruído, ajuntou-se a multidão; e estava confusa, porque cada um os ouvia falar na sua própria língua."},{c:2,v:7,t:"E todos pasmavam e se admiravam, dizendo uns aos outros: Pois quê! não são galileus todos esses que estão falando?"},{c:2,v:8,t:"Como é, pois, que os ouvimos falar cada um na própria língua em que nascemos?"},{c:2,v:9,t:"Nós, partos, medos, e elamitas; e os que habitamos a Mesopotâmia, a Judéia e a Capadócia, o Ponto e a Ásia,"},{c:2,v:10,t:"a Frígia e a Panfília, o Egito e as partes da Líbia próximas a Cirene, e forasteiros romanos, tanto judeus como prosélitos,"},{c:2,v:11,t:"cretenses e árabes - ouvímo-los em nossas línguas, falar das grandezas de Deus."},{c:2,v:12,t:"E todos pasmavam e estavam perplexos, dizendo uns aos outros: Que quer dizer isto?"},{c:2,v:13,t:"E outros, zombando, diziam: Estão cheios de mosto."},{c:2,v:14,t:"Então Pedro, pondo-se em pé com os onze, levantou a voz e disse-lhes: Varões judeus e todos os que habitais em Jerusalém, seja- vos isto notório, e escutai as minhas palavras."},{c:2,v:15,t:"Pois estes homens não estão embriagados, como vós pensais, visto que é apenas a terceira hora do dia."},{c:2,v:16,t:"Mas isto é o que foi dito pelo profeta Joel:"},{c:2,v:17,t:"E acontecerá nos últimos dias, diz o Senhor, que derramarei do meu Espírito sobre toda a carne; e os vossos filhos e as vossas filhas profetizarão, os vossos mancebos terão visões, os vossos anciãos terão sonhos;"},{c:2,v:18,t:"e sobre os meus servos e sobre as minhas servas derramarei do meu Espírito naqueles dias, e eles profetizarão."},{c:2,v:19,t:"E mostrarei prodígios em cima no céu; e sinais embaixo na terra, sangue, fogo e vapor de fumaça."},{c:2,v:20,t:"O sol se converterá em trevas, e a lua em sangue, antes que venha o grande e glorioso dia do Senhor."},{c:2,v:21,t:"e acontecerá que todo aquele que invocar o nome do Senhor será salvo."},{c:2,v:22,t:"Varões israelitas, escutai estas palavras: A Jesus, o nazareno, varão aprovado por Deus entre vós com milagres, prodígios e sinais, que Deus por ele fez no meio de vós, como vós mesmos bem sabeis;"},{c:2,v:23,t:"a este, que foi entregue pelo determinado conselho e presciência de Deus, vós matastes, crucificando-o pelas mãos de iníquos;"},{c:2,v:24,t:"ao qual Deus ressuscitou, rompendo os grilhões da morte, pois não era possível que fosse retido por ela."},{c:2,v:25,t:"Porque dele fala Davi: Sempre via diante de mim o Senhor, porque está à minha direita, para que eu não seja abalado;"},{c:2,v:26,t:"por isso se alegrou o meu coração, e a minha língua exultou; e além disso a minha carne há de repousar em esperança;"},{c:2,v:27,t:"pois não deixarás a minha alma no hades, nem permitirás que o teu Santo veja a corrupção;"},{c:2,v:28,t:"fizeste-me conhecer os caminhos da vida; encher-me-ás de alegria na tua presença."},{c:2,v:29,t:"Irmãos, seja-me permitido dizer-vos livremente acerca do patriarca Davi, que ele morreu e foi sepultado, e entre nós está até hoje a sua sepultura."},{c:2,v:30,t:"Sendo, pois, ele profeta, e sabendo que Deus lhe havia prometido com juramento que faria sentar sobre o seu trono um dos seus descendentes -"},{c:2,v:31,t:"prevendo isto, Davi falou da ressurreição de Cristo, que a sua alma não foi deixada no hades, nem a sua carne viu a corrupção."},{c:2,v:32,t:"Ora, a este Jesus, Deus ressuscitou, do que todos nós somos testemunhas."},{c:2,v:33,t:"De sorte que, exaltado pela dextra de Deus, e tendo recebido do Pai a promessa do Espírito Santo, derramou isto que vós agora vedes e ouvis."},{c:2,v:34,t:"Porque Davi não subiu aos céus, mas ele próprio declara: Disse o Senhor ao meu Senhor: Assenta-te à minha direita,"},{c:2,v:35,t:"até que eu ponha os teus inimigos por escabelo de teus pés."},{c:2,v:36,t:"Saiba pois com certeza toda a casa de Israel que a esse mesmo Jesus, a quem vós crucificastes, Deus o fez Senhor e Cristo."},{c:2,v:37,t:"E, ouvindo eles isto, compungiram-se em seu coração, e perguntaram a Pedro e aos demais apóstolos: Que faremos, irmãos?"},{c:2,v:38,t:"Pedro então lhes respondeu: Arrependei-vos, e cada um de vós seja batizado em nome de Jesus Cristo, para remissão de vossos pecados; e recebereis o dom do Espírito Santo."},{c:2,v:39,t:"Porque a promessa vos pertence a vós, a vossos filhos, e a todos os que estão longe: a quantos o Senhor nosso Deus chamar."},{c:2,v:40,t:"E com muitas outras palavras dava testemunho, e os exortava, dizendo: salvai-vos desta geração perversa."},{c:2,v:41,t:"De sorte que foram batizados os que receberam a sua palavra; e naquele dia agregaram-se quase três mil almas;"},{c:2,v:42,t:"e perseveravam na doutrina dos apóstolos e na comunhão, no partir do pão e nas orações."},{c:2,v:43,t:"Em cada alma havia temor, e muitos prodígios e sinais eram feitos pelos apóstolos."},{c:2,v:44,t:"Todos os que criam estavam unidos e tinham tudo em comum."},{c:2,v:45,t:"E vendiam suas propriedades e bens e os repartiam por todos, segundo a necessidade de cada um."},{c:2,v:46,t:"E, perseverando unânimes todos os dias no templo, e partindo o pão em casa, comiam com alegria e singeleza de coração,"},{c:2,v:47,t:"louvando a Deus, e caindo na graça de todo o povo. E cada dia acrescentava-lhes o Senhor os que iam sendo salvos."}],
    comentario: "Pentecostes: vento, fogo, línguas e a lista de povos presentes. Lucas concentra num dia um processo mais longo de expansão. O discurso de Pedro que se segue é o modelo dos sermões de Atos, e a festa judaica de Shavuot, que celebra o dom da Torá, dá o pano de fundo."
  },
  "At 6–7": {
    titulo: "Atos dos Apóstolos 6–7",
    tipo: "biblia",
    nota: "trecho de Atos 6–7",
    versos: [{c:7,v:54,t:"Ouvindo eles isto, enfureciam-se em seus corações, e rangiam os dentes contra Estêvão."},{c:7,v:55,t:"Mas ele, cheio do Espírito Santo, fitando os olhos no céu, viu a glória de Deus, e Jesus em pé à direita de Deus,"},{c:7,v:56,t:"e disse: Eis que vejo os céus abertos, e o Filho do homem em pé à direita de Deus."},{c:7,v:57,t:"Então eles gritaram com grande voz, taparam os ouvidos, e arremeteram unânimes contra ele"},{c:7,v:58,t:"e, lançando-o fora da cidade o apedrejavam. E as testemunhas depuseram as suas vestes aos pés de um mancebo chamado Saulo."},{c:7,v:59,t:"Apedrejavam, pois, a Estêvão que orando, dizia: Senhor Jesus, recebe o meu espírito."},{c:7,v:60,t:"E pondo-se de joelhos, clamou com grande voz: Senhor, não lhes imputes este pecado. Tendo dito isto, adormeceu. E Saulo consentia na sua morte."}],
    comentario: "O trecho escolhido é o apedrejamento de Estêvão, com a menção a um jovem chamado Saulo guardando as capas dos executores. O conflito ainda é interno ao mundo judaico, sem envolvimento romano — e a cena prepara a entrada em cena de Paulo."
  },
  "At 9,1-19": {
    titulo: "Atos dos Apóstolos 9,1-19",
    tipo: "biblia",
    versos: [{c:9,v:1,t:"Saulo, porém, respirando ainda ameaças e mortes contra os discípulos do Senhor, dirigiu-se ao sumo sacerdote,"},{c:9,v:2,t:"e pediu-lhe cartas para Damasco, para as sinagogas, a fim de que, caso encontrasse alguns do Caminho, quer homens quer mulheres, os conduzisse presos a Jerusalém."},{c:9,v:3,t:"Mas, seguindo ele viagem e aproximando-se de Damasco, subitamente o cercou um resplendor de luz do céu;"},{c:9,v:4,t:"e, caindo por terra, ouviu uma voz que lhe dizia: Saulo, Saulo, por que me persegues?"},{c:9,v:5,t:"Ele perguntou: Quem és tu, Senhor? Respondeu o Senhor: Eu sou Jesus, a quem tu persegues;"},{c:9,v:6,t:"mas levanta-te e entra na cidade, e lá te será dito o que te cumpre fazer."},{c:9,v:7,t:"Os homens que viajavam com ele quedaram-se emudecidos, ouvindo, na verdade, a voz, mas não vendo ninguém."},{c:9,v:8,t:"Saulo levantou-se da terra e, abrindo os olhos, não via coisa alguma; e, guiando-o pela mão, conduziram-no a Damasco."},{c:9,v:9,t:"E esteve três dias sem ver, e não comeu nem bebeu."},{c:9,v:10,t:"Ora, havia em Damasco certo discípulo chamado Ananias; e disse-lhe o Senhor em visão: Ananias! Respondeu ele: Eis-me aqui, Senhor."},{c:9,v:11,t:"Ordenou-lhe o Senhor: Levanta-te, vai à rua chamada Direita e procura em casa de Judas um homem de Tarso chamado Saulo; pois eis que ele está orando;"},{c:9,v:12,t:"e viu um homem chamado Ananias entrar e impor-lhe as mãos, para que recuperasse a vista."},{c:9,v:13,t:"Respondeu Ananias: Senhor, a muitos ouvi acerca desse homem, quantos males tem feito aos teus santos em Jerusalém;"},{c:9,v:14,t:"e aqui tem poder dos principais sacerdotes para prender a todos os que invocam o teu nome."},{c:9,v:15,t:"Disse-lhe, porém, o Senhor: Vai, porque este é para mim um vaso escolhido, para levar o meu nome perante os gentios, e os reis, e os filhos de Israel;"},{c:9,v:16,t:"pois eu lhe mostrarei quanto lhe cumpre padecer pelo meu nome."},{c:9,v:17,t:"Partiu Ananias e entrou na casa e, impondo-lhe as mãos, disse: Irmão Saulo, o Senhor Jesus, que te apareceu no caminho por onde vinhas, enviou-me para que tornes a ver e sejas cheio do Espírito Santo."},{c:9,v:18,t:"Logo lhe caíram dos olhos como que umas escamas, e recuperou a vista: então, levantando-se, foi batizado."},{c:9,v:19,t:"E, tendo tomado alimento, ficou fortalecido. Depois demorou- se alguns dias com os disc!pulos que estavam em Damasco;"}],
    comentario: "A conversão de Paulo na versão de Atos: luz, queda, voz e cegueira temporária. Lucas conta o episódio três vezes no mesmo livro, com variações de detalhe. O próprio Paulo, em Gálatas, descreve tudo em uma frase, sem nada disso."
  },
  "1Cor 15,8": {
    titulo: "1 Coríntios 15,8",
    tipo: "biblia",
    versos: [{c:15,v:8,t:"e por derradeiro de todos apareceu também a mim, como a um abortivo."}],
    comentario: "Por último, como a um abortivo, apareceu também a mim. A palavra que Paulo usa é violenta e o coloca fora de ordem na lista das aparições — reivindicando o mesmo tipo de encontro que os outros tiveram, e admitindo que chegou atrasado."
  },
  "At 15": {
    titulo: "Atos dos Apóstolos 15",
    tipo: "biblia",
    versos: [{c:15,v:1,t:"Então alguns que tinham descido da Judéia ensinavam aos irmãos: Se não vos circuncidardes, segundo o rito de Moisés, não podeis ser salvos."},{c:15,v:2,t:"Tendo Paulo e Barnabé contenda e não pequena discussão com eles, os irmãos resolveram que Paulo e Barnabé e mais alguns dentre eles subissem a Jerusalém, aos apóstolos e aos anciãos, por causa desta questão."},{c:15,v:3,t:"Eles, pois, sendo acompanhados pela igreja por um trecho do caminho, passavam pela Fenícia e por Samária, contando a conversão dos gentios; e davam grande alegria a todos os irmãos."},{c:15,v:4,t:"E, quando chegaram a Jerusalém, foram recebidos pela igreja e pelos apóstolos e anciãos, e relataram tudo quanto Deus fizera por meio deles."},{c:15,v:5,t:"Mas alguns da seita dos fariseus, que tinham crido, levantaram-se dizendo que era necessário circuncidá-los e mandar-lhes observar a lei de Moisés."},{c:15,v:6,t:"Congregaram-se pois os apóstolos e os anciãos para considerar este assunto."},{c:15,v:7,t:"E, havendo grande discussão, levantou-se Pedro e disse-lhes: Irmãos, bem sabeis que já há muito tempo Deus me elegeu dentre vós, para que os gentios ouvissem da minha boca a palavra do evangelho e cressem."},{c:15,v:8,t:"E Deus, que conhece os corações, testemunhou a favor deles, dando-lhes o Espírito Santo, assim como a nós;"},{c:15,v:9,t:"e não fez distinção alguma entre eles e nós, purificando os seus corações pela fé."},{c:15,v:10,t:"Agora, pois, por que tentais a Deus, pondo sobre a cerviz dos discípulos um jugo que nem nossos pais nem nós pudemos suportar?"},{c:15,v:11,t:"Mas cremos que somos salvos pela graça do Senhor Jesus, do mesmo modo que eles também."},{c:15,v:12,t:"Então toda a multidão se calou e escutava a Barnabé e a Paulo, que contavam quantos sinais e prodígios Deus havia feito por meio deles entre os gentios."},{c:15,v:13,t:"Depois que se calaram, Tiago, tomando a palavra, disse: Irmãos, ouvi-me:"},{c:15,v:14,t:"Simão relatou como primeiramente Deus visitou os gentios para tomar dentre eles um povo para o seu Nome."},{c:15,v:15,t:"E com isto concordam as palavras dos profetas; como está escrito:"},{c:15,v:16,t:"Depois disto voltarei, e reedificarei o tabernáculo de Davi, que está caído; reedificarei as suas ruínas, e tornarei a levantá-lo;"},{c:15,v:17,t:"para que o resto dos homens busque ao Senhor, sim, todos os gentios, sobre os quais é invocado o meu nome,"},{c:15,v:18,t:"diz o Senhor que faz estas coisas, que são conhecidas desde a antiguidade."},{c:15,v:19,t:"Por isso, julgo que não se deve perturbar aqueles, dentre os gentios, que se convertem a Deus,"},{c:15,v:20,t:"mas escrever-lhes que se abstenham das contaminações dos ídolos, da prostituição, do que é sufocado e do sangue."},{c:15,v:21,t:"Porque Moisés, desde tempos antigos, tem em cada cidade homens que o preguem, e cada sábado é lido nas sinagogas."},{c:15,v:22,t:"Então pareceu bem aos apóstolos e aos anciãos com toda a igreja escolher homens dentre eles e enviá-los a Antioquia com Paulo e Barnabé, a saber: Judas, chamado Barsabás, e Silas, homens influentes entre os irmãos."},{c:15,v:23,t:"E por intermédio deles escreveram o seguinte: Os apóstolos e os anciãos, irmãos, aos irmãos dentre os gentios em Antioquia, na Síria e na Cicília, saúde."},{c:15,v:24,t:"Portanto ouvimos que alguns dentre nós, aos quais nada mandamos, vos têm perturbado com palavras, confundindo as vossas almas,"},{c:15,v:25,t:"pareceu-nos bem, tendo chegado a um acordo, escolher alguns homens e enviá-los com os nossos amados Barnabé e Paulo,"},{c:15,v:26,t:"homens que têm exposto as suas vidas pelo nome de nosso Senhor Jesus Cristo."},{c:15,v:27,t:"Enviamos portanto Judas e Silas, os quais também por palavra vos anunciarão as mesmas coisas."},{c:15,v:28,t:"Porque pareceu bem ao Espírito Santo e a nós não vos impor maior encargo além destas coisas necessárias:"},{c:15,v:29,t:"Que vos abstenhais das coisas sacrificadas aos ídolos, e do sangue, e da carne sufocada, e da prostituição; e destas coisas fareis bem de vos guardar. Bem vos vá."},{c:15,v:30,t:"Então eles, tendo-se despedido, desceram a Antioquia e, havendo reunido a assembléia, entregaram a carta."},{c:15,v:31,t:"E, quando a leram, alegraram-se pela consolação."},{c:15,v:32,t:"Depois Judas e Silas, que também eram profetas, exortaram os irmãos com muitas palavras e os fortaleceram."},{c:15,v:33,t:"E, tendo-se demorado ali por algum tempo, foram pelos irmãos despedidos em paz, de volta aos que os haviam mandado."},{c:15,v:34,t:"[Mas pareceu bem a Silas ficar ali.]"},{c:15,v:35,t:"Mas Paulo e Barnabé demoraram-se em Antioquia, ensinando e pregando com muitos outros a palavra do Senhor."},{c:15,v:36,t:"Decorridos alguns dias, disse Paulo a Barnabé: Tornemos a visitar os irmãos por todas as cidades em que temos anunciado a palavra do Senhor, para ver como vão."},{c:15,v:37,t:"Ora, Barnabé queria que levassem também a João, chamado Marcos."},{c:15,v:38,t:"Mas a Paulo não parecia razoável que tomassem consigo aquele que desde a Panfília se tinha apartado deles e não os tinha acompanhado no trabalho."},{c:15,v:39,t:"E houve entre eles tal desavença que se separaram um do outro, e Barnabé, levando consigo a Marcos, navegou para Chipre."},{c:15,v:40,t:"Mas Paulo, tendo escolhido a Silas, partiu encomendado pelos irmãos à graça do Senhor."},{c:15,v:41,t:"E passou pela Síria e Cilícia, fortalecendo as igrejas."}],
    comentario: "O encontro de Jerusalém segundo Atos: a decisão de não impor a circuncisão aos não judeus, com discurso de Pedro, testemunho de Barnabé e Paulo e sentença final de Tiago. A comparação com Gálatas 2, escrito pelo próprio Paulo, mostra diferenças de tom e de detalhe."
  },
  "At 18,2": {
    titulo: "Atos dos Apóstolos 18,2",
    tipo: "biblia",
    versos: [{c:18,v:2,t:"E encontrando um judeu por nome Áqüila, natural do Ponto, que pouco antes viera da Itália, e Priscila, sua mulher (porque Cláudio tinha decretado que todos os judeus saíssem de Roma), foi ter com eles,"}],
    comentario: "Áquila e Priscila chegam a Corinto porque Cláudio expulsara os judeus de Roma. O dado cruza com a frase de Suetônio sobre distúrbios instigados por Chrestus, e é um dos raros pontos em que a narrativa cristã e a historiografia romana se tocam sem depender uma da outra."
  },
  "Tácito, Anais XV,44": {
    titulo: "Tácito, Anais XV,44 (c. 116 d.C.)",
    tipo: "outra",
    versos: [{t:"Para dissipar o boato, Nero apresentou como culpados, e puniu com os mais requintados suplícios, aqueles a quem o povo chamava de cristãos, detestados por suas abominações."},{t:"O autor desse nome, Cristo, fora executado sob o reinado de Tibério pelo procurador Pôncio Pilatos; reprimida por algum tempo, a perniciosa superstição irrompia de novo, não apenas na Judeia, origem do mal, mas também em Roma."},{t:"Foram primeiro presos os que confessavam; depois, por denúncia destes, uma imensa multidão, condenada menos pelo incêndio do que pelo ódio ao gênero humano."},{t:"Daí nascia a compaixão, ainda que se tratasse de culpados merecedores de castigo exemplar: porque pereciam não pelo bem público, mas pela crueldade de um só homem."}],
    comentario: "A menção mais valiosa entre as fontes romanas: hostil, independente dos Evangelhos e coerente com eles no essencial — um homem executado por Pilatos no reinado de Tibério, com seguidores que reapareceram depois. O título procurador é anacrônico (Pilatos foi prefeito, como mostra a inscrição de Cesareia), sinal de que Tácito usou o vocabulário administrativo de sua própria época."
  },
  "Josefo, Antiguidades XVIII,63-64 e XX,200": {
    titulo: "Josefo, Antiguidades Judaicas XVIII,63-64 (o Testimonium Flavianum)",
    tipo: "outra",
    versos: [{t:"Por esse tempo viveu Jesus, homem sábio — se é que se deve chamá-lo homem —, pois realizava feitos admiráveis e era mestre daqueles que recebem a verdade com prazer."},{t:"Atraiu a si muitos judeus e muitos gregos. Ele era o Cristo."},{t:"E, quando Pilatos, por denúncia dos principais entre nós, o condenou à cruz, os que antes o amavam não deixaram de amá-lo. Pois lhes apareceu ao terceiro dia, vivo de novo, como os divinos profetas haviam anunciado, junto com milhares de outras maravilhas a seu respeito."},{t:"E até hoje não desapareceu a tribo dos cristãos, assim chamada a partir dele."}],
    comentario: "As frases “se é que se deve chamá-lo homem”, “ele era o Cristo” e a menção à ressurreição são consideradas acréscimos cristãos por praticamente todos os especialistas — um judeu praticante não escreveria isso. O consenso majoritário é que existia um núcleo autêntico, ampliado por copistas; uma versão árabe do século X, citada pelo bispo Agápio, preserva forma bem mais sóbria."
  },
  "Josefo, Antiguidades XX,200": {
    titulo: "Josefo, Antiguidades Judaicas XX,200 (a morte de Tiago, 62 d.C.)",
    tipo: "outra",
    versos: [{t:"Anano, julgando ter ocasião favorável porque Festo havia morrido e Albino ainda estava a caminho, convocou o conselho dos juízes."},{t:"Trouxe diante dele o irmão de Jesus, chamado Cristo, cujo nome era Tiago, e alguns outros; e, acusando-os de terem transgredido a lei, entregou-os para serem apedrejados."},{t:"Mas os cidadãos que passavam por mais moderados e mais rigorosos na observância da lei ficaram indignados com isso, e o rei destituiu Anano do sumo sacerdócio."}],
    comentario: "Passagem considerada autêntica por quase todos os especialistas, sem sinal de interpolação: o texto não elogia Jesus nem os cristãos, e identifica Tiago pelo parentesco de forma quase incidental. É uma das melhores provas externas da existência histórica de Jesus — e mostra que a comunidade de Jerusalém ainda era liderada por um parente próximo."
  },
  "Josefo, Antiguidades XVIII,116-119": {
    titulo: "Josefo, Antiguidades Judaicas XVIII,116-119 (João Batista)",
    tipo: "outra",
    versos: [{t:"Alguns judeus julgavam que a destruição do exército de Herodes viera de Deus, como castigo pelo que ele fizera a João, chamado o Batista."},{t:"Pois Herodes o matou, embora fosse homem bom, que exortava os judeus a praticar a virtude, a agir com justiça uns com os outros e com piedade para com Deus, e assim a receber o batismo."},{t:"Quando muitos outros se reuniram em torno dele, pois se comoviam ao ouvi-lo, Herodes temeu que tamanha influência sobre o povo pudesse levar a alguma revolta — parecia que fariam qualquer coisa que ele aconselhasse."},{t:"Por isso julgou melhor prendê-lo antes que algo acontecesse, e mandou-o em cadeias para Maquerus, onde foi morto."}],
    comentario: "Josefo descreve João sem qualquer ligação com Jesus, o que confirma a existência independente do movimento batista. A explicação que dá para a execução é política — medo de revolta —, enquanto os Evangelhos apontam a denúncia do casamento de Antipas com Herodias. As duas razões não se excluem, e o lugar da prisão, a fortaleza de Maquerus, é dado só por ele."
  },
  "Plínio, Cartas X,96": {
    titulo: "Plínio, o Jovem, Cartas X,96 (c. 112 d.C.)",
    tipo: "outra",
    versos: [{t:"Afirmavam que toda a sua culpa, ou erro, consistia em reunir-se habitualmente em dia determinado, antes do amanhecer, e cantar entre si, alternadamente, um hino a Cristo como a um deus;"},{t:"e em obrigar-se por juramento não a algum crime, mas a não cometer furto, nem roubo, nem adultério, a não faltar à palavra dada nem negar um depósito quando reclamado."},{t:"Feito isso, costumavam separar-se e voltar a reunir-se para tomar alimento — comum e inocente, no entanto."},{t:"Não encontrei senão uma superstição desmedida e extravagante. Por isso, adiando a instrução do processo, recorro a ti para pedir conselho."}],
    comentario: "Um governador romano descrevendo, sem simpatia alguma, o que apurou sob interrogatório: reunião antes do amanhecer, hino a Cristo “como a um deus”, compromisso ético e refeição comum. É o testemunho externo mais antigo sobre a prática cristã — e mostra que o culto a Cristo como divino já existia por volta de 112, dois séculos antes de Niceia."
  },
  "Suetônio, Vida de Cláudio 25": {
    titulo: "Suetônio, Vida de Cláudio 25 (c. 121 d.C.)",
    tipo: "outra",
    versos: [{t:"Expulsou de Roma os judeus que, por instigação de Chrestus, provocavam distúrbios contínuos."}],
    comentario: "Uma frase só, e ambígua: Chrestus era nome comum de escravos, e Suetônio pode ter confundido as coisas. Ainda assim, o dado combina com Atos 18,2, que explica a chegada de Áquila e Priscila a Corinto pela expulsão ordenada por Cláudio — provavelmente em 49 —, o que sugere disputas sobre Cristo dentro da comunidade judaica de Roma."
  },
  "Alcorão 19,16-34": {
    titulo: "Alcorão, sura 19 (Maryam), versículos 16-34 — trecho",
    tipo: "outra",
    versos: [{t:"E menciona Maryam no Livro, quando se afastou de sua família para um lugar a oriente."},{t:"As dores do parto a levaram ao tronco de uma tamareira. Disse ela: “Quem me dera ter morrido antes disto e ser coisa esquecida!”"},{t:"Então uma voz a chamou de baixo: “Não te aflijas; teu Senhor fez correr um riacho a teus pés. Sacode em tua direção o tronco da tamareira, e ela deixará cair sobre ti tâmaras frescas e maduras. Come, bebe e alegra os teus olhos.”"},{t:"Ela veio ao seu povo, levando a criança. Disseram: “Ó Maryam, trouxeste algo espantoso!” Ela apontou para o menino. Disseram: “Como falaremos com uma criança de berço?”"},{t:"Disse ele: “Sou o servo de Deus. Ele me concedeu o Livro e fez de mim um profeta; abençoado onde quer que eu esteja, e me ordenou a oração e a caridade enquanto eu viver.”"}],
    comentario: "Tradução livre de um trecho da única sura do Alcorão com nome de mulher. O nascimento é milagroso — sem pai, sob a tamareira, no deserto —, mas a primeira fala do recém-nascido encerra qualquer leitura de divindade: ele se apresenta como servo e profeta. Elementos como a palmeira que alimenta a mãe circulavam antes em textos cristãos orientais, como o Evangelho do Pseudo-Mateus."
  },
  "Alcorão 3, 4, 5, 19, 43": {
    titulo: "Alcorão — trechos sobre Isa (Jesus)",
    tipo: "outra",
    versos: [{t:"Sura 4,157: “E por dizerem: ‘Matamos o Messias, Jesus, filho de Maria, o mensageiro de Deus’ — não o mataram nem o crucificaram, mas assim lhes pareceu. Os que discordam a respeito disso estão em dúvida; não têm conhecimento algum, apenas seguem conjecturas. Com certeza não o mataram.”"},{t:"Sura 4,158: “Ao contrário, Deus o elevou até Si; e Deus é poderoso, sábio.”"},{t:"Sura 3,45: “Quando os anjos disseram: ‘Ó Maria, Deus te anuncia a boa nova de uma palavra vinda dele: seu nome é o Messias, Jesus, filho de Maria, ilustre neste mundo e no outro.’”"},{t:"Sura 5,72-73: “Descreram os que dizem que Deus é o Messias, filho de Maria… Descreram os que dizem que Deus é o terceiro de três; não há divindade além do Deus único.”"},{t:"Sura 3,49: “E o farei mensageiro aos filhos de Israel: ‘Eu vos trago um sinal de vosso Senhor: modelo do barro a forma de um pássaro, sopro nele, e ele se torna pássaro, com a permissão de Deus.’”"}],
    comentario: "Tradução livre de trechos que resumem a posição islâmica: Isa é profeta e Messias, nascido de virgem, autor de milagres por permissão de Deus — mas não é Deus nem filho de Deus, e não morreu na cruz. O pássaro de barro que ganha vida vem do Evangelho da Infância de Tomé, texto cristão apócrifo do século II, o que mostra o repertório compartilhado no Oriente antes do século VII."
  },
  "Sanhedrin 43a": {
    titulo: "Talmude da Babilônia, Sanhedrin 43a — trecho",
    tipo: "outra",
    versos: [{t:"Na véspera de Pessach penduraram Yeshu."},{t:"E o arauto saiu diante dele durante quarenta dias, dizendo: “Ele será apedrejado, porque praticou feitiçaria, seduziu Israel e o desviou. Quem tiver algo a dizer em sua defesa, venha e o diga.”"},{t:"E, como não acharam nada em sua defesa, penduraram-no na véspera de Pessach."}],
    comentario: "Tradução livre de uma passagem que só existe em manuscritos não censurados — edições europeias do Talmude a suprimiram por medo de represálias. O texto foi redigido séculos depois dos fatos, em outro contexto, e vale como polêmica tardia, não como crônica: muitos estudiosos judeus e cristãos discutem inclusive se o Yeshu aí mencionado é o Jesus dos Evangelhos."
  },
  "Credo niceno": {
    titulo: "Credo de Niceia (325) — trecho",
    tipo: "outra",
    versos: [{t:"Cremos em um só Deus, Pai todo-poderoso, criador de todas as coisas visíveis e invisíveis."},{t:"E em um só Senhor Jesus Cristo, Filho de Deus, gerado unigênito do Pai, isto é, da substância do Pai; Deus de Deus, luz da luz, Deus verdadeiro de Deus verdadeiro; gerado, não feito, consubstancial ao Pai, por quem todas as coisas foram feitas."},{t:"O qual, por nós, homens, e por nossa salvação, desceu, encarnou-se e se fez homem; padeceu e ressuscitou ao terceiro dia; subiu aos céus e virá julgar os vivos e os mortos."},{t:"E no Espírito Santo."}],
    comentario: "Tradução livre do texto aprovado em 325. A palavra decisiva é homoousios — consubstancial, “da mesma substância” —, termo não bíblico escolhido justamente porque Ário não poderia aceitá-lo. O trecho sobre o Espírito Santo, aqui reduzido a uma linha, só ganharia desenvolvimento no Concílio de Constantinopla, em 381, na versão que as igrejas rezam até hoje."
  },
};

window.JC.creditoBiblia = "Texto bíblico: tradução de João Ferreira de Almeida (domínio público).";
window.JC.creditoOutras = "Trecho em tradução livre, a partir do texto clássico.";
